(window.GIM_TS=window.GIM_TS||{})["Zevachim.1"]={"from":24,"a":[["\u0003כל\u0004 קרבן \u0003ש\u0004דמו \u0003אינו\u0004 נזרק \u0003על מזבח החיצון כשלמים אין בו משום פיגול,\u0004 ולפיכך אין כלל דין פיגול בחטאות הפנימיות!","\u0003אלא\u0004 צריך לומר כך: \u0003הא והא\u0004 \u0005[זו וזו],\u0006 שתי הברייתות החלוקות בעניין פיגול בטבילת אצבע, הן כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 הסבורים שיש פיגול גם בחטאות הפנימיות. \u0003ולא קשיא\u0004 \u0005[ואינו קשה]:\u0006 \u0003כאן\u0004 שאמרו שאין פיגול בטבילת אצבע, מדובר \u0003בחטאות החיצונות,\u0004 שאף בהן יש טבילה באצבע לצורך נתינת הדם באצבע על קרנות המזבח, \u0003כאן\u0004 שאמרו שיש פיגול — \u0003בחטאות הפנימיות.\u0004","ושואלים: \u0003חטאות החיצונות פשיטא\u0004 \u0005[פשוט]\u0006 שכן הוא, ואין צורך להשמיענו, שהרי \u0003לא כתיב בהו\u0004 \u0005[נאמר בהם]\u0006 \u0003\"וטבל\"\u0004 כמו בפנימיות, ואם כן אינה נחשבת עבודה לפגל בה!","ומשיבים: \u0003אצטריך\u0004 \u0005[הוצרך]\u0006 הדבר להיאמר, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[עולה\u0006 היה \u0005על דעתך לומר]:\u0006 \u0003הואיל וכתיב\u0004 \u0005[ונאמר]\u0006 בהן: \u0003\"ולקח\u0004 הכהן מדם החטאת באצבעו\" (ויקרא ד, לד), \u0003ואי אתי\u0004 \u0005[ואם בא]\u0006 \u0003קוף רמי להו אידיה\u0004 \u0005[ומניח אותם\u0006 את הדם \u0005על ידו\u0006 של הכהן\u0005]\u0006 \u0003בעי למישקל זימנא אחריתי\u0004 \u0005[צריך ליטול\u0006 דם מן הכלי \u0005פעם אחרת]\u0006 משום שהוא מצווה לעשות זאת בעצמו, אם כן \u0003כמאן דכתיב\u0004 \u0005[כמו שנכתב]\u0006 \u0003\"וטבל\" דמי\u0004 \u0005[נחשב],\u0006","\u0003[קא משמע לן\u0004 \u0005[משמיע לנו]\u0006\u0003]\u0004 כי \u0003להכי לא כתיב\u0004 \u0005[משום כך לא כתוב]\u0006 בהן \u0003\"וטבל\"\u0004 אלא \"ולקח\", שבאופן זה \u0003משמע הכי\u0004 \u0005[כך]\u0006 שאין זו עבודה חשובה לפגל בה, \u0003ומשמע הכי\u0004 \u0005[כך],\u0006 שהדבר הוא מצוה.","שנינו במשנה ש\u0003ר' שמעון מכשיר\u0004 מחשבה לא ראויה \u0003בהילוך,\u0004 משום שהוא עבודה שאפשר בלעדיה. \u0003אמר ר' שמעון בן לקיש: מודה ר' שמעון בהולכת חטאות הפנימיות\u0004 (שמזים מדמם בתוך ההיכל) \u0003שמחשבה\u0004 לא ראויה \u0003פוסלת בהו\u0004 \u0005[בהם],\u0006 ומדוע? \u0003הואיל ו\u0004היא \u0003עבודה שאין יכול לבטלה,\u0004 שהרי אינו יכול לשחוט את הקרבן בפנים, ונמצא שהוא מוכרח להוליך את הדם ממקום השחיטה להיכל.","ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' שמעון: כל\u0004 קרבן \u0003ש\u0004דמו \u0003אינו\u0004 נזרק \u0003על מזבח החיצון כשלמים\u0004 אלא בתוך ההיכל, \u0003אין חייבין עליו\u0004 במחשבת חוץ לזמנו \u0003משום פיגול!\u0004","\u0003אמר ר' יוסי בר' חנינא:\u0004 אף על פי שהוא סבור שאין בזה פיגול, ואינו חייב על כך כרת, מכל מקום \u0003מודה היה\u0004 ר' שמעון שיש בכך \u0003לפסול,\u0004 ודבר זה הוא למד \u0003מקל וחומר:\u0004 \u0003ומה\u0004 מחשבת \u0003שלא לשמן שהוכשרו בשלמים\u0004 — \u0003פסול בחטאת,\u0004 כפי ששנינו בתחילת פרק זה, מחשבת \u0003חוץ לזמנו שפוסל בשלמים\u0004 — \u0003אינו דין שיפסול בחטאות?\u0004","ושואלים: \u0003ואשכחן\u0004 \u0005[ומצאנו]\u0006 לר' שמעון שהמחשבה \u0003חוץ לזמנו\u0004 פוסלת בהולכת חטאות פנימיות, מחשבת \u0003חוץ למקומו מנלן\u0004 \u0005[מנין לנו]?\u0006","\u0003אי\u0004 \u0005[אם]\u0006 תאמר שהוא לומד \u0003מ\u0004מחשבת \u0003חוץ לזמנו,\u0004 יש לדחות: \u0003מה לחוץ לזמנו שכן\u0004 יש בו בדרך כלל חיוב \u0003כרת!\u0004","\u0003אי\u0004 \u0005[אם]\u0006 תאמר שהוא לומד את זה \u0003מ\u0004מחשבת \u0003שלא לשמה\u0004 — יש לדחות: מה דין שלא לשמה \u0003שכן נוהג בבמה\u0004 בזמן שהבמות היו מותרות, ואין הדין כן במחשבה חוץ למקומו!","את הטענה האחרונה דוחים: דין \u0003שלא לשמן\u0004 שפוסל את הקרבן \u0003במאי\u0004 \u0005[במה,\u0006 באיזה קרבן\u0005]\u0006 הוא \u0003נוהג? בפסח וחטאת,\u0004 והרי \u0003פסח וחטאת\u0004 \u0003בבמה לא קרבו\u0004 כלל, ולפיכך אין להקשות מדברים שנהגו בבמה. ונמצא שאכן יש ללמוד פסול חוץ למקומו בחטאות הפנימיות מן הפסול של שלא לשמה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 יש ללמוד פסול חוץ למקומו מדין חוץ \u0005לזמנו. ומה שדחינו שדין חוץ לזמנו חמור, שיש בו כרת —\u0006 אין זו דחיה, כי דבר זה \u0003הקישא\u0004 \u0005[היקש]\u0006 \u0003הוא,\u0004 שבפסוק שלמדים ממנו את הפיגול: \"ואם האכל יאכל מבשר זבח שלמיו ביום השלישי לא ירצה, המקריב אתו לא יחשב לו פגול יהיה\" (ויקרא ז, יח) דרשו חכמים: \"ביום ה\u0003שלישי\u0004 לא ירצה\" — \u0003זה\u0004 מחשבה \u0003חוץ לזמנו,\u0004 \"לא יחשב לו \u0003פיגול\u0004 יהיה\", שהוא מיותר — \u0003[זה]\u0004 מחשבה \u0003חוץ למקומו.\u0004 ודבר שנלמד בהיקש — אין מקשים עליו.","\u0003אמר רבא: אם תימצי\u0004 \u0005[תרצה]\u0006 \u0003לומר\u0004 ש\u0003ר'\u0004 \u0003שמעון סבר לה כבריה\u0004 \u0005[סבור הוא כבנו],\u0006 ר' אלעזר בר' שמעון, ש\u0003אמר\u0004 כי השטח \u0003בין האולם ולמזבח צפון\u0004 הוא, ולפיכך ראוי לשחיטת חטאות, \u0003אין מחשבה\u0004 פסולה \u0003מועלת\u0004 ופוסלת \u0003בהולכת\u0004 דם \u0003חטאות הפנימיות אלא\u0004 כשחשב מחשבה פסולה בזמן שהוליך \u0003מפתח אולם ולפנים,\u0004 אבל לא כשהוליך מחוץ לשטח זה, משום שאין הכרח להלך שם, שהרי יכול היה לשחוט על פתח האולם.","\u0003ואם תמצי\u0004 \u0005[תרצה]\u0006 \u0003לומר סבר לה\u0004 \u0005[שהוא סבור]\u0006 \u0003כר' יהודה, דאמר\u0004 \u0005[שאומר]:\u0006 \u0003תוך עזרה מקדש,\u0004 שלרצפת העזרה יש דין מזבח להקטיר עליה, \u0003אין מחשבה\u0004 פסולה \u0003מועלת\u0004 ופוסלת \u0003בהולכת סילוק בזיכין\u0004 של לבונה, שהם מתירים את לחם הפנים באכילה כשמקטירים אותם, \u0003אלא\u0004 בזמן שמוליך אותם \u0003מפתח היכל\u0004 דרך האולם \u0003ולחוץ,\u0004 עד שמגיע לעזרה, לפי שאת השולחן ניתן להניח בכל מקום בהיכל, והעזרה כולה כשרה להקטרת הבזיכים.","\u0003ואם תמצי\u0004 \u0005[תרצה]\u0006 \u0003לומר סבר\u0004 \u0005[\u0006שהוא \u0005סבור]\u0006 גם: \u0003קדושת היכל ואולם חדא\u0004 \u0005[אחת]\u0006 \u0003היא,\u0004 ולפיכך אפשר מן הדין להניח את שולחן הלחם גם באולם — \u0003אין מחשבה מועלת אלא מפתח אולם ולחוץ\u0004 כלומר, כשמוליך בתוך חלל פתח האולם עד שמגיע לעזרה שדינה כמזבח.","\u0003ואם תמצי\u0004 \u0005[תרצה]\u0006 \u0003לומר\u0004 שהוא סבור גם: \u0003תוך הפתח כלפנים\u0004 שיכול להניח את השולחן אפילו שם — \u0003אין מחשבה מועלת אפילו פסיעה אחת, אלא בכדי הושטת ידו\u0004 שיניח את הבזיכים מידו על רצפת העזרה.","\u0003ואם תמצי\u0004 \u0005[תרצה]\u0006 \u0003לומר\u0004 גם \u0003סבר\u0004 \u0005[שסבור]\u0006 ר' שמעון: \u0003הולכה שלא ברגל לא שמה\u0004 (אינה נחשבת) \u0003הולכה,\u0004 נמצא ש\u0003אין מחשבה מועלת כלל\u0004 בהולכת סילוק בזיכים.","ועוד לענין הולכה מסופר, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לאמוריה\u0004 \u0005[למתורגמנו]\u0006 של \u0003רב חסדא, בעי מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003מרב חסדא: הולכה בזר\u0004 (מי שאינו כהן), \u0003מהו?\u0004 האם היא פוסלת, כמו שאר עבודות?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כשרה\u0004 היא, \u0003ומקרא מסייעני\u0004 שנאמר: \u0003\"וישחטו את הפסח ויזרקו הכהנים את הדם מידם והלוים מפשיטים\"\u0004 (דברי הימים ב לה, יא). משמע שעבודת הכהנים ההכרחית מתחילה רק בזריקה, ולא בקבלה ובהולכה שלפני כן.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב ששת\u0004 ממה ששנינו בברייתא: \u0003זר, ואונן\u0004 (מי שמתו לא נקבר עדיין),"],["\u0003שיכור ובעל מום, בקבלה בהולכה בזריקה\u0004 — \u0003פסול, וכן\u0004 מי שהיה \u0003יושב\u0004 בשעת עבודות אלה, \u0003וכן\u0004 מי שעשה אותן ביד \u0003שמאל!\u0004 והרי זה \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על רב חסדא, שהרי בפירוש נאמר כאן שהולכה בזר פסולה.","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב חסדא\u0004 שהכשיר, \u0003קרא קאמר\u0004 \u0005[פסוק אמר]\u0006 כראיה, שהכהנים זרקו מיד הישראלים את הדם, וכיצד אפשר לדחות אותו כך?","ומשיבים: מדובר שם \u0003דעביד\u0004 \u0005[שעושה]\u0006 הישראל כ\u0003מעשה אצטבא\u0004 (מדף), שהיה הכהן נותן את הכלי בידו להחזיק בו, ואחר כך היה כהן נוטל ממנו את הכלי וזורק את הדם, ולא היה מוליך את הדם.","\u0003רבה ורב יוסף דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003הולכה בזר\u0004 — \u0003מחלוקת ר' שמעון ורבנן\u0004 \u0005[וחכמים]\u0006 במשנתנו, לדעת \u0003ר' שמעון\u0004 ש\u0003אמר: עבודה שאפשר לבטלה לאו\u0004 \u0005[לא]\u0006 \u0003עבודה היא\u0004 לפוסלה במחשבה — הולכה \u0003כשרה בזר,\u0004 שהרי אפשר לבטלה כששוחט בצד המזבח, \u0003לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים]\u0006 הסבורים שהיא עבודה, שהרי נפסלת במחשבה — הריהי \u0003פסולה\u0004 בזר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: והא\u0004 \u0005[והרי]\u0006 \u0003שחיטה\u0004 שהיא \u0003עבודה שאי אפשר לבטלה, ו\u0004בכל זאת \u0003כשרה בזר! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שחיטה לאו\u0004 \u0005[לא]\u0006 \u0003עבודה היא.\u0004","ותוהים: \u0003ולא?\u0004 האם אינה נחשבת כעבודה כלל? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' זירא אמר רב: שחיטת פרה\u0004 אדומה \u0003בזר\u0004 — \u0003פסולה, ואמר רב עלה\u0004 \u0005[עליה]:\u0006 מה המקור לכך? מפני שכתוב בה (במדבר פרק יט) \u0003\"אלעזר\u0004 הכהן\", \u0003ו\"חוקה\",\u0004 שמכאן למדים שאין לשנות \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003בה!\u0004","ודוחים: אין ללמוד מפרה אדומה, כי \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003פרה,\u0004 ש\u0003קדשי בדק הבית היא,\u0004 ואינה נחשבת כזבח.","ותוהים על כך: \u0003ולאו כל דכן\u0004 \u0005[ולא כל שכן]\u0006 \u0003הוא?\u0004 אם לגבי \u0003קדשי בדק הבית הויא\u0004 \u0005[הרי זו]\u0006 השחיטה \u0003עבודה,\u0004 לגבי \u0003קדשי מזבח לאו\u0004 \u0005[לא]\u0006 כל שכן ש\u0003עבודה היא?\u0004","\u0003אמר רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי,\u0004 לדחות את הקושיה: ייתכן דבר כזה, \u0003מידי דהוה\u0004 \u0005[כמו שהוא]\u0006 לגבי ראיית \u0003מראות נגעים,\u0004 כדי לטמא או לטהר, \u0003דלאו\u0004 \u0005[שלא]\u0006 \u0003עבודה היא, ו\u0004בכל זאת \u0003בעיא\u0004 \u0005[צריכה]\u0006 \u0003כהונה\u0004 ואי אפשר לעשותה על ידי זר. וחוזרים ומקשים על דברי רבה ורב יוסף לעיל: כיצד ניתן לומר שר' שמעון מכשיר הולכה בזר משום שלדעתו ניתן לבטלה?","\u0003והרי הולכת אברים לכבש,\u0004 ש\u0003עבודה שאפשר לבטלה היא,\u0004 שהרי יכול לשחוט את הקרבן סמוך לכבש, \u0003ו\u0004בכל זאת \u0003פסולה בזר, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והקריב הכהן את הכל [והקטיר] המזבחה\"\u0004 (ויקרא א, יג), \u0003ואמר מר\u0004 \u0005[החכם]:\u0006 הקרבה \u0003זו הולכת אברים לכבש!\u0004","ודוחים: \u0003היכא דגלי\u0004 — \u0003גלי\u0004 \u0005[במקום שגילה\u0006 הכתוב \u0003—\u0004 \u0005גילה],\u0006 \u0003והיכא\u0004 ש\u0003לא גלי\u0004 \u0005[גילה]\u0006 — \u0003לא גלי\u0004 \u0005[גילה],\u0006 ובהולכת דם לא נאמר במפורש שהיא עבודת כהן.","ושואלים: \u0003ולאו כל דכן\u0004 \u0005[ולא כל שכן]\u0006 \u0003הוא? ומה הולכת אברים לכבש דלא מעכבא\u0004 \u0005[שאינה מעכבת]\u0006 את ה\u0003כפרה,\u0004 שהרי גם אם לא יעלו האיברים למזבח כבר חלה הכפרה בזריקת הדם — בכל זאת \u0003בעיא\u0004 \u0005[צריכה]\u0006 \u0003כהונה, הולכת דם דמעכבא\u0004 \u0005[שמעכבת]\u0006 \u0003כפרה\u0004 — \u0003[לא כל שכן]?\u0004 לכך לא ניתנה תשובה.","ומעירים: \u0003איתמר [נמי\u0004 \u0005[נאמר גם כן]\u0006\u0003]\u0004 ש\u0003אמר עולא אמר ר'\u0004 \u0003אלעזר: הולכה בזר פסולה אפילו ל\u0004דעת \u0003ר' שמעון.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם ללומדים]:\u0006 \u0003הולכה שלא ברגל\u0004 שלא הלך למזבח, אלא כגון שהעביר את מזרק הדם בידו, \u0003שמה הולכה או\u0004 \u0003לא שמה הולכה?\u0004","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא (בראש עמוד זה): \u0003וכן יושב וכן\u0004 עושה ביד \u0003שמאל\u0004 — \u0003פסול\u0004 בהולכה, ונדייק מכאן: \u0003הא\u0004 \u0005[אבל]\u0006 אם היה \u0003עומד דומיא דיושב\u0004 \u0005[בדומה ליושב],\u0006 שאינו זז ממקומו ומוליך בידו — \u0003כשר!\u0004","ודוחים: \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003יושב\u0004 שפסול כוונתו אפילו במקרה \u0003דקשייף מישף\u0004 \u0005[שמשתפשף\u0006 וזז מעט תוך כדי ישיבה בקרקע\u0005],\u0006 ולפי זה \u0003עומד\u0004 שכשר הוא \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003יושב\u0004 — \u0003דנייד פורתא\u0004 \u0005[שזז קצת],\u0006 ועל ידי כך מתקיימת בו מצות הולכה ברגל.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה מקרבן הפסח, ששנינו: \u0003שחט ישראל וקבל הכהן\u0004 את הדם בכלי, והכהנים היו עומדים בשורה ממקום השחיטה עד המזבח, \u0003נתנו\u0004 הכהן \u0003לחבירו וחברו לחבירו,\u0004 משמע שאין צריכים להוליך ברגל, אלא די בזה שמעבירים מיד ליד!","ודוחים: \u0003התם נמי דניידי פורתא\u0004 \u0005[שם גם כן\u0006 מדובר \u0005שהם זזים קצת\u0006 ברגליהם\u0005]\u0006 תוך כדי ההעברה. ושואלים: \u0003ומאי קא משמע לן\u0004 \u0005[ומה משמיע לנו]\u0006 התנא בתיאור זה של עבודת הפסח, אם לא ללמדנו שאין צורך בהולכה ברגל? ומשיבים: משמיע לנו ש\u0003\"ברב עם הדרת מלך\"\u0004 (משלי יד, כח) שכבוד שמים הוא שתיעשה עבודת ה' ברוב עם.","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו להלן: אם \u0003קבל\u0004 הכהן \u0003הכשר\u0004 את הדם בכלי \u0003ו\u0004מיד \u0003נתן\u0004 את הכלי \u0003לפסול\u0004 שהיה עומד סמוך למזבח — \u0003יחזיר\u0004 הפסול את הכלי \u0003לכשר\u0004 שנתן לו, כדי שיוליכו למזבח. ואם הולכה שלא ברגל הולכה — הרי כבר נעשתה ההולכה, כשנתן הכשר לפסול, ואין צורך אלא שכהן כשר יחזור ויקח את הכלי מיד הפסול!","ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 ותקן את הנוסח: \u0003יחזור הכשר ויקבלה,\u0004 ואין צורך בהולכה ברגל.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 ש\u0003אמר עולא אמר ר' יוחנן: הולכה שלא ברגל לא שמה\u0004 \u0005[אינה נחשבת]\u0006 ל\u0003הולכה.\u0004"],["ושואלים: הולכה שנעשתה שלא ברגל, האם \u0003אפשר לתקונה\u0004 \u0005[\u0006לחזור ו\u0005לתקנה]\u0006 אם \u0005יוליך מחדש כראוי,\u0006 \u0003או לא אפשר לתקונה\u0004 \u0005[לתקנה]?\u0006","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003קבל הכשר ונתן\u0004 מידו \u0003ל\u0004ידיו של \u0003פסול\u0004 — \u0003יחזיר לכשר.\u0004 הרי שאפשר לתקן את ההולכה הראשונה שנעשתה שלא ברגל.","\u0003ונהי נמי\u0004 \u0005[ואם גם כן]\u0006 אתה אומר שאין צורך להחזיר לראשון, אלא, כפי שהצענו בעמוד הקודם, ש\u0003יחזור הכשר ויקבלנו\u0004 ויזרקנו על המזבח, מכל מקום \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 שהולכה שאינה ראויה \u0003לא אפשר\u0004 יותר \u0003לתקונה\u0004 \u0005[לתקנה]\u0006 — הרי \u0003איפסלא לה\u0004 \u0005[נפסלה]\u0006 בהולכה הראשונה!","ומשיבים: \u0003מי סברת דקאי זר גואי\u0004 \u0005[האם סבור אתה ש\u0006מדובר כאן כאשר \u0005עומד הזר בפנים]\u0006 קרוב יותר למזבח מן המקבל, וכאשר נתנו הכשר לפסול עשה מקצת עבודת ההולכה? \u0003לא,\u0004 מדובר \u0003דקאי זר בראי\u0004 \u0005[שעומד הזר בחוץ]\u0006 רחוק יותר מן המזבח, ונמצא שהכשר שנתן לו לא עשה כלל הולכה למזבח, שהרי הרחיק את הדם מן המזבח.","ומביאים ראיה ממה ש\u0003איתמר\u0004 \u0005[נאמר]\u0006 כך: \u0003אמר עולא אמר ר' יוחנן: הולכה שלא ברגל\u0004 — \u0003פסולה. אלמא\u0004 \u0005[מכאן]\u0006 ממה שהשתמש בלשון פסולה (ולא כדבריו לעיל \"לא שמה הולכה\") משמע ש\u0003לא אפשר לתקונה\u0004 \u0005[לתקנה].\u0006","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב נחמן לעולא\u0004 ממה ששנינו במשנה: \u0003נשפך\u0004 הדם \u0003מן הכלי על הרצפה ואספו\u0004 שוב לכלי — \u0003כשר,\u0004 משמע שלמרות שהדם נשפך (גם) לכיוון המזבח אפשר לתקן עבודה זו!","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כשיצא\u0004 הדם \u0003לחוץ\u0004 כשנשפך, ולא לעבר המזבח, ולא היתה כאן הולכה.","ותוהים: וכי דם שנשפך \u0003לבראי נפיק לגואי לא עייל\u0004 \u0005[לחוץ הוא יוצא לפנים לא נכנס]?\u0006 הרי ברור שכאשר נשפך דם הוא מתפזר לכל צד! ומשיבים: מדובר \u0003במקום מדרון\u0004 שהדם נשפך לצד אחד, מן המזבח ולחוץ. \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 מדובר שנשפך הדם \u0003בגומא,\u0004 שלא יצא למקום אחר. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 מדובר \u0003בסמיכא\u0004 \u0005[\u0006בדם \u0005סמיך],\u0006 שלא נשפך לכל צד.","ותוהים: \u0003ואיכפל תנא לאשמועינן כל הני\u0004 \u0005[ו\u0006כי \u0005התאמץ התנא להשמיע אותנו כל אלה]\u0006 שהם מקרים נדירים? \u0003ועוד\u0004 יש להקשות: \u0003אדתני באידך פירקין\u0004 \u0005[עד שהוא שונה בפרק האחר שלנו\u0006 במסכת זו\u0005]:\u0006 \u0003נשפך\u0004 הדם מצואר הבהמה \u0003על הרצפה\u0004 ולא נכנס לכלי, \u0003ואספו\u0004 — \u0003פסול, ליפלוג בדידיה\u0004 \u0005[שיחלק בו עצמו]\u0006 בדם שנשפך מן הכלי, ויאמר כך: \u0003במה דברים אמורים\u0004 שהוא כשר? \u0003כשיצא\u0004 הדם \u0003לחוץ, אבל נכנס לפנים\u0004 — \u0003פסול!\u0004 ומסכמים, \u0003הרי זו\u0004 \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על דברי עולא בשם ר' יוחנן, ונדחו דבריו.","\u0003אתמר\u0004 \u0005[נאמר]:\u0006 \u0003הולכה שלא ברגל\u0004 האם הולכה היא או לא — \u0003מחלוקת ר' שמעון ורבנן\u0004 \u0005[וחכמים]\u0006 במשנתנו היא, האם מחשבה פוסלת בהולכה כזו. ומסבירים את הדברים: \u0003בהולכה רבתי\u0004 \u0005[גדולה]\u0006 שמוליך ברגליו את הדם למזבח \u0003—\u0004 \u0003דכולי עלמא לא פליגי\u0004 \u0005[הכל אינם חולקים]\u0006 שהיא \u0003פסולה, כי פליגי\u0004 \u0005[כאשר הם חולקים]\u0006 הרי זה \u0003בהולכה זוטרתי\u0004 \u0005[קטנה]\u0006 ששחט סמוך למזבח ממש, שר' שמעון סבור שאינה הולכה, ולכן אין מחשבה פוסלת בה, וחכמים פוסלים.","\u0003מחכו עלה במערבא\u0004 \u0005[צחקו על כך בארץ ישראל],\u0006 \u0003אלא\u0004 לפי זה, \u0003חטאת העוף,\u0004 הנמלקת סמוך למזבח וכשהוא אוחזה מזה מדמה על קיר המזבח, שנאמר ש\u0003פסולה בה מחשבה\u0004 בהזאת דמה, \u0003ל\u0004דעת \u0003ר' שמעון היכי משכחת לה\u0004 \u0005[איך אתה מוצא אותה]?\u0006 כי \u0003אי דחשיב עלה מקמי דליפוק\u0004 \u0005[אם ש\u0006הוא \u0005חושב עליה,\u0006 כשהוא מקרב את גופה למזבח, \u0005לפני שיוצא]\u0006 ה\u0003דם\u0004 — \u0003לא כלום היא,\u0004 שהרי לדעתו הולכה שלא ברגל היא, שאינה נחשבת כלל עבודה. \u0003ואי בתר דנפק\u0004 \u0005[ואם אחרי שיצא]\u0006 ה\u0003דם\u0004 מן הצואר — הרי \u0003איתעבידא ליה\u0004 \u0005[\u0006כבר \u0005נעשתה לו]\u0006 \u0003מצותו\u0004 שכבר הוזה הדם!","ומשיבים: \u0003מאי קושיא\u0004 \u0005[מה הקושיה]?\u0006 \u0003דלמא מדפריש ועד דמטא\u0004 \u0005[שמא\u0006 מזמן \u0005שפרש\u0006 הדם מן העוף \u0005עד שהגיע\u0006 בפועל\u0003]\u0004 \u0003למזבח,\u0004 זה הוא הזמן הנחשב כזמן ההזאה ובו פוסלת מחשבה!","וראיה לדבר שמשך זמן זה פוסל, \u0003דהא בעא מיניה\u0004 \u0005[שהרי שאל אותו]\u0006 \u0003ר' ירמיה מר' זירא: היה\u0004 הכהן \u0003מזה\u0004 את הדם, \u0003ונקטעה ידו של מזה עד שלא הגיע דם לאויר המזבח, מהו?\u0004 האם ההזאה פסולה משום שהמזה הוא כעת בעל מום (ופוסל), או שמא שהדם כבר יצא בכשרות? \u0003ואמר ליה\u0004 \u0005[לו]:\u0006 \u0003[פסולה,\u0004 והסביר: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006\u0003]?\u0004 כי \u0003\"והזה... ונתן\" בעינן\u0004 \u0005[צריכים אנו],\u0006 ששתי פעולות אלו נכתבו בסמוך (ראה ויקרא ד, ו—ז), כדי להקישן זו לזו, ללמדנו שהזאה כמו נתינה, נגמרת על המזבח. ואם כן, פוסלת המחשבה בשלב זה!","\u0003כי אתו\u0004 \u0005[כאשר באו]\u0006 \u0003רב פפא ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע מבי רב\u0004 \u0005[מבית רבם],\u0006 \u0003אמרי\u0004 \u0005[אמרו]\u0006 הסבר אחר לדברים: \u0003היינו חוכא\u0004 \u0005[זהו\u0006 עניינו של \u0005הצחוק\u0006 שצחקו\u0005]\u0006 בארץ ישראל: \u0003ו\u0004כי \u0003בהולכה רבתי\u0004 \u0005[גדולה]\u0006 \u0003לא פליגי\u0004 \u0005[חולקים]\u0006 ר' שמעון וחכמים? \u0003והא כי פליגי\u0004 \u0005[והרי כאשר חולקים]\u0006 ר' שמעון וחכמים במשנה, \u0003בהולכה רבתי\u0004 \u0005[גדולה]\u0006 \u0003פליגי\u0004 \u0005[\u0006הם \u0005חולקים],\u0006 שהרי ר' שמעון מנמק את דבריו שם בכך שאפשר בלא הילוך, ומכאן שמדובר שם במקרה שמהלך!","\u0003אלא\u0004 כך צריך לומר: \u0003בהולכה זוטרתי\u0004 \u0005[קטנה]\u0006 \u0003כולי עלמא לא פליגי דלא פסלה\u0004 \u0005[הכל אינם חלוקים שאין\u0006 המחשבה \u0005פוסלת],\u0006 \u0003כי פליגי\u0004 \u0005[כאשר\u0006 הם \u0005חלוקים]\u0006 — הרי זה \u0003בהולכה רבתי\u0004 \u0005[גדולה]\u0006 שמוליכה מרחק ניכר, וחכמים פוסלים אף שאפשר לבטלה.","דם אשר \u0003הוליכו זר, והחזירו כהן\u0004 למקום שהיה בו הדם מלכתחילה, \u0003וחזר\u0004 הכהן \u0003והוליכו\u0004 למזבח — \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה בני רבי חייא ור' ינאי, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: כשר, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: פסול.\u0004 ויסוד המחלוקת, \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 המתיר, \u0005סבור]:\u0006 \u0003אפשר לתקונה\u0004 \u0005[לתקנה],\u0006 שהולכה שלא נעשתה כראוי אפשר לתקן בהולכה ראויה. \u0003ומר סבר\u0004 \u0005[וחכם זה\u0006 שפוסל \u0005סבור]:\u0006 \u0003לא אפשר לתקונה\u0004 \u0005[לתקנה]\u0006 אם מתחילה נעשתה בפסול.","ושואלים: אם \u0003הוליכו כהן והחזירו, וחזר והוליכו זר,\u0004 מה יהיה הדין? \u0003אמר רב שימי בר אשי: לדברי המכשיר\u0004 בהוליכו זר והחזירו והוליכו כהן — הרי זה \u0003פסול,\u0004 שהרי הולכה אחרונה נעשתה בפסול. \u0003לדברי הפוסל\u0004 שם, לפי שהולכה ראשונה נעשתה בפסול — הרי הוא \u0003מכשיר\u0004 במקרה זה, שהולכה ראשונה נעשתה כראוי.","\u0003רבא אמר: אף לדברי הפוסל\u0004 כשהוליכו הזר בתחילה — \u0003פסול\u0004 במקרה זה, שהוליכו כהן וחזר והוליכו הזר, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003צריך\u0004"],["\u0003לאמטוייה\u0004 \u0005[להביא אותו]\u0006 להוליך את הדם כדי לזורקו על המזבח. ודבר זה שאי אפשר בלעדיו — בוודאי לא יכול הזר לעשותו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה לרב אשי, הכי\u0004 \u0005[כך]\u0006 \u0003אמר\u0004 \u0003רב ירמיה מדיפתי: הא\u0004 \u0005[זה]\u0006 ההנחה שמה ש\u0003צריך לאמטוייה\u0004 \u0005[להביא אותו]\u0006 את הדם כדי לזורקו הוא הילוך הנחשב כעבודה — היא ה\u0003מחלוקת\u0004 בין \u0003ר' אליעזר ורבנן\u0004 \u0005[וחכמים]\u0006 במשנתנו.","\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנתנו\u0005],\u0006 \u0003ר' אליעזר אומר: המהלך במקום שצריך להלך\u0004 — \u0003מחשבה פוסלת,\u0004 המהלך ב\u0003מקום שאין צריך להלך\u0004 — \u0003אין מחשבה פוסלת.\u0004","\u0003ואמר רבא\u0004 על כך: \u0003הכל מודים,\u0004 אם \u0003קבלו\u0004 את הדם \u0003בחוץ\u0004 כלומר, רחוק מן המזבח, \u0003והכניסו בפנים\u0004 כלומר, קירבו אל המזבח — \u0003זהו\u0004 \u0003הילוך שצריך להלך.\u0004 אם \u0003קבלו בפנים\u0004 סמוך למזבח \u0003והוציאו לחוץ\u0004 הרחיקו מן המזבח — \u0003זהו הילוך שאין צריך להלך.\u0004","\u0003לא נחלקו אלא כשהכניסו וחזר והוציאו,\u0004 ועכשיו הוא חוזר ומכניסו, \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 תנא קמא, \u0005סבור]:\u0006 \u0003הא צריך לאמטוייה\u0004 \u0005[הרי צריך להביא אותו]\u0006 ולכן הילוך זה עבודה הוא, ומחשבה פוסלת בו. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' אליעזר, \u0005סבור]:\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003כהילוך הצריך לעבודה דמי\u0004 \u0005[הוא נחשב],\u0006 כיון שכבר נעשתה עבודת הקודש של הולכה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 מברייתא, \u0003ר' אליעזר אומר: המהלך מקום שצריך להלך\u0004 — \u0003מחשבה פוסלת, כיצד? קבלו בחוץ והכניסו לפנים\u0004 — \u0003זהו הילוך שצריך להלך, קבלו בפנים והוציאו לחוץ\u0004 — \u0003זהו הילוך שאין צריך לילך,\u0004 ונדייק: \u0003והא\u0004 \u0005[ואולם]\u0006 אם \u0003חזר והכניסו\u0004 — \u0003הילוך שצריך להלך הוא,\u0004 ומודה בו ר' אליעזר! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי תניא תניא\u0004 \u0005[אם שנויה\u0006 ברייתא \u0005שנויה]\u0006 וחוזר אני מדבריי.","","","\u0003כל הזבחים שקבלו דמן זר\u0004 מי שאינו כהן, או כהן \u0003אונן\u0004 (מי שמת מתו עליו ולא נקבר עדיין), \u0003טבול יום\u0004 מי שנטמא וטבל, ועדיין לא שקעה השמש ולא נטהר לגמרי, \u0003ומחוסר כפורים\u0004 כהן שנטהר לגמרי אלא שצריך להביא קרבן כפרה לשם השלמת טהרתו, כמו מצורע או זב לאחר היום השביעי לטהרתו, \u0003ומחוסר בגדים\u0004 כהן שלא היו עליו כל בגדי כהונה, או מי \u0003שלא רחץ ידים ורגלים\u0004 בכיור לפני העבודה, או כהן \u0003ערל,\u0004 או כהן \u0003טמא,\u0004 או שקיבל את הדם כשהוא \u0003יושב,\u0004 או שהיה \u0003עומד\u0004 לא על הרצפה אלא \u0003על גבי כלים,\u0004 או \u0003על גבי בהמה\u0004 או \u0003על גבי רגלי חברו\u0004 — בכל המקרים האלה העושה כן \u0003פסל\u0004 את הדם להקרבה. אם \u0003קבל ב\u0004יד \u0003שמאל\u0004 — \u0003פסל, ר' שמעון מכשיר.\u0004","","ומבררים: \u0003זר מנלן\u0004 \u0005[מנין לנו]\u0006 שהוא פוסל בעבודת קדש? \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003לוי:\u0004 נאמר בפתיחת רשימת הטומאות שצריך להיזהר מהן בקודש: \u0003\"דבר אל אהרן ואל בניו לאמר וינזרו מקדשי בני ישראל\u0004 ולא יחללו את שם קדשי\" (ויקרא כב, ב), ונברר: מה שנאמר \"קדשי \u0003בני ישראל\" למעוטי מאי\u0004 \u0005[למעט את מה\u0006 הוא בא\u0005]?\u0006 \u0003אילימא למעוטי\u0004 \u0005[אם תאמר למעט]\u0006 \u0003נשים\u0004 שהן בנות ישראל — וכי יעלה על הדעת כי \u0003קרבן נשים בטומאה קרב?\u0004","\u0003אלא\u0004 תאמר שהכוונה היא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003גוים\u0004 שקרבנם קרב בטומאה — גם זאת יש לדחות: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 בגוים גם \u0003ציץ לא מרצה\u0004 על טומאה של קודש, ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003ובגוים\u0004 — \u0003בין בשוגג בין במזיד\u0004 \u0003לא הורצה\u0004 לא עלה הקרבן לרצון על ידי הציץ, אם נתגלה בדיעבד שהיה טמא, וכי \u0003בטומאה\u0004 גמורה \u0003קרב?\u0004","\u0003אלא הכי קאמר\u0004 \u0005[כך אמר]\u0006 כך יש להבין את לשון הכתוב: \u0003\"וינזרו מקדשי, בני ישראל ולא יחללו\"\u0004 כלומר, הכהנים אליהם נאמר ציווי זה ינזרו מן הקדשים כשהם טמאים, וגם בני ישראל צריכים להינזר ולפרוש מעבודת הקדשים, כדי שלא יחללו אותם בעבודתם.","\u0003דבי\u0004 \u0005[בבית מדרשו]\u0006 של \u0003רבי ישמעאל תנא\u0004 \u0005[שנה]\u0006 כך: \u0003אתיא\u0004 \u0005[בא,\u0006 נלמד הדבר\u0005]\u0006 \u0003בקל וחומר מ\u0004כהן שהוא \u0003בעל מום, מה בעל מום שאוכל\u0004 בקדשים — בכל זאת \u0003אם עבד\u0004 בקודש \u0003חילל\u0004 את העבודה,"],["\u0003זר שאינו אוכל\u0004 בקדשי קדשים — \u0003אינו דין שאם עבד חילל?\u0004","ודוחים: \u0003מה לבעל מום\u0004 שיש בו צד חומרה, \u0003שכן עשה בו קרב כמקריב\u0004 שאף קרבן בעל מום פסול כדרך שפוסל בכהן!","ואומרים: אם כן \u0003טמא יוכיח,\u0004 שאינו שייך בקרבן אלא רק במקריב, ומחלל. ודוחים: \u0003מה לטמא\u0004 שיש בו חומרה אחרת, \u0003שכן מטמא\u0004 אחרים!","ומשיבים: \u0003בעל מום יוכיח\u0004 שאינו פוסל אחרים. \u0003וחזר הדין\u0004 מבעל מום לטמא, ואפשר ללמוד משניהם: \u0003לא ראי\u0004 (הרי) \u0003זה כראי זה ולא ראי זה כראי זה, הצד השוה שבהן שמוזהרין\u0004 שלא לעשות עבודה, \u0003ואם עבדו חיללו, אף אני אביא זר שהוא מוזהר, ו\u0004לפיכך \u0003אם עבד חילל.\u0004","ושואלים: ובאמת, \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שהזר \u0003מוזהר\u0004 שלא לעבוד? \u0003אי\u0004 \u0005[אם]\u0006 אתה אומר שלומדים דבר זה \u0003מ\u0004הפסוק \u0003\"וינזרו\"\u0004 (ויקרא כב, ב), ואתה מפרש שיש שם איסור לזרים לעבוד (כמבואר בעמוד הקודם), אם כן אין צורך בקל וחומר לומר שהוא מחלל עבודה, שהרי \u0003חילול בגופיה כתיב ביה\u0004 \u0005[בגופו כתוב בו]\u0006 \"ולא יחללו\"! \u0003אלא\u0004 יש לומר כי למדים דבר זה מ\"ושמרו את משמרת אהל מועד לכל עבודת האהל \u0003וזר לא יקרב אליכם\"\u0004 (במדבר יח, ד).","ומקשים: את הלימוד מבעל מום וטמא \u0003איכא למיפרך\u0004 \u0005[יש לפרוך]:\u0006 \u0003מה להצד השוה שבהן שכן\u0004 שניהם, בעל מום וטמא, \u0003לא הותרו בבמה\u0004 משנכנסו ישראל לארץ ולא היה משכן קבוע, והותר אז להקריב בבמה. מה שאין כן בזר המותר בבמה!","ואומרים: \u0003לא תימא\u0004 \u0005[אל תאמר]\u0006 \u0003טמא יוכיח\u0004 יחד עם בעל מום, \u0003אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003אונן יוכיח,\u0004 שגם הוא הוזהר שלא לעבוד, ומחלל את העבודה. ודוחים: \u0003מה לאונן שכן אסור ב\u0004אכילת \u0003מעשר\u0004 שני ולא רק בעבודה, כזר! ומשיבים: \u0003[בעל מום] יוכיח\u0004 שמותר במעשר.","\u0003וחזר הדין, לא ראי זה כראי זה, הצד השוה שבהן שמוזהרין כו'\u0004 שלא לעבוד ואם עבדו חיללו — אף זר שהוזהר כמותם, אם עבד — חילל.","ומקשים: \u0003הכא נמי לפרוך\u0004 \u0005[כאן גם כן נקשה]:\u0006 \u0003מה להצד השוה שבהן\u0004 בבעל מום ואונן \u0003שכן לא הותרו בבמה! מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב סמא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא: ומאן לימא לן\u0004 \u0005[ומי יאמר לנו]\u0006 ש\u0003אונן אסור בבמה? דלמא שרי\u0004 \u0005[שמא מותר]\u0006 \u0003בבמה!\u0004","\u0003רב משרשיא אמר\u0004 מקור אחר לדינו של זר: \u0003אתיא\u0004 \u0005[נלמד הדבר]\u0006 ב\u0003קל וחומר מ\u0004פסול של כהן העובד כשהוא \u0003יושב: מה יושב שאוכל\u0004 קדשים, \u0003אם עבד\u0004 כשהוא יושב — \u0003חילל, זר שאינו אוכל\u0004 — \u0003אינו דין שאם עבד חילל?\u0004","ודוחים: \u0003מה ליושב שכן פסול לעדות\u0004 לפי שהעדים צריכים לעמוד בשעה שמעידים, ונמצא שיש ביושב צד חומרה! ומשיבים: למדים זאת \u0003מיושב תלמיד חכם,\u0004 כי תלמיד חכם שבא להעיד — מותר להושיב אותו.","ומקשים: על כל פנים יש ביושב חומרה, \u0003מה לשם יושב\u0004 לעיקר דינו \u0003שכן\u0004 באופן עקרוני יושב \u0003פסול לעדות!\u0004 ומשיבים: \u0003שם יושב לא פריך\u0004 \u0005[אינו מקשה],\u0006 כי אפשר להקשות מדין מסויים, אבל לא ממושג כללי שיש בו יוצאים מן הכלל. \u0003ואם תמצא לומר פריך\u0004 \u0005[ואם\u0006 שבכל זאת \u0005מקשה]\u0006 משם יושב, \u0003אתיא\u0004 \u0005[בא,\u0006 נלמד הדבר\u0005]\u0006 \u0003מיושב ומחדא מהנך\u0004 \u0005[ומאחד מאלה],\u0006 בעל מום, טמא או אונן.","ושואלים: \u0003ויושב\u0004 ש\u0003כשר בבמה מנלן\u0004 \u0005[מנין לנו]?\u0006 שהרי ניתן להקשות אותה קושיה שהקשינו לעיל: מה לצד השווה ביניהם שכן לא הותרו בבמה! ומשיבים, \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"לעמד לפני ה' לשרתו\"\u0004 (דברים י, ח), ללמד כי חובה זו לעמוד בזמן השירות הריהי דווקא \u0003\"לפני ה'\"\u0004כלומר, במקדש, שהוא מקום שכינה, \u0003ולא לפני במה,\u0004 שאינה אלא מקום עבודה.","שנינו במשנה ש\u0003אונן\u0004 פסול לעבודה. ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בכהן גדול שמתו הוריו: \u0003\"ומן המקדש לא יצא ולא יחלל\"\u0004 (ויקרא כא, יב), כלומר, ואינו מחלל בכך את עבודתו. ומכאן נלמד: \u0003הא\u0004 \u0005[אבל]\u0006 \u0003אחר\u0004 (כהן הדיוט) \u0003שלא יצא\u0004 ועבד — \u0003חילל.\u0004","\u0003רבי אלעזר אמר: מהכא\u0004 \u0005[מכאן]\u0006 אפשר ללמוד, שכשסבור היה משה ששעיר חטאת נפסל ונשרף משום שבני אהרן הקריבוהו כשהיו אוננים על אחיהם, ענה לו אהרן: \u0003\"הן\u0004 היום \u0003הקריבו\u0004 את חטאתם ואת עולתם\"? (ויקרא י, יט), כלומר: וכי בני שהם כהנים הדיוטים הקריבו? \u0003אני הקרבתי, מכלל\u0004 הדברים אתה לומד \u0003דאי אינהו\u0004 \u0003אקריב שפיר אישתרוף\u0004 \u0005[שאם הם היו מקריבים יפה היה נשרף\u0006 הקרבן\u0003],\u0004 ומשמע שכהן הדיוט ששימש באנינות פוסל את הקרבן.","ושואלים: \u0003ורבי אלעזר מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר מ\u0004הפסוק שהובא תחילה \u0003\"ומן המקדש לא יצא\"?\u0004 ומשיבים: \u0003אמר לך\u0004 \u0005[יכול היה לומר לך]:\u0006 \u0003מי כתיב\u0004 \u0005[האם נאמר\u0006 במפורש \u0005שם]\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אחר שלא יצא חילל?\u0004 ואין מסקנה זו מחוייבת מן הכתוב.","ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 שלמד מאותו פסוק, \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 \u0003לא אמר מ\"הן הקריבו\"\u0004 כר' אלעזר? ומשיבים: לדעתו אין לפרש כך את הפסוק, משום שהוא \u0003קסבר\u0004 \u0005[סבור]\u0006 שחטאת זו לא מפני אנינות נשרפה, אלא \u0003מפני טומאה\u0004 שאירעה בה \u0003נשרפה.\u0004","\u0003דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל תנא\u0004 \u0005[שנה]:\u0006 \u0003אתיא\u0004 \u0005[בא\u0006 הדבר ונלמד\u0005]\u0006 פסולו של אונן \u0003בקל וחומר מבעל מום,\u0004 ובדרך זו: \u0003ומה\u0004"],["\u0003בעל מום שאוכל\u0004 בקדשים — \u0003אם עבד חילל, אונן שאין אוכל\u0004 בקדשים — \u0003אינו דין שאם עבד חילל?\u0004","ודוחים: \u0003מה לבעל מום שכן עשה בו קריבין כמקריבין,\u0004 שאף קרבן שהוא בעל מום פסול, ואין דין זה שייך באונן!","ואומרים: \u0003זר יוכיח,\u0004 שלא עשה בו קריבין כמקריבין, והוא מחלל עבודה. ודוחים: \u0003מה לזר\u0004 שפסולו גדול יותר, \u0003שכן אין לו תקנה\u0004 שאינו יכול אף פעם להפוך לכהן הראוי לעבודה. מה שאין כן באונן, שלאחר יום פטירת קרובו הוא מותר!","ומשיבים: \u0003בעל מום יוכיח,\u0004 שיש לו תקנה, אם היה זה מום עובר, ובכל זאת מחלל! \u0003וחזר הדין\u0004 בין בעל מום ובין זר, \u0003לא ראי זה\u0004 \u0003כראי זה ולא ראי זה כראי זה, הצד השוה שבהן שהן מוזהרין\u0004 שלא לעבוד \u0003ואם עבדו\u0004 \u0003חיללו, אף אני אביא אונן שמוזהר ואם עבד חילל.\u0004","ושואלים: \u0003היכן מוזהר\u0004 האונן שלא לעבוד? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שלמדים דבר זה \u0003מ\u0004מה שנאמר בכהן גדול כשהוא אונן \u0003\"ומן המקדש לא יצא\u0004 ולא יחלל את מקדש אלוהיו\" (ויקרא כא יב), ומכאן נדייק שכהן הדיוט מחלל (ראה בעמוד הקודם), אם כן אין צורך בקל וחומר, לשון \u0003חילול בגופיה כתיב ביה\u0004 \u0005[ב\u0006כתוב זה \u0005עצמו כתוב בו]!\u0006 \u0003אלא\u0004 הוא למד \u0003מ\"הן הקריבו\"\u0004 (ויקרא י, יט), כמבואר בעמוד הקודם, שבפסוק זה טוען אהרן: וכי הם הקריבו, \u0003וקסבר\u0004 \u0005[וסבור הוא]\u0006 שאותה חטאת \u0003מפני אנינות נשרפה.\u0004","ומקשים: אם מן הצד השווה שבבעל מום ובזר אתה למד, \u0003איכא למפרך\u0004 \u0005[יש להקשות]:\u0006 \u0003מה להצד השוה שבהן,\u0004 בבעל מום ובזר, \u0003שכן לא הותרה מכללו\u0004 ששניהם אסורים בכל מקרה. מה שאין כן באונן שהותר מכללו, שהרי מותר בכהן גדול!","ומשיבים: \u0003טמא יוכיח\u0004 שגם הוא מותר מכללו בקרבנות ציבור הבאים בטומאה, ולמרות זאת הוא מחלל.","ודוחים: \u0003מה לטמא שכן מטמא\u0004 אחרים, ושמא מפני חומרה זו שבו אף מחלל עבודה! ומשיבים: \u0003הנך\u0004 \u0005[אלה,\u0006 בעל מום וזר\u0005]\u0006 \u0003יוכיחו\u0004 שאינם פוסלים אחרים. \u0003וחזר הדין\u0004 בין שלושתם, בעל מום, זר וטמא. לא ראי זה כראי זה, ולא ראי זה כראי זה, \u0003הצד השוה שבהן שמוזהרין\u0004 שלא לעבוד ומחללים העבודה — ואף אונן שמוזהר מחלל עבודה.","ושואלים, \u0003ולפרוך\u0004 \u0005[ושיקשה]\u0006 כך: \u0003מה להצד\u0004 \u0003השוה שבהן\u0004 בבעל מום, זר וטמא, \u0003שכן לא הותרו מכללן אצל כהן גדול בקרבן יחיד,\u0004 מה שאין כן באנינות, שכהן גדול עובד כשהוא אונן אף בקרבן יחיד! ומשיבים: \u0003שם\u0004 (דין) ה\u0003טומאה מיהא אישתראי\u0004 \u0005[על כל פנים הותר]\u0006 מכללו בקרבן ציבור, ואין איפוא מקום לפרוך את הלימוד מצד זה.","\u0003רב משרשיא אמר:\u0004 הלכה זו שאונן מחלל עבודתו \u0003אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 \u0003בקל וחומר מיושב: ומה יושב שאוכל\u0004 בקדשים — \u0003אם עבד\u0004 בישיבה \u0003חילל,\u0004 \u0003אונן שאינו אוכל\u0004 — \u0003אינו דין שאם עבד חילל?\u0004","ודוחים: \u0003מה ליושב שכן\u0004 \u0003פסול לעדות!\u0004 ומשיבים: למדים זאת \u0003מיושב תלמיד חכם,\u0004 שיכול להעיד בישיבה.","ומקשים: \u0003מה לשם\u0004 לעיקר דין \u0003יושב שכן פסול לעדות!\u0004 ואומרים: \u0003שם\u0004 \u0003יושב לא פריך\u0004 \u0005[אינו מקשה]\u0006 כאשר יש מקרה מסויים שהוא כשר. \u0003ואם תימצי\u0004 \u0005[תרצה]\u0006 \u0003לומר\u0004 שבכל זאת \u0003פריך\u0004 \u0005[מקשה]\u0006 ממנו, \u0003אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 ההלכה \u0003מיושב ומחדא מהנך\u0004 \u0005[ומאחת מאלה]\u0006 בעל מום, זר, טמא, בדרך \"מה הצד\".","שנינו במשנה ש\u0003אונן\u0004 שקיבל את הדם — \u0003פסול\u0004 הקרבן. \u0003אמר רבא: לא שנו\u0004 שהקרבן פסול \u0003אלא בקרבן יחיד, אבל בקרבן צבור\u0004 — \u0003מרצה\u0004 הקרבן, עולה לרצון, וכיצד למדים זאת? \u0003קל וחומר מטומאה:\u0004","\u0003מה טומאה שלא הותרה מכללה אצל כהן גדול בקרבן יחיד,\u0004 שאין קרבן יחיד קרב בטומאה — \u0003הותרה אצל\u0004 כהן \u0003הדיוט בקרבן צבור,\u0004 שקרבן ציבור מוקרב בשעת הצורך על ידי כהן טמא, \u0003אנינות שהותרה מכללה אצל כהן גדול\u0004 שהוא עובד כשהוא אונן אפילו \u0003בקרבן יחיד\u0004 — \u0003אינו דין שהותרה אצל כהן הדיוט בקרבן ציבור?\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבא בר אהילאי:\u0004 אם בדרך לימוד זו אתה הולך, יכולים גם ללמוד אחרת ולהגיע למסקנות אחרות, מוטעות. שיכול אתה להסיק כי \u0003לא תותר אנינות אצל\u0004 \u0003כהן גדול בקרבן יחיד מקל וחומר,\u0004 ונאמר כך: \u0003ומה טומאה שהותרה אצל כהן הדיוט בצבור\u0004 — \u0003לא הותרה אצל כהן גדול בקרבן יחיד, אנינות שלא הותרה אצל כהן הדיוט\u0004 אפילו \u0003בקרבן צבור\u0004 — \u0003אינו דין שלא תותר אצל כהן גדול בקרבן יחיד?\u0004","וכן אפשר לטעון: \u0003ותותר טומאה אצל כהן גדול בקרבן יחיד מקל וחומר,\u0004 ובאופן זה: \u0003ומה אנינות שלא הותר אצל כהן הדיוט בקרבן צבור\u0004 — \u0003הותרה אצל כהן גדול בקרבן יחיד, טומאה שהותרה אצל כהן הדיוט בקרבן צבור\u0004 — \u0003אינו דין שהותרה אצל כהן גדול בקרבן יחיד?\u0004","או נאמר קל וחומר אחר: \u0003ולא תותר טומאה אצל כהן הדיוט בקרבן צבור מקל וחומר: ומה אנינות שהותרה אצל כהן גדול בקרבן יחיד\u0004 — \u0003לא הותרה אצל כהן הדיוט\u0004 אפילו \u0003בקרבן צבור, טומאה שלא הותרה אצל כהן גדול בקרבן יחיד\u0004 — \u0003אינו דין שלא תותר בכהן הדיוט בקרבן צבור?\u0004",""],["\u0003אלא איכא למיפרך הכי ואיכא למיפרך הכי\u0004 \u0005[אפשר לדון כך ואפשר לדון כך],\u0006 וכיון שהלימודים הללו מתחלפים וסותרים זה את זה, אם כן \u0003כל חדא וחדא תיקו בדוכתיה\u0004 \u0005[אחד ואחד\u0006 מן הדינים \u0005יעמוד במקומו],\u0006 ונשאיר את ההלכה כמות שהיא, בלי להוסיף דינים חדשים על סמך קל וחומר.","שנינו במשנה ש\u0003טבול יום\u0004 כלומר, טמא שטבל מטומאתו בו ביום, ועדיין לא נטהר לגמרי עד הערב, פוסל. ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו\u0006 הלכה זו\u0005]?\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' סימאי אומר: רמז לטבול יום שאם עבד\u0004 במקדש \u0003חילל מנין? תלמוד לומר\u0004 ביחס לכהנים: \u0003\"קדשים יהיו\u0004 לאלהיהם \u0003ולא יחללו\"\u0004 (ויקרא כא, ו),","\u0003אם אינו ענין לטמא\u0004 ממש, \u0003דנפיק\u0004 \u0005[שיוצא\u0006 דבר זה\u0005]\u0006 \u0003מ\u0004הפסוק \u0003\"וינזרו\u0004 מקדשי בני ישראל\" (ויקרא כב, ב), \u0003תנהו\u0004 \u0003ענין לטבול יום.\u0004 ומקשים: ומדוע תתנהו ענין דווקא לזה?","\u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003תנהו ענין לקורח קרחה\u0004 בראשו או \u0003למשחית פאת זקן,\u0004 הכתובים סמוך לפסוק \"ולא יחללו\"!","ומשיבים: כיוון שיש לנו לימוד אחר מפסוק זה לגבי טבול יום, ש\u0003טבול יום\u0004 ש\u0003אם עבד\u0004 שדינו \u0003במיתה מנא לן\u0004 \u0005[מנין לנו]?\u0006 \u0003דגמר\u0004 \u0005[שלמד]\u0006 בגזירה שווה \u0003\"חילול\"\u0004 האמור כאן מ\u0003\"חילול\" מתרומה,\u0004 שם נאמר \"ומתו בו כי יחללוהו\" (ויקרא כב, ט), מכאן יש ללמוד כי גם לענין חילול עבודה האמור בפסוק זה \u0003דפסיל\u0004 \u0005[\u0006מי \u0005שפוסל]\u0006 \u0003בתרומה\u0004 כלומר, טבול יום, הוא \u0003מחיל\u0004 \u0005[מחלל]\u0006 את ה\u0003עבודה,\u0004 ומי \u0003דלא פסיל\u0004 \u0005[שאינו פוסל]\u0006 \u0003בתרומה לא מחיל\u0004 \u0005[אינו מחלל]\u0006 \u0003עבודה.\u0004","\u0003אמר רבה: למה לי דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 מקורות נפרדים לגבי \u0003טמא וטבול יום ומחוסר כפורים\u0004 שמחללים עבודה?","ומשיב: \u0003צריכי\u0004 \u0005[צריכים\u0006 הם\u0005],\u0006 \u0003דאי כתב רחמנא\u0004 \u0005[שאם היתה כותבת התורה]\u0006 רק \u0003טמא\u0004 הייתי אומר שאין ללמוד ממנו לטבול יום ומחוסר כיפורים, \u0003שכן\u0004 הוא \u0003מטמא\u0004 שהופך את מה שנגע בו לטמא, מה שאין כן טבול יום ומחוסר כיפורים, שאף שלא נטהרו לגמרי — אינם מטמאים, אלא רק פוסלים את התרומה (בטבול יום) או את הקדשים (במחוסר כיפורים). ואם היתה התורה כותבת \u0003בטבול יום\u0004 שהוא מחלל עבודה, \u0003מחוסר כפורים לא אתי מיניה\u0004 \u0005[אינו יכול לבוא\u0006 להילמד \u0005ממנו]\u0006 \u0003שכן\u0004 טבול יום חמור יותר, שהוא \u0003פסול בתרומה.\u0004 ואם היתה התורה כותבת רק \u0003במחוסר כפורים\u0004 — \u0003טבול יום לא אתי מיניה\u0004 \u0005[אינו יכול לבוא ממנו]\u0006 \u0003שכן\u0004 מחוסר כיפורים חמור יותר, שהוא \u0003מחוסר מעשה\u0004 שצריך להביא קרבן להשלמת טהרתו. מה שאין כן טבול יום, שטהרתו באה מעצמה עם שקיעת השמש.","ושואלים: \u0003מחדא לא אתי\u0004 \u0005[\u0006מדבר \u0005אחד\u0006 מהם \u0005אי אפשר ללמוד],\u0006 \u0003תיתי חדא מתרתי\u0004 \u0005[שתבוא,\u0006 תילמד \u0005אחת משתים\u0006 האחרות\u0005]!\u0006","ושואלים: \u0003בהי\u0004 \u0005[באיזו\u0006 מהם\u0005]\u0006 \u0003לא לכתוב רחמנא\u0004 \u0005[תכתוב\u0006 \u0003התורה]?\u0004 ש\u0003לא לכתוב\u0004 \u0005[תכתוב]\u0006 \u0003במחוסר כפורים ותיתי מהנך\u0004 \u0005[ותילמד מאלה]\u0006 מטמא ומטבול יום — אפשר לדחות: \u0003מה להנך\u0004 \u0005[לאלה]\u0006 \u0003שכן פסולים בתרומה,\u0004 ולכן מחללים עבודה!","\u0003אלא לא לכתוב רחמנא\u0004 \u0005[תכתוב התורה]\u0006 \u0003בטבול יום ותיתי מהנך\u0004 \u0005[ותלמד מאלה]\u0006 מטמא וממחוסר כיפורים, \u0003דמאי פרכת\u0004 \u0005[שמה אתה מקשה]?\u0006 \u0003מה להנך\u0004 \u0005[לאלה]\u0006 \u0003שכן מחוסרים מעשה,\u0004 שטמא צריך טבילה לטהרתו, ומחוסר כיפורים צריך קרבן לגמר טהרתו — \u0003סוף סוף\u0004 למרות שמחוסרי כיפורים צריכים קרבן להשלמת טהרתם, מכל מקום \u0003קלישא לה\u0004 \u0005[קלושה היא]\u0006 \u0003טומאתן\u0004 יותר מטבול יום, ואם כן אינם נחשבים מחוסרי מעשה ביחס אליו!"],["ומשיבים: \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 רבה ש\u0003מחוסר כפורים\u0004 של \u0003זב\u0004 (ושאר מחוסרי כפרה) \u0003כזב דמי\u0004 \u0005[נחשב]\u0006 לענין טומאתו, וטומאתו חמורה, איפוא, מטבול יום שאינו זקוק לכפרה.","ומעירים: \u0003ו\u0004שאלה זו, האם \u0003מחוסר כפורים\u0004 של \u0003זב כזב דמי\u0004 \u0005[נחשב]\u0006 \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 פרה אדומה ש\u0003שרפה אונן\u0004 או \u0003מחוסר כפורים\u0004 — הרי היא \u0003כשרה. יוסף הבבלי אומר:\u0004 אם שרפה \u0003אונן\u0004 — \u0003כשרה, מחוסר כפורים\u0004 — \u0003פסולה. מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא בזה הם חלוקים],\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 יוסף הבבלי, \u0005סבור]:\u0006 \u0003מחוסר כפורים\u0004 של \u0003זב כזב דמי\u0004 \u0005[נחשב]\u0006 ולכן הינו כטמא לגמרי, ואינו כשר לשריפת הפרה, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 התנא האחר, \u0005סבור]:\u0006 מחוסר כיפורים \u0003לאו כזב דמי\u0004 \u0005[אינו נחשב כזב],\u0006 ודינו כטבול יום, שכשר בפרה?","ודוחים: \u0003לא,\u0004 אפשר לומר כי בדרך כלל \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003כזב דמי\u0004 \u0005[נחשב],\u0006 \u0003והכא בהא קמיפלגי\u0004 \u0005[וכאן בזה הם חלוקים],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בהזאת מי פרה אדומה: \u0003\"והזה הטהר\"\u0004 (במדבר יט, יט), וכבר יודעים אנו מן הפסוק הקודם שמדובר באיש טהור, אלא שיש כאן הדגשה — הטהור לענין זה, \u0003מכלל שהוא טמא\u0004 לענין אחר, ובכך \u0003לימד\u0004 הכתוב \u0003על טבול יום שכשר בפרה.\u0004","ובפירושה של דרשה זו נחלקו, \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 התנא הראשון, \u0005סבור]\u0006 שהכוונה היא לטבול יום של \u0003טומאה\u0004 שב\u0003כל התורה כולה\u0004 שכשר לעבודת הפרה, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 יוסף הבבלי, \u0005סבור]:\u0006 \u0003טומאה דהך פרשה\u0004 \u0005[של פרשה זו בלבד],\u0006 כלומר, רק בטבול יום מטומאת מת, שאותה מטהרת הפרה האדומה.","\u0003הלכך\u0004 \u0005[על כן]\u0006 \u0003אונן וטבול יום\u0004 של \u0003טמא שרץ, דקילי\u0004 \u0005[שהם קלים],\u0006 \u0003אתו\u0004 \u0005[באים\u0006 ונלמדים\u0005]\u0006 \u0003בקל וחומר מטבול יום\u0004 של \u0003מת, אבל מחוסר כפורים\u0004 של \u0003זב, דחמיר\u0004 \u0005[ש\u0006הוא \u0005חמור\u0006 יותר\u0005]\u0006 שדינו כזב, \u0003שכן טומאה\u0004 של זב \u0003יוצאה עליו מגופו\u0004 ולא באה עליו מבחוץ — \u0003לא,\u0004 אי אפשר ללמוד להכשיר בו את עבודת הפרה.","שנינו במשנה ש\u0003מחוסר בגדים\u0004 שעבד פסל. ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 דבר זה? \u0003אמר\u0004 \u0003ר' אבוה אמר ר' יוחנן, ומטו\u0004 \u0005[והיו מגיעים]\u0006 \u0003בה\u0004 בשמועה זו ומוסרים אותה \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' אלעזר בר' שמעון,\u0004 ש\u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"וחגרת אותם אבנט אהרן ובניו וחבשת להם מגבעת והיתה להם כהנה לחקת עולם\"\u0004 (שמות כט, ט), ללמוד מכאן \u0003בזמן שבגדיהם עליהם\u0004 — \u0003כהונתם עליהם, אין בגדיהם עליהם\u0004 — \u0003אין כהונתם עליהם\u0004 ופוסלים את עבודתם.","ושואלים: \u0003והא מהכא נפקא\u0004 \u0005[ו\u0006דבר \u0005זה מכאן\u0006 הוא \u0005יוצא\u0006 נלמד\u0005]?\u0006 \u0003מהתם נפקא\u0004 \u0005[משם\u0006 הוא \u0005יוצא,\u0006 נלמד\u0005],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003מנין לשתויי יין שאם עבד\u0004 כשהוא שתוי \u0003חילל? תלמוד לומר: \"יין ושכר אל תשת\" וגו'\u0004 (ויקרא י, ט) ונאמר בהמשך \u0003\"ולהבדיל בין הקדש ובין החל\"\u0004 (ויקרא י, י) שדבר זה מבדיל בין עבודת קודש לבין עבודה מחוללת. וממשיכה הברייתא: \u0003מחוסר בגדים ושלא רחוץ ידים ורגלים, מנין\u0004 שגם הוא מחלל?"],["\u0003תלמוד לומר: \"חקה\" \"חקה\"\u0004 שנאמרה גם בשתויי יין (ויקרא י, ט) וגם בבגדי כהונה (שמות כח, מג) וברחיצת ידים ורגלים (ראה שמות ל, כא) \u0003לגזירה שוה.\u0004 ואם כן, יש לכך מקור מכתוב אחר!","ומשיבים: \u0003אי מהתם\u0004 \u0005[אם משם]\u0006 בלבד, משתויי יין, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כך: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שמחוסר בגדים מחלל עבודה, אמורים רק ב\u0003עבודה\u0004 ש\u0003זר חייב עליה מיתה,\u0004 שעל כך מדברת פרשת שתויי יין, \u0003אבל עבודה\u0004 ש\u0003אין זר חייב עליה מיתה אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שמחוסר בגדים מחלל כל עבודה.","ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 איפוא ש\u0003מחוסר בגדים\u0004 מחלל כל עבודה, גם זו שאין זר חייב עליה מיתה, \u0003שתויי\u0004 \u0003יין מנלן\u0004 \u0005[מנין לנו]?\u0006 שהרי הפרשה שם עוסקת רק במה שחייבים עליו מיתה. ומשיבים: \u0003אתיא\u0004 \u0005[בא,\u0006 נלמד \u0005הדבר]\u0006 בגזירה שווה \u0003של\u0004 \u0003\"חקה\" \"חקה\"\u0004 \u0003ממחוסר בגדים.\u0004","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 ה\u0003תנא\u0004 של הברייתא בענין שתויי יין את חילול עבודה מ\u0003\"ולהבדיל בין\u0004 הקודש ובין החול\" \u0003קא נסיב לה\u0004 \u0005[הוא לוקח,\u0006 למד, \u0005אותה]!\u0006 ומשיבים: דבר זה היה \u0003מקמי דליקום\u0004 \u0005[לפני שעומדת\u0006 בידו\u0005]\u0006 ה\u0003גזירה שוה,\u0004 ואולם לאחר מכן היא הבסיס להלכה זו.","ושואלים: כיצד יכול אתה לומר כן? \u0003והא\u0004 \u0005[והרי]\u0006 ה\u0003תנא,\u0004 בגזירה שווה זו \u0003מחוסר בגדים\u0004 \u0003הוא דקא יליף\u0004 \u0005[שלומד]\u0006 \u0003משתויי יין,\u0004 ולא שתויי יין ממחוסר בגדים! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003מנין שלא נחלקו\u0004 (כלומר, שאין הבדל וחילוק) \u0003בין מחוסר בגדים לשתויי יין ושלא רחוץ ידים ורגלים? תלמוד לומר: \"חקה\" \"חקה\" לגזירה שוה.\u0004","ושואלים: כיון שיש גזירה שווה, \u0003אלא\u0004 הפסוק \u0003\"להבדיל\"\u0004 ממנו למדנו מתחילה ששתויי יין מחללים עבודה, \u0003למה לי?\u0004 ומשיבים: \u0003לכ\u0004 מו שנהג \u0003רב,\u0004 ש\u0003רב לא מוקים אמורא עליה מיומא טבא לחבריה\u0004 \u0005[היה מעמיד מתורגמן עליו מיום טוב לחבירו]\u0006 כלומר, לא היה דורש ברבים ביום טוב, מזמן שהיה אוכל ושותה יין, עד למחרת (יום טוב שני של גלויות) \u0003משום שכרות\u0004 הואיל ושתוי אינו יכול להבדיל כראוי בין דבר לדבר. והרי נאמר שם: \"יין ושכר אל תשת... ולהבדיל בין הקודש ובין החול ובין הטמא ובין הטהור, ולהורות את בני ישראל את כל החוקים\" וכו' (ויקרא י, ט—יא), ומכאן שמי ששתה יין אסור לו להורות הלכה.","ושואלים: \u0003אכתי מהכא נפקא\u0004 \u0005[עדיין מכאן\u0006 מפסוק זה, \"והיתה להם כהונה לחוקת עולם\", \u0005יוצא\u0006 הדבר\u0005]\u0006 שמחוסר בגדים מחלל עבודה? \u0003מהתם נפקא\u0004 \u0005[משם יוצא]:\u0006 שנאמר במצוה של נתינת האש על המזבח: \u0003\"ונתנו בני אהרן הכהן\u0004 אש על המזבח\" (ויקרא א, ז) והייתור \"הכהן\" לגבי אהרן בא להדגיש: הכהן \u0003בכיהונו,\u0004 כשהוא נוהג בכהונה, \u0003לימד על כהן גדול שלבש בגדי כהן הדיוט ועבד\u0004 ש\u0003עבודתו פסולה!\u0004","ומשיבים: יש צורך גם בפסוק זה, שכן \u0003אי מהתם\u0004 \u0005[אם משם],\u0006 מ\"והיתה להם כהונה לחוקת עולם\", \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 דווקא ב\u0003עבודה דמעכבא\u0004 \u0005[שמעכבת]\u0006 את ה\u0003כפרה, אבל עבודה דלא מעכבא\u0004 \u0005[שאינה מעכבת]\u0006 \u0003כפרה\u0004 כמו נתינת האש, \u0003לא\u0004 יפסול בה. לכך הובא כתוב זה.","ועוד שואלים: \u0003ואכתי מהכא נפקא\u0004 \u0005[ועדיין מכאן יוצא,\u0006 נלמד הדבר\u0005]\u0006 מצירופם של כתובים אלה? \u0003מהתם נפקא\u0004 \u0005[משם יוצא],\u0006 שנאמר: \u0003\"וערכו בני אהרן הכהנים את הנתחים\" וגו'\u0004 (ויקרא א, ח), והמלה \u0003\"הכהנים\"\u0004 באה להדגיש: \u0003בכיהונן, מכאן\u0004 \u0003לכהן הדיוט שלבש בגדי כהן גדול ועבד\u0004 — \u0003עבודתו פסולה!\u0004","ומשיבים: \u0003אי\u0004 \u0003מהתם\u0004 \u0005[אם משם]\u0006 \u0003הוה אמינא הני מילי\u0004 \u0005[הייתי אומר\u0006 ש\u0005דברים אלה]\u0006 אמורים ב\u0003חיסור\u0004 בגדים, כגון כהן גדול שלא לבש את כל הבגדים הראויים לו, \u0003אבל ייתור\u0004 בגדים כגון כהן הדיוט שלבש בגדי כהן גדול \u0003לא\u0004 יפסול, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 פסוק זה שאפילו ייתור בגדים פוסל.","ועוד לגבי דיני בגדי כהונה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003היו\u0004 הבגדים \u0003מרושלין\u0004 ונגררים על הקרקע, או \u0003מסולקין\u0004 מוגבהים מן הקרקע, \u0003או\u0004 \u0003משוחקים\u0004 שחוקים, \u0003ועבד\u0004 בהם — \u0003עבודתו כשירה.\u0004 אבל אם \u0003לבש שני מכנסים,\u0004 או \u0003שני\u0004 \u0003אבנטים,\u0004 או \u0003חסר אחת\u0004 מן הבגדים, או \u0003יתר אחת, או שהיתה לו רטיה\u0004 (תחבושת) \u0003על מכת בשרו תחת בגדו\u0004 והיא חוצצת בין הבגד והבשר, \u0003או שהיו\u0004"],["\u0003מטושטשין\u0004 מלוכלכים ומוכתמים, \u0003או מקורעין\u0004 (אפילו היו חדשים), \u0003ועבד\u0004 — \u0003עבודתו פסולה.\u0004","ומביאים מה ש\u0003אמר רב יהודה אמר שמואל:\u0004 אם היו \u0003מרושלין\u0004 נגררים על הקרקע — \u0003כשרין,\u0004 אם \u0003מסולקין\u0004 ומוגבהים מן הקרקע — \u0003פסולין.\u0004 ומקשים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 שהבאנו: \u0003מסולקין\u0004 — \u0003כשרין! אמר רמי בר חמא, לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן\u0004 בברייתא, \u0003מדובר\u0004 \u0003שסילקן\u0004 (שהעלה אותן) \u0003על ידי אבנט,\u0004 ובאמת אינם קצרים ממידתו. \u0003כאן\u0004 שפסל שמואל, מדובר \u0003דליתניהו מעיקרא\u0004 \u0005[שאינם\u0006 מכסים את רגליו \u0005מתחילה]\u0006 \u0003כלל\u0004 ואילו","\u0003רב אמר: אחד זה ואחד זה\u0004 בין מרושלים בין מסולקים — \u0003פסולין.\u0004","ומסופר, \u0003רב הונא איקלע\u0004 \u0005[הזדמן]\u0006 \u0003ל\u0004מקום \u0003ארגיזא, רמא ליה בר אושפיזכניה\u0004 \u0005[השליך לו,\u0006 הראה לו סתירה \u0005בן בעל האכסניא שלו]:\u0006 \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר שמואל: מרושלין\u0004 \u0003כשרין, ומסולקין פסולין? והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003מסולקין\u0004 — \u0003כשרין! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בר מינה דההיא\u0004 \u0005[חוץ ממנה, מאותה\u0006 ברייתא\u0005],\u0006 אין להקשות ממנה, \u0003דשנייה\u0004 \u0005[ש\u0006כבר \u0005תירץ אותה]\u0006 \u0003רמי בר חמא,\u0004 שמדובר בה כשהם מסולקים על ידי אבנט.","ושואלים: \u0003אלא לרב קשיא\u0004 \u0005[קשה]\u0006 שהוא פוסל במרושלים, והברייתא מכשירה בהם! \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מרושלין\"\u0004 בברייתא? כשהם \u0003מסולקין על ידי אבנט\u0004 לגובה הראוי, ומשום כך הם כשרים — כי לדעת התנא \u0003אבנט מיגז אגיז\u0004 \u0005[גוזז אותם],\u0006 וכאילו לא היתה שם תוספת, \u0003אלא\u0004 לפי זה \u0003מסולקין קשיא\u0004 \u0005[קשה]:\u0006 מדוע כשרים הם? הרי גם אם סילקם על ידי אבנט — נחשבים הם כגזוזים וקצרים מן המידה הראויה!","\u0003אמר ר' זירא, רב חדא\u0004 \u0003תני\u0004 \u0005[שנה\u0006 את המלים \"מרושלין מסולקין\" כדבר \u0005אחד],\u0006 כיצד? \u0003מרושלין שסילקן\u0004 (העלה אותן) \u0003על\u0004 \u0003ידי אבנט\u0004 ועשה אותם כראוי — \u0003כשרין,\u0004 אבל מסולקים — פסולים.","\u0003אמר ר' ירמיה מדיפתי: מרושלין שלא סילקן\u0004 — \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 האם הם כשרים, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 נאמר בציצית \"גדילים תעשה לך על ארבע כנפות כסותך אשר תכסה בה\" (דברים כב, יב). וממה שנאמר \u0003\"על ארבע כנפות כסותך\"\u0004 מדייקים: \u0003ארבע ולא שלש,\u0004 שאם היו לכסות רק שלוש כנפות אינו חייב בציצית. ושואלים: \u0003או אינו אלא\u0004 ללמדנו \u0003ארבע ולא חמש?\u0004 ומשיבים: \u0003כשהוא\u0004 מוסיף ו\u0003אומר: \"אשר תכסה בה\"\u0004 (דברים כב, יב) — \u0003הרי\u0004 טלית \u0003בעלת חמש אמור\u0004 מריבוי הכתוב. \u0003הא מה אני מקיים ארבע?\u0004 לומר \u0003ארבע ולא שלש.\u0004 ושואלים: \u0003ו\u0004כיון שיש פה לשון מיעוט ולשון ריבוי, \u0003מה ראית לרבות בעלת חמש ולהוציא בעלת שלש?\u0004 ומשיבים: \u0003מרבה אני בעלת חמש\u0004 — \u0003שיש בכלל חמש ארבע\u0004 כנפות שהתורה חייבה בהן ציצית, \u0003ומוציא\u0004 \u0003אני בעלת שלש\u0004 — \u0003שאין בכלל שלש ארבע.\u0004 זו ברייתא אחת.","\u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003\"על ארבע כנפות כסותך\"\u0004 (דברים כב, יב) — \u0003ארבע ולא שלש,\u0004 \u0003ארבע ולא חמש,\u0004 וגם בעלת חמש כנפות פטורה מציצית. \u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא\u0006 בנושא \u0005זה הם חלוקים],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 שפוטר טלית בעלת כנף נוספת, \u0005סבור]:\u0006 \u0003יתר כמאן דאיתיה דמי\u0004 \u0005[כמי שישנו\u0006 הוא \u0005נחשב],\u0006 לא ניתן להתעלם ממנו, ולפיכך הוא פוסל גם בבגדי כהונה מרושלים, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 המחייב חמש כנפות בציצית, \u0005סבור]:\u0006 יתר \u0003כמאן דליתיה דמי\u0004 \u0005[כמי שאינו\u0006 הוא \u0005נחשב],\u0006 ולכן בגדים מרושלים כשרים?","ודוחים: \u0003לא, דכולי עלמא כמאן דאיתיה דמי\u0004 \u0005[לדעת הכל\u0006 יתר \u0005כמי שישנו\u0006 הוא \u0005נחשב]\u0006 ובבגדי כהונה הוא פוסל, \u0003ושאני הכא דרבי רחמנא\u0004 \u0005[ושונה כאן,\u0006 לענין ציצית, \u0005שריבתה התורה]:\u0006 \u0003\"אשר תכסה בה\".\u0004","ושואלים: \u0003ואידך\u0004 \u0005[והאחר],\u0006 הפוטר כסות בעלת חמש כנפות מציצית, \u0003האי\u0004 \u0005[זה\u0006 הריבוי\u0005]\u0006 \u0003\"אשר\u0004 \u0003תכסה בה\" מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בו]?\u0006 ומשיבים: \u0003מיבעי ליה לכדתניא\u0004 \u0005[צריך\u0006 הוא \u0005לו לכמו ששנויה\u0006 בברייתא אחרת\u0005]:\u0006 נאמר \u0003\"וראיתם אתו\"\u0004 (במדבר טו, לט) — \u0003פרט לכסות לילה\u0004 שאז אין הציצית נראית. ויש לשאול: \u0003או אינו אלא פרט לכסות סומא\u0004 שאינו רואה את הציצית? על כך יש להשיב: \u0003כשהוא אומר: \"אשר תכסה בה\"\u0004 לרבות — \u0003הרי כסות סומא אמור\u0004 שחייבת בציצית, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מה אני מקיים \"וראיתם אתו\"? פרט לכסות לילה.\u0004","ושואלים: \u0003ומה ראית לרבות כסות סומא ולהוציא כסות לילה?\u0004 ומשיבים: \u0003מרבה אני כסות סומא, ש\u0004אף על פי שהוא אינו רואה \u0003ישנה בראיה אצל אחרים, ומוציא אני כסות לילה שאינה בראיה\u0004 גם \u0003אצל אחרים. [\u0004ושואלים:","\u0003ואידך\u0004 \u0005[והאחר]\u0006 שדרש ריבוי זה לרבות כסות בעלת חמש כנפות, מהיכן יודע הוא הלכה זו לרבות כסות סומא? ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא לו\u0006 הדבר\u0005]\u0006 \u0003מ\"אשר\"\u0004 שהוא לשון ריבוי. ומן הצד השני, \u0003ואידך\u0004 \u0005[והאחר]?\u0006 את המילה \u0003\"אשר\" לא דריש\u0004 \u0005[אינו דורש]\u0006 כריבוי. ]","ועוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בענין בגדי כהונה: מה שנאמר בהם \u0003\"בד\"\u0004 בא לומר \u0003ב\u0004\u0003שיהיו של בוץ\u0004 (פשתן), \u0003\"בד\"\u0004 — \u0003שיהו חדשים, \"בד\"\u0004 — \u0003שיהו שזורים\u0004 שיהא החוט ממנו הם עשויים שזור מכמה חוטים יחד, \u0003\"בד\"\u0004 — \u0003שיהו חוטן כפול ששה, \"בד\"\u0004 — \u0003שלא ילבש\u0004 בגדים \u0003של\u0004 \u0003חול עמהן.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: בשלמא\u0004 \u0005[נניח]\u0006 מה שהוא שונה \u0003שיהו\u0004 \u0003של בוץ\u0004 — \u0003הא קא משמע לן\u0004 \u0005[דבר זה משמיע לנו]:\u0006 \u0003בוץ\u0004 (פשתן) — \u0003אין\u0004 \u0005[כן],\u0006 \u0003מידי\u0004 \u0003אחרינא\u0004 \u0005[דבר\u0006 \u0005אחר]\u0006 — \u0003לא. אלא\u0004 מה שהוא שונה: \u0003\"בד\"\u0004 — \u0003שיהו חדשים,\u0004 האם נלמד מכאן ש\u0003חדשים\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003שחקין\u0004 (שחוקים) — \u0003לא? והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 שבגדי כהונה \u0003משוחקין\u0004 — \u0003כשרים!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 ולשיטתך\u0005],\u0006 מה ששנה בברייתא זו \u0003\"בד\" שיהו חוטן כפול ששה,\u0004 כיצד הוא נלמד? הלוא \u0003\"בד\"\u0004 — \u0003חד חד לחודיה משמע\u0004 \u0005[אחד אחד לעצמו משמעו]!\u0006 \u0003אלא הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 אותם \u0003בגדים שנאמר בהן \"בד\" צריכין שיהו של בוץ, חדשים, שזורין, שיהא חוטן כפול ששה, יש מהן\u0004 מהדרישות האלה \u0003למצוה\u0004 לכתחילה, ו\u0003יש מהן לעכב.\u0004","ושואלים: לעיקרו של דבר, \u0003ממאי\u0004 \u0005[ממה יודע אתה]\u0006 \u0003דהאי בד כתנא\u0004 \u0005[שבד זה\u0006 האמור במקרא \u0005פשתן]\u0006 \u0003הוא? אמר רב יוסף בר' חנינא: דבר העולה מן הקרקע בד בבד\u0004 \u0005[אחד אחד],\u0006 שאין גבעוליו מתפצלים לכמה ענפים.","ושואלים: \u0003אימא\u0004 \u0005[אמור]\u0006 שהוא \u0003עמרא\u0004 \u0005[צמר]!\u0006 ואומרים: \u0003עמרא מיפצל\u0004 \u0005[הצמר מתפצל]\u0006 השערות מתפצלות לכמה נימים. ושואלים: \u0003כיתנא נמי מיפצל\u0004 \u0005[הפשתן גם כן מתפצל]!\u0006 ומשיבים: פשתן \u0003על ידי לקותא מיפציל\u0004 \u0005[\u0006רק \u0005על ידי הכאה הוא מתפצל]\u0006 ואילו הצמר מתפצל מעצמו.","\u0003רבינא אמר, מהכא\u0004 \u0005[מכאן]\u0006 למדים דבר זה, שנאמר בבגדי הכהנים: \u0003\"פארי פשתים יהיו על ראשם ומכנסי פשתים יהיו על מתניהם לא יחגרו ביזע\"\u0004 (יחזקאל מד, יח), הרי שהבד האמור בתורה הוא פשתים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לרבינא: והא\u0004 \u0005[\u0006ודבר \u0005זה]\u0006 \u0003עד דאתא\u0004 \u0005[שבא]\u0006 \u0003יחזקאל מנלן\u0004 \u0005[מנין\u0006 היה \u0005לנו]?\u0006 אמר לו: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 ולשיטתך\u0005],\u0006 \u0003הא\u0004 \u0005[זו]\u0006 ש\u0003אמר רב חסדא\u0004 לענין אחר: \u0003דבר זה\u0004 (הלכה זו) שמשומד וערל פסולים לשרת בכהונה \u0003מתורת משה רבינו לא למדנו\u0004 שאינה כתובה בתורה, \u0003מדברי יחזקאל בן בוזי למדנו\u0004 שאמר: \u0003\"כל בן נכר ערל לב וערל בשר לא יבא אל מקדשי\"\u0004 (יחזקאל מד, ט), \u0003עד שבא יחזקאל מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003אלא גמרא גמירי לה\u0004 \u0005[במסורת היו למודים אותה]\u0006 שכך היא ההלכה, \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003יחזקאל ואסמכיה אקרא\u0004 \u0005[והסמיכה על המקרא],\u0006 \u0003הכא נמי גמרא גמירי לה\u0004 \u0005[כאן גם כן במסורת היו יודעים אותה]\u0006 ובא יחזקאל ופירש אותה.","כיון שהוזכר פסוק זה שואלים: \u0003מאי\u0004 \u0005[מה פירוש]\u0006 \u0003\"לא יחגרו ביזע\"? אמר אביי: לא יחגרו במקום שמזיעין, כדתניא\u0004 \u0005[כמו ששנויה\u0006 ברייתא\u0003]:\u0004 \u0003כשהם חוגרין\u0004 את האבנט \u0003אין חוגרין\u0004 אותו \u0003לא למטה ממתניהן ולא למעלה מאציליהן\u0004 (מגובה מרפקיהם), \u0003אלא\u0004"],["\u0003כנגד אצילי ידיהן\u0004 מול המרפקים.","\u0003אמר רב אשי, אמר לי הונא בר נתן: זימנא חדא הוה קאימנא קמיה דאיזגדר מלכא\u0004 \u0005[פעם אחת הייתי עומד לפני איזגדר המלך]\u0006 מלך פרס, \u0003והוה מדלי לי המיינאי\u0004 \u0005[והיה מוגבה לי אבנטי\u0006 למעלה מן \u0005המידה\u0006\u0005],\u0006 \u0003ותיתייה ניהליה\u0004 \u0005[ו\u0006הוא \u0005הוריד אותו למטה]\u0006 למקומו, \u0003ואמר לי: \"ממלכת כהנים וגוי קדוש\"\u0004 (שמות יט, ו) \u0003כתיב בכו\u0004 \u0005[כתוב בכם],\u0006 ולכן אתם צריכים להיות מהודרים ככהנים. \u0003כי אתאי קמיה\u0004 \u0005[כאשר באתי לפני]\u0006 \u0003אמימר\u0004 וסיפרתי לו מעשה זה, \u0003אמר לי: אקיים\u0004 \u0005[התקיים]\u0006 \u0003בך\u0004 מאמר הנביא \u0003\"והיו מלכים אמניך\"\u0004 (ישעיהו מט, כג), שמלכים ינהגו בבני ישראל כאילו היו אומנים, משרתים המטפלים ומגדלים את בני המלכים.","ובענין נוסף שקשור לבגדי כהונה, \u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]:\u0006 \u0003כהן שלקה באצבעו\u0004 ונפצע — \u0003כורך עליה גמי\u0004 גומא, כתחבושת, \u0003במקדש\u0004 אפילו בשבת, \u0003אבל לא במדינה\u0004 כלומר, מחוץ למקדש. שאסור הדבר משום שבות (מצות שביתה ממעשים שונים, מגזירת חכמים), אבל במקדש לא גזרו איסורי שבות. \u0003ואם\u0004 התכוון \u0003להוציא ממנה דם,\u0004 שהוא איסור שמן התורה — \u0003כאן\u0004 \u0003וכאן\u0004 בין במקדש בין במדינה \u0003אסור.\u0004","ועל כך \u0003אמר ר' יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא: לא שנו\u0004 שמותר לכהן לכרוך על אצבעו \u0003אלא גמי, אבל צילצול קטן\u0004 (רצועה קטנה לקישוט) \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003יתור בגדים\u0004 ואסור. \u0003ור' יוחנן אמר: לא אמרו יתור בגדים אלא במקום\u0004 שצריכים להיות בו \u0003בגדים, אבל שלא במקום בגדים,\u0004 באצבע, \u0003לא הוי\u0004 \u0005[אין זה]\u0006 \u0003יתור.\u0004","ושואלים: \u0003ותיפוק ליה\u0004 \u0005[ותצא לו]\u0006 סיבה אחרת לאיסור לכרוך צלצול על אצבעו — \u0003משום חציצה\u0004 שחוצץ בינו ובין הכלי שצריך להחזיק בו! ומשיבים: מדובר \u0003ב\u0004יד \u0003שמאל\u0004 שאינו עובד בה. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 ביד ימין, אבל \u0003שלא במקום עבודה\u0004 כלומר, במקום שאינו נוגע בכלי.","ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 שיטת ר' יוחנן, ששלא במקום בגדים אין זה נחשב יתור כלל, על שיטת \u0003רבא,\u0004 ש\u0003אמר רבא אמר רב חסדא: במקום בגדים\u0004 — \u0003אפילו נימא\u0004 \u0005[חוט]\u0006 \u0003אחת חוצצת, שלא במקום בגדים\u0004 — רק דבר שיש בו \u0003שלש על שלש\u0004 אצבעות \u0003חוצצות\u0004 כלומר, מהוות יתור בגדים, \u0003פחות\u0004 \u0003מכאן אינן חוצצות.\u0004","ומעירים: על דברי \u0003ר' יוחנן ודאי פליגא\u0004 \u0005[חולקת\u0006 היא\u0005]\u0006 שיטת רבא, שהרי הוא סבור שלא במקום בגדים אין זה יתור כלל. אך על דברי \u0003ר' יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא\u0004 \u0003מי לימא דפליגא\u0004 \u0005[האם\u0006 \u0003נאמר ש\u0004היא \u0005חלוקה]?\u0006 שהרי לשיטתו אף צילצול קטן יש בו יתור, ואילו לדעת רבא — דווקא מה שיש בו שלוש על שלוש.","ומשיבים: לא, אפשר לומר שגם לדעת רבא \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003צילצול קטן דחשיב\u0004 \u0005[ש\u0006הוא \u0005חשוב],\u0006 ולכן הוא נחשב כבגד, ועושה יתור בגדים.","\u0003לישנא\u0004 \u0003אחרינא אמרי לה\u0004 \u0005[בלשון אחרת אומרים אותה]\u0006 מחלוקת זו: \u0003אמר ר' יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא: לא שנו\u0004 שמותר הכהן לכרוך על אצבעו \u0003אלא גמי, אבל צילצול קטן חוצץ. ור' יוחנן אמר: לא אמרו חציצה בפחות משלש על שלש אלא במקום בגדים, אבל שלא במקום בגדים\u0004 — \u0003שלש על שלש חוצצות, פחות מיכן אינה חוצצת.\u0004 ומעירים: \u0003ו\u0004דברי ר' יוחנן, שמחלק שלא במקום בגדים בין שלוש על שלוש ובין פחות מכך, \u0003היינו\u0004 \u0005[הוא\u0006 הדבר\u0005]\u0006 שאמר \u0003רבא אמר\u0004 בשם \u0003רב חסדא.\u0004","ושואלים: \u0003לימא פליגא\u0004 \u0005[האם לומר ש\u0006שיטת רבא \u0005חלוקה]\u0006 על דברי \u0003ר' יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא?\u0004 ודוחים: לא, \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003צילצול קטן דחשיב\u0004 \u0005[ש\u0006הוא \u0005חשוב].\u0006","ושואלים: \u0003ול\u0004דעת \u0003ר' יוחנן מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 שנה התנא \u0003גמי?\u0004 \u0003לשמועינן\u0004 \u0005[שישמיע לנו]\u0006 \u0003צילצול קטן,\u0004 ויש בזה חידוש גדול יותר, שמותר הדבר למרות שהוא דבר חשוב! ומשיבים: \u0003מילתא אגב\u0004 \u0003אורחיה קא משמע לן\u0004 \u0005[דבר בדרך אגב משמיע לנו],\u0006 ש\u0003גמי מסי\u0004 \u0005[מרפא]\u0006 את הפצע.","ובענין חציצה בבגדי כהונה, \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא: נכנסה לו רוח בבגדו,\u0004 כלומר, נכנסה רוח והרחיקה את בגדו מגופו, \u0003מהו\u0004 הדין? האם \u0003\"על בשרו\"\u0004 ממש \u0003בעינן\u0004 \u0005[צריכים אנו],\u0006 כלשון הכתוב (ויקרא ו, ג), \u0003והא ליכא\u0004 \u0005[והרי אין כאן],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003דרך לבישה בכך\u0004 שאין הבגד נמצא על הבשר ממש?","ועוד, \u0003כינה\u0004 שנמצאת עליו, \u0003מהו\u0004 \u0003שתחוץ\u0004 האם תיחשב חציצה?","ומפרטים: כינה \u0003מתה לא תבעי\u0004 \u0005[תישאל]\u0006 \u0003לך, דודאי\u0004 \u0003חייצא\u0004 \u0005[שודאי\u0006 היא \u0005חוצצת],\u0006 כמו כל דבר אחר. אבל כינה \u0003חיה, מאי\u0004 \u0005[מה\u0006 דינה\u0005]?\u0006 \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]:\u0006 \u0003כיון דאתא ואזלא\u0004 \u0005[שבאה והולכת]\u0006 שהיא מצויה עליו כל הזמן, \u0003רביתא היא ולא חייצא\u0004 \u0005[כמו גידול\u0006 של בשרו \u0005היא ואינה חוצצת],\u0006 \u0003או דלמא כיון דקפיד\u0004 \u0003עלה\u0004 — \u0003חייצא\u0004 \u0005[שמא כיון שהוא מקפיד עליה\u0006 — \u0005חוצצת]?\u0006","ושואלים עוד: \u0003עפר,\u0004 \u0003מהו שיחוץ?\u0004 ותוהים: \u0003עפר ודאי חייץ\u0004 \u0005[חוצץ]!\u0006 \u0003אלא\u0004 לא עפר ממש, אלא \u0003אבק עפר\u0004 כלומר, אבק כלשהו, \u0003מהו?\u0004","ועוד שאלו: \u0003בית השחי\u0004 כלומר, החלל שנמצא בבית השחי אם אין הבגד מהודק לגופו לגמרי, \u0003מהו שיחוץ?\u0004 האם \u0003\"על\u0004 \u0003בשרו\" בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003והא ליכא\u0004 \u0005[והרי אין כאן],\u0006 ולכן צריך להיות הדוק לגופו לגמרי, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003דרך לבישה בכך?\u0004","וכן \u0003הכניס ידו לתוך חיקו\u0004 מתחת לבגד \u0003מהו?\u0004 \u0003גופו מי חייץ\u0004 \u0005[האם חוצץ]\u0006 \u0003או לא?\u0004","ועוד שואלים: \u0003נימא\u0004 \u0005[חוט],\u0006 \u0003מהו שתחוץ?\u0004 ותוהים: \u0003נימא\u0004 \u0005[חוט]\u0006 \u0003ודאי חייצא\u0004 \u0005[חוצצת]!\u0006 \u0003אלא נימא\u0004 \u0005[חוט]\u0006 \u0003מדולדלת\u0004 שעומדת להיקרע מן הבגד, \u0003מהו\u0004 דינה, האם כיוון שהיא מדולדלת נחשבת כמנותקת וחוצצת?","ועוד, \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003מר בר רב אשי: יצא שערו בבגדו,\u0004 ששער ראשו נכנס מתחת לכתונת \u0003מהו?\u0004 האם \u0003שערו כגופו דמי\u0004 \u0005[נחשב]\u0006 \u0003או לאו\u0004 \u0005[לא]\u0006 \u0003כגופו דמי\u0004 \u0005[נחשב]?\u0006","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' זירא: תפילין, מהו שיחוצו\u0004 בכהן? ומפרטים: \u0003אליבא דמאן דאמר\u0004 \u0005[לפי שיטתו של מי שאומר]\u0006 ש\u0003לילה לאו\u0004 \u0005[אין]\u0006 \u0003זמן תפילין הוא\u0004 — \u0003לא תבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 שאלה זו, \u0003כיון\u0004 שב\u0003לילה חייצי\u0004 \u0005[\u0006הם \u0005חוצצות],\u0006 ב\u0003יום נמי חייצי\u0004 \u0005[גם כן\u0006 הם \u0005חוצצים].\u0006 \u0003כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 השאלה \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]:\u0006 \u0003לילה זמן תפילין,\u0004 ואם כן, \u0003מאי\u0004 \u0005[מה]\u0006 הדין? \u0003האם\u0004 \u0003מצוה דגופיה חייץ\u0004 \u0005[ש\u0006אדם מקיים \u0005בגופו חוצץ]\u0006 \u0003או לא חייץ\u0004 \u0005[חוצץ]?\u0006","\u0003איגלגל מילתא ומטא\u0004 \u0003לקמיה\u0004 \u0005[התגלגל הדבר,\u0006 השאלה הזו של ר' זירא \u0005והגיעה לפני]\u0006 \u0003ר' אמי, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תלמוד ערוך הוא בידינו, תפילין חוצצות.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0003]\u0004 ממה ששנינו בברייתא: \u0003כהנים בעבודתן ולוים בדוכנן\u0004 כשהם שרים על גבי הדוכן, \u0003וישראל במעמדן\u0004 אנשים מישראל הבאים למקדש להיות שם בזמן הקרבת קרבנות הציבור — \u0003פטורין מן התפלה ומן התפילין,\u0004 מפני שהם עוסקים במצוה, והעוסק במצוה פטור ממצוות אחרות. \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 להבין מן הלשון \"פטורין\" ש\u0003אם הניחן\u0004 בכל זאת — \u0003אינן חוצצות?\u0004 ודוחים: \u0003לא,\u0004 \u0003אם הניחן\u0004 — \u0003חוצצות.\u0004","ותוהים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 הלשון \u0003\"פטורים\"\u0004 אינה מדוייקת, \u0003\"אסורים\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005],\u0006 שהרי יש בהן חציצה בכהנים! ומשיבים: \u0003כיון דאיכא\u0004 \u0005[שיש\u0006 ברשימה זו\u0005]\u0006 גם \u0003לוים וישראל דלא מתנו ליה\u0004 \u0005[שאי\u0006 אפשר \u0005לשנות שם]\u0006 \u0003\"אסור\",\u0004 שהרי להם בוודאי מותר הדבר, שאין בהם דין חציצה, \u0003משום הכי תנא\u0004 \u0005[כך שנה]\u0006 \u0003\"פטורין\",\u0004 שהיא משותפת לכולם.","ושואלים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 תפילין, \u0003אם הניחן\u0004 הכהן \u0003אינן חוצצות!\u0004 ומתרצים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 של \u0003יד,\u0004 שהן חוצצות בין הבגד והבשר, \u0003הא\u0004 \u0005[זו]\u0006 של \u0003ראש\u0004 אינן חוצצות.","ושואלים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 תפילין של \u0003יד? דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ילבש על בשרו\"\u0004 (ויקרא ו, ג), ללמד \u0003שלא יהא דבר חוצץ בינו\u0004 (בין הבגד) \u0003לבשרו,\u0004 של \u0003ראש נמי כתיב\u0004 \u0005[גם כן נאמר]:\u0006 \u0003\"ושמת המצנפת על ראשו\"\u0004 (שמות כט, ו), ויהיו איפוא התפילין חציצה בין המצנפת והראש!","ומשיבים: \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003שערו\u0004 של הכהן הגדול \u0003היה נראה בין ציץ למצנפת,\u0004 שהציץ היה על המצח, נמוך מקו השיער, והמצנפת היתה גבוהה ממנו,"],["\u0003ששם מניחין תפילין,\u0004 ואם כן לא היה בכך חציצה.","שנינו במשנה: \u0003מחוסר כיפורים\u0004 עבודתו פסולה. ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שהוא פוסל? \u0003אמר\u0004 \u0003רב הונא, אמר קרא\u0004 \u0005[המקרא]\u0006 לגבי הקרבן שמביאה היולדת: \u0003\"וכפר עליה הכהן וטהרה\"\u0004 (ויקרא יב, ח), \u0003\"טהרה\"\u0004 — \u0003מכלל שהיא טמאה\u0004 עד עכשיו. משמע שכל זמן שלא כיפר עליה הרי היא נחשבת כטמאה, וטמא פוסל כמו שלמדנו (ראה לעיל זבחים יז,א).","שנינו במשנה: \u0003ושלא רחוץ ידים ורגלים\u0004 פוסל עבודה. מנין? \u0003אתיא\u0004 \u0005[בא\u0006 נלמד הדבר\u0005]\u0006 בגזירה שווה \u0003\"חקה\" \"חקה\" ממחוסר בגדים,\u0004 שמחלל עבודה (ראה לעיל זבחים יז,ב).","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כהן גדול שלא טבל ושלא קידש\u0004 ידיו ורגליו ביום הכיפורים \u0003בין בגד לבגד\u0004 כשהוא מחליף מבגדי זהב לבגדי לבן לצורך העבודות הנעשות בהיכל, וכשהוא חוזר ולובש בגדי זהב לעבודות הנעשות בחוץ, \u0003ובין עבודה לעבודה, ועבד\u0004 — \u0003עבודתו כשרה.\u0004 אבל \u0003אחד כהן גדול ואחד\u0004 \u0003כהן הדיוט שלא קידש ידיו ורגליו\u0004 תחילה ב\u0003שחרית ועבד\u0004 בלי קידוש — \u0003עבודתו פסולה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אסי לר' יוחנן: מכדי\u0004 \u0005[הרי]\u0006 \u0003חמש טבילות ועשרה קדושין\u0004 שעושה כהן גדול ביום הכיפורים \u0003דאורייתא\u0004 \u0005[מן התורה\u0006 הן\u0005],\u0006 \u0003ו\"חקה\" כתיב בהו\u0004 \u0005[נאמר בהם]\u0006 (ויקרא טז, לד) — \u0003ליעכבו\u0004 \u0005[שיעכבו]\u0006 ושיפסלו את העבודה אם לא עשאם!","\u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בפרשת יום הכיפורים: \u0003\"ולבשם\"\u0004 (ויקרא טז, ד), לומר: \u0003לבישה\u0004 של בגדים הראויים \u0003מעכבת, ואין דבר אחר מעכב.\u0004","\u0003צהבו\u0004 (האירו) \u0003פניו\u0004 של רב אסי, ששמח בתשובה הזו. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003וי\"ו אאופתא כתבי\u0004 \u0005[על גזר עץ כתבתי]\u0006 \u0003לך\u0004 כלומר, לא אמרתי לך הסבר שיש בו ממש, כי \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שרק לבישת בגדים מעכבת, \u0003דצפרא\u0004 \u0003נמי\u0004 \u0005[\u0006קידוש \u0005של שחרית\u0006 של יום הכיפורים \u0005גם כן]\u0006 לא היה צריך לעכב, ובברייתא נאמר שהוא מעכב.","ומביאים לכך תשובה ממה ש\u0003אמר חזקיה: אמר קרא\u0004 \u0005[הכתוב]\u0006 לענין קידוש ידים ורגלים: \u0003\"והיתה להם חק עולם לו\u0004 (לאהרן, הכהן הגדול) \u0003ולזרעו לדרתם\"\u0004 (שמות ל, כא), להשוות את אהרן לבניו, ולומר: \u0003דבר המעכב\u0004 בענין זה \u0003בזרעו\u0004 (שאר הכהנים) והוא קידוש של שחרית — \u0003מעכב בו\u0004 בכהן הגדול בעבודת יום הכיפורים, \u0003דבר שאינו מעכב בזרעו\u0004 — \u0003אין מעכב בו,\u0004 ולפיכך, קידוש בין בגד לבגד ובין עבודה לעבודה, שאין בו צורך בשאר הכהנים — אינו פוסל אף בכהן הגדול.","\u0003ר' יונתן אמר, מהכא\u0004 \u0005[מכאן]\u0006 יש ללמוד דבר זה, שנאמר בכיור: \u0003\"ורחצו ממנו משה ואהרן ובניו\"\u0004 (שמות מ, לא), לומר: \u0003דבר המעכב בבניו מעכב בו, דבר שאינו מעכב בבניו אין מעכב בו.\u0004","ושואלים: \u0003ר' יונתן מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר מ\u0004הכתוב שאמר \u0003חזקיה?\u0004 ומשיבים, \u0003אמר\u0004 \u0005[יכול היה לומר]\u0006 \u0003לך: ההוא\u0004 אותו כתוב \"והיתה לו חק עולם לו ולזרעו לדורותם\", כדי ללמד שדין זה נוהג \u0003לדורות הוא דכתיב\u0004 \u0005[שנאמר],\u0006 לא רק באהרן ובבניו המוזכרים באותו פסוק, אלא בכל זרעו לדורות, ולא לשם היקש בין זרעו לבינו.","\u0003ואידך מאי טעמא\u0004 \u0005[והאחר\u0006 חזקיה \u0005מה טעם]\u0006 \u0003לא אמר מהאי\u0004 \u0005[מזו]\u0006 שהביא ר' יונתן? ומשיבים: \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 הפסוק הזה \u0003לכ\u0004 מו שהסבירו \u0003ר' יוסי בר'\u0004 \u0003חנינא,\u0004 ש\u0003אמר ר' יוסי בר' חנינא: כל כיור שאין בו\u0004 מים \u0003כדי לקדש ארבעה כהנים ממנו\u0004 — \u0003אין מקדשין בו, שנאמר: \"ורחצו ממנו משה ואהרן ובניו\",\u0004 ומכאן שהיו בו מים כדי שיוכלו לרחוץ ממנו ארבעה: משה ואהרן — שניים, ו\"בניו\" — שניים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כיצד מצות קידוש\u0004 של ידים ורגלים? \u0003מניח\u0004 הכהן את \u0003ידו הימנית על גבי רגלו הימנית וידו השמאלית על גבי רגלו השמאלית ו\u0004כך \u0003מקדש\u0004 במים היורדים מן הכיור. \u0003ר' יוסי בר' יהודה אומר: מניח\u0004 \u0003שתי ידיו זו על גב זו, ו\u0004מניחן \u0003על גבי שתי רגליו\u0004 המונחות גם הן \u0003זו על גבי זו, ומקדש.\u0004 \u0003אמרו לו: הפלגתה\u0004 בדבריך, \u0003אי אפשר לעשות כן\u0004 שיעמוד באופן זה.","ואומרים: \u0003שפיר קאמרי ליה\u0004 \u0005[יפה אמרו לו]\u0006 שאי אפשר לעמוד כן! \u0003אמר רב יוסף:\u0004 הכוונה היא \u0003ש\u0004\u0003חבירו מסייעו\u0004 ומחזיק אותו שלא יפול.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]?\u0006 \u0003אמר אביי:\u0004 לגבי \u0003עמידה מן הצד\u0004 על ידי סיוע \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 מחלוקת, שלדעת חכמים אינה נחשבת כעמידה, ולכן אינם סבורים כדברי ר' יוסי בר' יהודה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב סמא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אשי לרבינא: וליתיב מיתב ולקדש\u0004 \u0005[ושישב בישיבה ויקדש],\u0006 שאז יכול לרחוץ ידים ורגלים בבת אחת! אמר לו: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"בבואם אל אהל מועד ירחצו מים ולא ימותו או בגשתם אל המזבח \u0003לשרת\"\u0004 (שמות ל, כ), \u0003ושירות מעומד הוא\u0004 דווקא, שנאמר \"לעמוד לשרת\" (דברים יח, ה).","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003קידש ידיו ורגליו ביום\u0004 — \u0003אין צריך לקדש בלילה\u0004 שלאחריו, אבל אם קידש ידיו ורגליו \u0003בלילה\u0004 — \u0003צריך לקדש ביום, דברי רבי, שהיה רבי אומר: לינה\u0004 (כלומר, לילה שעובר) \u0003מועלת\u0004 (פועלת ומשפיעה) גם \u0003ב\u0004ענין \u0003קידוש ידים ורגלים,\u0004 כמו על כל דבר שנתקדש לעבודת המקדש בכל יום ויום, וכיוון שעבר הלילה (בעמוד השחר) צריך לחזור ולקדש. \u0003ר' אלעזר בר'\u0004 \u0003שמעון אומר: אין לינה מועלת בקידוש ידים ורגלים\u0004 וכל זמן שממשיך בעבודתו אינו צריך לקדש.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003היה עומד ומקריב על גבי מזבח כל הלילה, לאורה\u0004 בעלות השחר, כשמגיע אור יום, \u0003טעון קידוש ידים ורגלים, דברי רבי.\u0004 ואילו \u0003ר' אלעזר בר' שמעון אומר: כיון שקידש ידיו ורגליו מתחילת עבודה, אפילו\u0004 המשיך לעבוד \u0003מיכן ועד עשרה ימים אינו צריך לקדש.\u0004","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 שייאמרו שתי המחלוקות\u0003,\u0004 \u0003דאי אשמעינן קמייתא\u0004 \u0005[שאילו היה משמיע לנו\u0006 רק \u0005את הראשונה]\u0006 היינו אומרים כך: \u0003בההיא קאמר\u0004 \u0005[באותה\u0006 מחלוקת \u0005אומר]\u0006 \u0003רבי\u0004 שצריך לחזור ולקדש ביום, משום \u0003דפסק ליה\u0004 \u0005[שהפסיק לו]\u0006 \u0003מעבודה לעבודה\u0004 אחרת, \u0003אבל בהא דלא פסק ליה\u0004 \u0005[בזו,\u0006 השניה, \u0005שלא פסק לו]\u0006 שהוא ממשיך עדיין באותה עבודה — \u0003אימא מודי ליה\u0004 \u0005[אמור שמודה לו]\u0006 \u0003רבי לר'\u0004 \u0003אלעזר בר' שמעון\u0004 שאינו צריך לחזור ולקדש. ולהיפך, \u0003ואי אשמעינן בהא\u0004 \u0005[ואילו היה משמיע לנו בזו\u0006 בשניה בלבד\u0005]\u0006 היינו אומרים: \u0003בהא קאמר\u0004 \u0005[בזו אומר]\u0006 \u0003ר' אלעזר בר' שמעון\u0004 שאינו צריך קידוש, משום שהוא עדיין מצוי באותה עבודה, \u0003אבל בהא\u0004 \u0005[בזו]\u0006 כשסיים עבודה ומתחיל אחרת, \u0003אימא מודי ליה\u0004 \u0005[אמור שמודה לו]\u0006 \u0003לרבי,\u0004 על כן \u0003צריכא\u0004 \u0005[צריכה]\u0006 שתובא המחלוקת בשני המקרים.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רבי? דכתיב\u0004 \u0005[שנאמר]\u0006 מתי רוחצים הכהנים ידיהם ורגליהם: \u0003\"בגשתם\u0004 אל המזבח לשרת להקטיר\" (שמות ל, כ) — כאשר ניגש ומתחיל עבודה, ובשחר מתחילה עבודה חדשה במזבח. \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אלעזר בר' שמעון? דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בבאם\u0004 אל אוהל מועד\" (שמות ל, כ), הרי שחיוב הרחיצה קשור בתחילת ביאתו של הכהן לאוהל מועד עד שיצא.","ושואלים: \u0003ואידך נמי\u0004 \u0005[והאחר גם כן],\u0006 רבי, \u0003הא כתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"בבאם\"!\u0004 ומשיבים: \u0003אי כתיב\u0004 \u0005[אם\u0006 היה \u0005כתוב]\u0006 רק \u0003\"בגשתם\" ולא כתיב\u0004 \u0005[\u0006היה \u0005כתוב]\u0006 \u0003\"בבאם\", הוה\u0004 \u0003אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003על כל גישה וגישה\u0004 שניגש לכל עבודה צריך לרחוץ ידיו, לכן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]:\u0006 \u0003\"בבאם\"\u0004 לומר שזקוק לכך רק פעם אחת ביום, כשהוא נכנס לעבודה.","ושואלים: \u0003ואידך נמי\u0004 \u0005[והאחר גם כן],\u0006 ר' אלעזר בר' שמעון, \u0003הא כתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"בגשתם\"!\u0004 והוא משיב: \u0003אי כתיב\u0004 \u0005[אם\u0006 היה \u0005כתוב]\u0006 \u0003\"בבאם\" ולא\u0004 \u0003כתיב\u0004 \u0005[\u0006היה \u0005כתוב]\u0006 \u0003\"בגשתם\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003אפילו\u0004 על \u0003ביאה\u0004 \u0003ריקנית\u0004 כלומר, כשנכנס בלי לעבוד צריך קידוש ידים ורגלים.","ותוהים: על \u0003ביאה ריקנית\u0004 צריך לקדש? \u0003הא כתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"לשרת\"\u0004 (שמות ל, כ)! \u0003אלא\u0004 צריך לומר כך: \u0003\"בגשתם\" מיבעי ליה\u0004 \u0005[צריך לו]\u0006 \u0003לכ\u0004 מו שאמר \u0003רב אחא בר יעקב,\u0004 ש\u0003אמר\u0004 \u0003רב אחא בר יעקב: הכל מודים בקידוש שני\u0004 של ידים ורגלים שמקדש הכהן הגדול לאחר כל טבילה ביום הכיפורים — \u0003כשהוא לבוש\u0004 בבגדי כהונה \u0003מקדש,\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"או בגשתם\",\u0004 לומר שצריך לרחוץ ידיו ורגליו \u0003מי\u0004 \u0003שאינו מחוסר אלא גישה בלבד, יצא זה\u0004 אם אינו לבוש עדיין, \u0003שמחוסר לבישה וגישה,\u0004 ולכן ילבש בגדיו תחילה ואחר כך יקדש.","ושואלים: מה שנאמר \u0003\"להקטיר אשה\"\u0004 (שמות ל, כ) \u0003למה לי?\u0004"],["ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר],\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 קידוש ידים ורגלים אמורים דווקא ב\u0003עבודה\u0004 \u0003דמעכבא\u0004 \u0005[שמעכבת]\u0006 את ה\u0003כפרה,\u0004 שהקרבן אינו מכפר בלעדיה, כגון העבודות הקשורות בזריקת הדם על המזבח, \u0003אבל עבודה\u0004 ש\u0003לא מעכבא\u0004 \u0005[מעכבת]\u0006 \u0003כפרה\u0004 — \u0003לא,\u0004 והקטרת חלבים ואיברים אינה מעכבת כפרה, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 הכתוב \"להקטיר אשה לה'\" שגם להקטרה צריך קידוש ידים ורגלים.","ושבים למחלוקת רבי ור' אלעזר בר' שמעון. \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי אמר\u0004 בשם \u0003ר' יוחנן, בעי\u0004 \u0005[שאל]\u0006 \u0003אילפא:\u0004 \u0003לדברי\u0004 ר' אלעזר בר' שמעון \u0003האומר אין לינה מועלת\u0004 (פועלת, פוסלת) \u0003בקידוש ידים ורגלים,\u0004 ומשעלה עמוד השחר אין צורך לחזור ולקדש, \u0003מי כיור\u0004 (המים המצויים בתוך הכיור) \u0003מהו שיפסלו\u0004 בלינה? וצדדי השאלה, \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]:\u0006 \u0003הני\u0004 \u0003למאי\u0004 \u0005[\u0006מים \u0005אלה למה\u0006 הם מיועדים\u0005]?\u0006 \u0003לקידוש ידים ורגלים,\u0004 והרי לענין \u0003קידוש ידים ורגלים\u0004 \u0003גופייהו\u0004 \u0005[הם עצמם]\u0006 \u0003לא פסול בהו\u0004 \u0005[פוסלת בהם]\u0006 \u0003לינה,\u0004 אם כן הוא הדין למי הכיור המיועדים לכך. \u0003או דלמא\u0004 \u0005[שמא]\u0006 נאמר כך: \u0003כיון דקדוש להו\u0004 \u0005[שהתקדשו להם]\u0006 המים \u0003בכלי שרת\u0004 (הוא הכיור, שהוא מכלי הקודש) \u0003מיפסלי\u0004 \u0005[נפסלים\u0006 הם\u0005]\u0006 בלינה, כמו כל דבר שנתקדש בכלי שרת?","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין אמר: ר' ירמיה אמר ר' אמי אמר ר' יוחנן: הדר פשיט\u0004 \u0005[חזר\u0006 ו\u0005פתר]\u0006 \u0003אילפא\u0004 את השאלה הזו ואמר: \u0003כמחלוקת בזו\u0004 בענין לינה האם היא מועלת לענין קידוש, \u0003כך מחלוקת בזו\u0004 בענין מי כיור, ור' אלעזר בר' שמעון סבור, איפוא, כי אין לינה מועלת בהם.","\u0003אמר לפניו ר' יצחק בר ביסנא\u0004 לפני ר' ירמיה: \u0003רבי, אתה אומר כן?\u0004 אין הדבר כך, \u0003אלא הכי\u0004 \u0005[כך]\u0006 \u0003אמר\u0004 \u0003ר' אסי אמר ר' יוחנן [משמיה\u0004 \u0005[משמו]\u0006 של \u0003אילפא]: כיור שלא שקעו מבערב\u0004 במי הבור המיועד לכך — \u0003מקדש ממנו לעבודת לילה, ולמחר אינו מקדש.\u0004","\u0003והוינן\u0004 \u0005[והיינו עוסקים]\u0006 \u0003בה\u0004 בשאלה זו: \u0003למחר אינו מקדש\u0004 האם כוונתו ש\u0003לא צריך לקדוש\u0004 אחר, שאין לינה מועלת בקידוש ידים ורגלים, וקידוש בלילה מועיל גם ליום. \u0003או דלמא איפסלו\u0004 \u0005[שמא נפסלו]\u0006 המים \u0003בלינה\u0004 ולכן אינו יכול לקדש מהם? \u0003ולא פשיט לן\u0004 \u0005[פתר לנו]\u0006 ר' אמי בעיה זו, \u0003ומר קא פשיט ליה מיפשיט\u0004 \u0005[ואדוני,\u0006 ר' ירמיה, \u0005פותר אותה\u0006 משמו\u0005]\u0006 שאילפא אכן החליט בענין זה.","ומנסים לפתור שאלה זו, ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: בין האנשים שנזכרו לשבח בענייני המקדש \u0003בן קטין,\u0004 שהוא \u0003עשה\u0004 (נתן מכספו כדי לעשות) \u0003שנים עשר דד\u0004 (ברזים) \u0003לכיור, אף הוא עשה מוכני\u0004 (כלי גלגלים) \u0003לכיור שלא יהיו מימיו נפסלין בלינה,\u0004 שהיו משקעים את הכיור בתוך בור המים. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 שיטת \u0003ר' אלעזר בר' שמעון היא?\u0004 ונמצא שאף הוא מודה שמי כיור נפסלים בלינה! ודוחים: \u0003לא,\u0004 שיטת \u0003רבי היא.\u0004","ושואלים: \u0003והא\u0004 \u0005והרי]\u0006 \u0003מדרישא\u0004 \u0005[מ\u0006כיון \u0005שתחילתה\u0006 של אותה משנה\u0005]\u0006 ברור שהיא שיטת \u0003ר' אלעזר בר' שמעון, סיפא נמי\u0004 \u0005[סופה גם כן]\u0006 שיטת \u0003ר' אלעזר בר' שמעון!\u0004 ומנין שתחילתה כשיטתו היא?","\u0003דקתני רישא\u0004 \u0005[ששנה בתחילה]\u0006 של אותו פרק במסכת יומא: \u0003בא לו\u0004 הכהן הגדול \u0003אצל פרו, ו\u0004אותו \u0003פר היה עומד בין האולם ולמזבח, ראשו\u0004 של הפר \u0003ל\u0004כיוון \u0003דרום\u0004 (ואחוריו לצפון) \u0003ופניו\u0004 מופנים הצידה \u0003למערב, והכהן עומד במזרח\u0004 בצד הפר \u0003ופניו למערב,\u0004 ושם היה שוחטו. \u0003מאן\u0004 \u0005[מי]\u0006 \u0003שמעת ליה\u0004 \u0005[אותו]\u0006 ש\u0003אמר: בין האולם ולמזבח\u0004 אף הוא \u0003צפון\u0004 ואפשר לשחוט בו קדשי קדשים? שיטת \u0003ר' אלעזר בר' שמעון\u0004 היא,","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003איזהו צפון\u0004 לענין שחיטת קדשי קדשים שנאמר בהם \"ושחט אותו על ירך המזבח צפונה לפני ה'\" (ויקרא א, יא)? \u0003מקיר מזבח\u0004 \u0003צפוני ועד כותל עזרה צפוני וכנגד כל המזבח\u0004 כלומר, לאורך כל כותלו הצפוני של המזבח — \u0003כולו צפון,\u0004 אלו \u0003דברי ר' יוסי בר' יהודה,\u0004 \u0003ר' אלעזר בר' שמעון מוסיף אף\u0004 את השטח ש\u0003בין האולם ולמזבח\u0004 מערבה מן המזבח, כל שהוא בחצי הצפוני של העזרה. \u0003רבי מוסיף: אף\u0004 חציו הצפוני של השטח שממזרח למזבח, \u0003מקום דריסת רגלי הכהנים\u0004 \u0003ומקום דריסת רגלי ישראל,\u0004 אף הוא צפון. \u0003אבל\u0004 חלקה הצפוני מערבי של העזרה, \u0003מן\u0004 בית \u0003החליפות ולפנים\u0004 כלומר, השטח המצוי לצפונו של האולם וההיכל — \u0003הכל מודים ש\u0004הוא \u0003פסול,\u0004 שאינו בכלל ירך המזבח!","ודוחים הוכחה זו: \u0003ותסברא\u0004 \u0005[וכי סבור אתה]\u0006 שמשנה זו במסכת יומא שיטת \u0003ר' אלעזר בר' שמעון היא ולא רבי? [השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003רבי]\u0004 שהוסיף את מזרח העזרה בכלל צפון על דברי \u0003ר' יוסי בר'\u0004 \u0003יהודה\u0004 הוא \u0003מוסיף,\u0004 על דברי \u0003ר' אלעזר בר' שמעון לא מוסיף?\u0004 בוודאי אף הוא מודה שבין האולם ולמזבח צפון הוא. ויתכן איפוא לומר שמשנה זו, וגם המשכה ממנו משמע שמימיו של הכיור נפסלים בלינה, כולה כשיטת רבי!","ומשיבים: \u0003אנן הכי קאמרינן\u0004 \u0005[אנו כך אומרים אנו]:\u0006 \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 שמשנה זו כשיטת \u0003רבי\u0004 \u0003היא, לוקמה\u0004 \u0005[שיעמיד\u0006 את הפר\u0005]\u0006 \u0003במקום דריסת רגלי כהנים ובמקום דריסת\u0004 \u0003רגלי ישראל,\u0004 שלשיטתו אף הוא צפון. ואם נאמר דווקא בין האולם ולמזבח משמע שמשנה זו שלא כשיטתו, אלא כשיטת ר' אלעזר בר' שמעון.","ותוהים: \u0003אלא מאי\u0004 \u0005[מה]\u0006 אתה אומר — שדווקא שיטת \u0003ר' אלעזר בר' שמעון היא? לוקמה\u0004 \u0005[שיעמיד אותו\u0006 את הפר\u0005]\u0006 בשטח ש\u0003מקיר מזבח צפוני עד כותל עזרה צפוני,\u0004 שהכל מודים שהוא צפון! \u0003אלא מאי אית לך למימר\u0004 \u0005[מה יש לך לומר]?\u0006 מדוע אין מעמידים שם את הפר — \u0003משום חולשא\u0004 של ה\u0003כהן גדול\u0004 שכל עבודות היום עליו, ולכן מקרבים ככל האפשר את הפר להיכל, שם הוא צריך לזרוק את דמו, \u0003הכא נמי\u0004 \u0005[כך גם כן]\u0006 יכול אתה לומר שמשנה זו היא כשיטת רבי, שמעמידים את הפר בין האולם ולמזבח, הטעם הוא \u0003משום חולשא\u0004 של ה\u0003כהן\u0004 ה\u0003גדול.\u0004","\u0003אמר ר' יוחנן:\u0004 כהן ש\u0003קידש ידיו ורגליו לתרומת הדשן\u0004 שהיא העבודה הראשונה במקדש, הנעשית בקרות הגבר, עוד לפני עלות השחר, \u0003למחר\u0004 לאחר שיעלה עמוד השחר \u0003אינו צריך לקדש\u0004 שוב, \u0003שכבר קידש מתחילת עבודה.\u0004","ושואלים: \u0003למאן\u0004 \u0005[ל\u0006פי שיטת \u0005מי]\u0006 אמר דבר זה? \u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004דעת \u0003רבי, האמר\u0004 \u0005[הרי\u0006 הוא \u0005אומר]:\u0006 ש\u0003פסלה לינה\u0004 בעלות השחר, ולפיכך צריך לקדש עוד פעם בבוקר! \u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004דעת \u0003ר' אלעזר בר' שמעון, האמר\u0004 \u0005[הרי אמר]:\u0006 כיון שקידש ידיו ורגליו בתחילת עבודתו \u0003אין צריך\u0004 הכהן \u0003לקדש\u0004 שוב, \u0003אפילו מיכן ועד עשרה ימים,\u0004 ומדוע הזכיר דווקא מי שקידש לפני תרומת הדשן?","\u0003אמר אביי: לעולם\u0004 אמר ר' יוחנן \u0003ל\u0004שיטת \u0003רבי, ולינה\u0004 שפוסלת בקידוש ידים ורגלים — \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 \u0003היא,\u0004 שגזרו על כל כהן לחזור ולקדש בכל בוקר, גם אם לא הפסיק בעבודה. \u0003ומודי דמקרות הגבר ועד צפרא לא פסלה\u0004 \u0005[ומודה\u0006 רבי \u0005שמקריאת הגבר,\u0006 שאז נעשית תרומת הדשן, \u0005ועד הבוקר אין פוסלת]\u0006 ה\u0003לינה,\u0004 שאין מקום לגזור במקרה כזה","\u0003.\u0004 \u0003רבא אמר: לעולם,\u0004 שיטת \u0003ר' אלעזר בר' שמעון [היא,\u0004 הסבור שאין לינה פוסלת. \u0003וראה ר' יוחנן דבריו]\u0004 והסכים להם \u0003בתחילת עבודה,\u0004 שתרומת הדשן, אף שהיא נעשית קודם השחר, תחילת עבודת היום הבא היא. \u0003ולא\u0004 קיבל את דבריו \u0003בסוף עבודה,\u0004 שאם קידש כהן ידיו לשם עבודות לילה שהן סיום של יום האתמול, כגון הקטר חלבים — צריך לחזור ולקדש עם בוקר. אבל לדעת רבי — צריך לקדש לאחר עלות השחר.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו במסכת תמיד: \u0003ראוהו אחיו הכהנים\u0004 את הכהן שהרים את תרומת הדשן \u0003שירד\u0004 מן המזבח, \u0003והם\u0004 הכהנים האחרים \u0003רצו ובאו, מיהרו וקידשו ידיהם ורגליהם מן הכיור.\u0004 ואנו מניחים כי כהנים אלה כבר עבדו במשך הלילה."],["\u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003אביי דמוקים לה\u0004 \u0005[שמעמיד אותה\u0006 את שיטת ר' יוחנן\u0005]\u0006 \u0003כרבי, ו\u0004סבור ש\u0003מודי\u0004 \u0005[מודה]\u0006 \u0003רבי\u0004 ש\u0003מקרות הגבר עד צפרא\u0004 \u0005[הבוקר]\u0006 \u0003לא פסלה\u0004 \u0005[פוסלת]\u0006 ה\u0003לינה, הא מני\u0004 \u0005[\u0006משנה \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 כשיטת \u0003רבי היא,\u0004 שכהנים שעבדו בלילה מועלת בהם לינה בעמוד השחר, ומכל מקום יכולים הם עכשיו לקדש ידיהם ורגליהם, ושוב לא ייפסלו בלינה.","\u0003אלא לרבא דמוקים לה\u0004 \u0005[שמעמיד אותה]\u0006 \u0003כ\u0004דעת \u0003ר' אלעזר בר' שמעון, אבל ל\u0004דעת \u0003רבי מקרות הגבר עד צפרא פסלה\u0004 \u0005[מקריאת הגבר עד הבוקר פוסלת]\u0006 ה\u0003לינה, הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003רבי\u0004 — הרי גם אם יקדשו כעת ידיהם ורגליהם, מכל מקום בעלות השחר \u0003פסלה\u0004 \u0005[פוסלת]\u0006 \u0003לינה.\u0004 \u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003ר' אלעזר בר' שמעון, הא\u0004 \u0005[הרי]\u0006 \u0003אמר:\u0004 כהן שקידש ידיו ורגליו והחל בעבודה — \u0003אפילו מיכן ועד עשרה ימים אינו צריך לקדש\u0004 ולפיכך, אותם כהנים שעסקו בלילה בהקטרת חלבים, אינם צריכים קידוש נוסף!","ודוחים: \u0003לעולם\u0004 יש לפרש שהיא \u0003כ\u0004שיטת \u0003ר' אלעזר בר' שמעון, והכא במאי עסקינן\u0004 \u0005[וכאן במה אנו עוסקים]\u0006 \u0003בכהני חדתי\u0004 \u0005[בכהנים חדשים]\u0006 שלא עבדו במקדש בלילה, אלא מתחילים בעבודתם בבוקר, ולדעת הכל צריכים לקדש.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003יציאה\u0004 מן המקדש \u0003מהו שתועיל\u0004 ותפסול \u0003בקידוש ידים ורגלים\u0004 להצריך את הכהן לשוב ולקדש? \u0003אם תימצי\u0004 \u0005[תמצא]\u0006 \u0003לומר\u0004 ש\u0003לינה לא פסלה\u0004 \u0005[פוסלת]\u0006 כאשר מגיע עמוד השחר — הרי זה משום \u0003דלא פריש\u0004 \u0005[שאינו פורש]\u0006 מעבודתו, אלא עסוק בה, \u0003אבל יציאה דפריש\u0004 \u0005[ש\u0006הוא \u0005פורש\u0006 מן המקדש\u0003]\u0004 יש לומר כי \u0003אסוחי מסח\u0004 \u0003דעתיה\u0004 \u0005[מסיח\u0006 הוא את \u0005דעתו],\u0006 ומשום כך צריך לשוב לקדש ידיו ורגליו, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון\u0004 ש\u0003בידו לחזור\u0004 בכל רגע \u0003לא מסח\u0004 \u0005[אינו מסיח\u0006 דעתו\u0005]?\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו: \u0003קידש ידיו ורגליו ונטמאו\u0004 ידיו — \u0003מטבילן ואין צריך לקדש,\u0004 קידש ידיו ורגליו ו\u0003יצאו\u0004 — \u0003הרי הן בקדושתן,\u0004 הרי שהיציאה אינה פוסלת!","ודוחים: אם \u0003יצאו\u0004 רק \u0003ידיו לא קמיבעיא לן\u0004 \u0005[נשאלה לנו],\u0006 וודאי אינו צריך קידוש, \u0003כי קמיבעיא לן\u0004 \u0005[כאשר נשאלה לנו]\u0006 היא אם \u0003יצא כל גופו, מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא: \u0003שלא רחוץ ידים ורגלים\u0004 — \u0003מקדש\u0004 ידיו ורגליו \u0003בכלי שרת בפנים,\u0004 ואם \u0003קידש\u0004 ידיו \u0003בכלי שרת בחוץ, או בכלי חול בפנים, או שטבל במי מערה ועבד\u0004 — \u0003עבודתו פסולה,\u0004 לפי שבכל אלה לא קידש ידיו כראוי. ונדייק מכאן: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 משום ש\u0003קידש בכלי שרת בחוץ\u0004 עבודתו פסולה, \u0003הא\u0004 \u0005[אבל]\u0006 אם \u0003קידש בפנים ויצא\u0004 — \u0003עבודתו כשירה.\u0004","ודוחים: \u0003דלמא\u0004 \u0005[שמא]\u0006 מה שנאמר כאן \u0003קידש בכלי שרת בחוץ, היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 לא שיצא הכהן לחוץ וקידש שם, אלא \u0003כגון דאפיק\u0004 \u0005[שהוציא]\u0006 \u0003ידיו לבר\u0004 \u0005[החוצה]\u0006 \u0003וקידש.\u0004 ולפיכך ניתן לדייק רק כך: \u0003הא\u0004 \u0005[אבל]\u0006 אם \u0003קידש בפנים ויצא,\u0004 הרי זה במקרה \u0003דאפיק ידיה לבר\u0004 \u0005[שהוציא ידיו לחוץ],\u0006 ורק אז \u0003כשירה. אבל יצא כל גופו\u0004 עדיין \u0003תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך,\u0004 ולא נפתרה בעיה זו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב זביד לרב פפא, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 מברייתא אחרת: \u0003יצא\u0004 הכהן \u0003חוץ למחיצת חומת העזרה, אם\u0004 יצא כדי \u0003לשהות\u0004 שם זמן ניכר — \u0003טעון טבילה, אם לפי שעה\u0004 בלבד יצא — \u0003טעון קידוש ידים ורגלים.\u0004 הרי שעצם היציאה אף לזמן קצר פוסלת ידיו, וצריך קידוש אחר!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 מכאן אין ראיה, \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שיצא להסך רגליו\u0004 (לצרכים גדולים) והוא מה שאמר שיצא לשהות, \u0003ולהטיל מים\u0004 (לצרכים קטנים) והוא האמור כאן שיצא לפי שעה. ויש לומר כי משום כך צריך קידוש ידים ורגלים, ולא משום עצם היציאה.","ומקשים: דבר זה לא היה צריך לומר, \u0003הא בהדיא\u0004 \u0003קתני לה\u0004 \u0005[הרי בפירוש שנה אותה]\u0006 במשנה: \u0003כל המיסך רגליו\u0004 — \u0003טעון טבילה, וכל המטיל מים\u0004 — \u0003טעון קידוש ידים ורגלים!\u0004 ומשיבים: זו אינה קושיה, \u0003תני והדר\u0004 \u0005מפרש\u0006 \u0005[\u0006הריהו \u0005שונה וחוזר ומפרש]\u0006 בצורה אחרת.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 כהן העוסק ב\u0003פרה\u0004 אדומה, שעבודתה מחוץ למקדש, \u0003ר' חייא בר יוסף אמר:\u0004 לפני עבודתו \u0003מקדש\u0004 ידיו ורגליו \u0003בכלי שרת בפנים,\u0004 כדרך שעושים לפני עבודת הקדשים \u0003ו\u0004אחר כך \u0003יוצא\u0004 ועושה את עבודתה. \u0003ור' יוחנן אמר:\u0004 מקדש ידיו ורגליו \u0003אפילו בחוץ, ואפילו בכלי חול, ואפילו במקידה\u0004 (קערה) \u0003של חרס.\u0004 והרי אפילו לדעת המצריך לקדש בפנים אינו פוסל ידיו ביציאה לחוץ.","\u0003אמר רב פפא: שאני\u0004 \u0005[שונה]\u0006 \u0003פרה, הואיל וכל מעשיה בחוץ\u0004 ולא במקדש \u0003לא פסלה\u0004 \u0005[פוסלת]\u0006 \u0003בה יציאה.\u0004 ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003למה לי\u0004 ש\u0003מקדש\u0004 ידיו לעבודת הפרה? ומשיבים: \u0003כעין עבודה\u0004 של קרבנות \u0003פנים\u0004 עושים גם בפרה אדומה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 שאלה\u0005]:\u0006 \u0003טומאה\u0004 שנטמא הכהן במקדש, \u0003מהו שתועיל ל\u0004הצריכו \u0003קידוש ידים ורגלים\u0004 לאחר שייטהר מטומאתו? \u0003אם תימצי\u0004 \u0005[תמצא]\u0006 \u0003לומר\u0004 ש\u0003יציאה לא פסלה\u0004 \u0005[פוסלת],\u0006 הרי זה משום \u0003דגברא חזי\u0004 \u0005[שהאיש\u0006 על כל פנים \u0005ראוי]\u0006 לעבודה, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 \u0003דגברא\u0004 \u0005[שהאיש]\u0006 \u0003לא חזי\u0004 \u0005[ראוי]\u0006 לעבודה, שהרי נטמא — \u0003אסוחי מסח דעתיה\u0004 \u0005[מסיח\u0006 הוא \u0005דעתו]\u0006 גם משמירת קדושת ידיו. \u0003או דלמא\u0004 \u0005[שמא]\u0006 נאמר: \u0003כיון דהדר חזי\u0004 \u0005[ש\u0006הוא \u0005חוזר\u0006 ונעשה \u0005ראוי]\u0006 מיד על ידי טבילה \u0003[דק ליה\u0004 \u0005[הוא מדקדק]\u0006\u0003] ולא מסח דעתיה\u0004 \u0005[ואינו מסיח דעתו]?\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא: \u0003קידש ידיו ורגליו ונטמאו\u0004 — \u0003מטבילן ואין צריך לקדש.\u0004","ודוחים: \u0003נטמאו ידיו לא מיבעיא לן\u0004 \u0005[נשאלה לנו],\u0006 \u0003[כי מיבעיא לן\u0004 \u0005[כאשר נשאלה לנו]\u0006\u0003] נטמא כל גופו.\u0004 ותוהים: אם נטמא \u0003כל גופו, תיפוק לי\u0004 \u0005[תצא לו]\u0006 הלכה זו ממקום אחר, שהרי כל הטובל לטומאתו, \u0003כיון דבעי למעבד\u0004 \u0005[ש\u0006הוא \u0005צריך לעשות]\u0006 \u0003הערב שמש אסוחי מסח דעתיה\u0004 \u0005[\u0006הוא \u0005מסיח\u0006 את \u0005דעתו]\u0006 בודאי במשך זמן רב זה! ומשיבים: \u0003כגון דאיטמי\u0004 \u0005[שנטמא]\u0006 \u0003סמוך לשקיעת החמה,\u0004 שאינו צריך לשהות הרבה, ואינו מסיח דעתו.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת: \u0003פרה, ר' חייא בר' יוסף אמר: מקדש בכלי שרת בפנים ויוצא. ור' יוחנן אמר: אפילו בחוץ, ואפילו בכלי חול, ואפילו במקידה של חרס.\u0004"],["\u0003והא\u0004 \u0005[והרי]\u0006 ב\u0003פרה דטמויי מטמינן ליה\u0004 \u0005[שאנו מטמאים אותו]\u0006 את העוסק בה לאחר שקידש ידיו ורגליו, \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 לאחר שהביאו את הפרה להר המשחה שמחוץ לירושלים, \u0003מטמאין היו\u0004 את \u0003הכהן השורף את הפרה ומטבילין אותו\u0004 מיד לאחר מכן, ואז היה שורף את הפרה, ולמה היו עושים כן? כדי \u0003להוציא מלבן של צדוקין,\u0004 כלומר, לנהוג באופן פומבי נגד דעתם, \u0003שהיו אומרים\u0004 שפרה אדומה דווקא \u0003במעורבי שמש היתה נעשית\u0004 כלומר, באלה שטבלו ונטהרו לגמרי לאחר ששקעה השמש, ולכן היו מראים לכל שהיא נעשית במי שטבל באותו יום מטומאתו. על כל פנים, ממה שלא הוצרך קידוש נוסף לאחר מכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003לא פסלה\u0004 \u0005[פוסלת]\u0006 \u0003בה\u0004 בפרה \u0003(מחשבת) טומאה\u0004 את קידוש הידים שנעשה מתחילה!","ודוחים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003פרה, הואיל\u0004 ש\u0003טבול יום לא פסיל\u0004 \u0005[פוסל]\u0006 \u0003בה\u0004 כמו שאר קדשים, לכן גם אין טומאה פוסלת את קידוש הידים שלה. ואין ללמוד מכאן לענין קידוש של עבודת המקדש, שכל טומאה פוסלת בה. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שלא מקיימים בפרה דין קידוש כמו בעבודת המקדש, \u0003למה לי\u0004 ש\u0003מקדש\u0004 כלל בפרה? והרי ממילא אין נוהגים בה דיני הקידוש! ומשיבים: במעשה הפרה \u0003כעין עבודה [בעינן\u0004 \u0005[צריכים אנו]\u0006\u0003],\u0004 שייעשה הדבר כדרך עבודה בקודש, שמקדשים ידים לפני העבודה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003מהו לקדש ידיו [ורגליו] בכיור\u0004 עצמו, שישכשך ידיו ורגליו בתוך הכיור? האם לומר כי \"ורחצו אהרן ובניו \u0003ממנו\u0004 את ידיהם ואת רגליהם\" (שמות ל, יט) \u0003אמר רחמנא\u0004 \u0005[הכתוב]\u0006 ובא ללמדנו שדווקא במים היוצאים ממנו ירחצו, \u0003ולא בתוכו, או דלמא\u0004 \u0005[שמא]\u0006 \u0003אפילו בתוכו\u0004 אפשר?","\u0003אמר רב נחמן בר יצחק, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא שהובאה בעמוד הקודם: \u0003או שטבל במי מערה\u0004 (שהם מקוה טהרה) \u0003ועבד\u0004 עבודה — \u0003עבודתו פסולה,\u0004 שאין זה נחשב לקידוש. ונדייק מכאן: \u0003הא\u0004 \u0005[אבל]\u0006 אם עשה כן ב\u0003מי כיור דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003מי מערה,\u0004 בטבילה, \u0003ועבד\u0004 — \u0003עבודתו כשרה.\u0004","ודוחים: \u0003לא,\u0004 אפשר לומר שטבילת ידים בכיור גם היא לא תועיל, אלא \u0003מי מערה איצטריכא ליה\u0004 \u0005[הוצרך לו],\u0006 לומר, \u0003שלא תאמר:\u0004 הרי במים אלה \u0003כל גופו טובל בהן\u0004 ונטהר, \u0003ידיו ורגליו לא כל שכן?\u0004 ולכן משמיע לנו שאין זה מועיל.","\u0003אמר ר' חייא בר יוסף: מי כיור נפסלין\u0004 בלינה לכל עבודה לפי הזמן הראוי לה: \u0003ל\u0004צורך עבודת ה\u0003מתירין\u0004 כלומר, לצורך עבודות המתירות את הקרבן באכילה, כגון זריקת הדם או הקטרת קומץ המנחה, דינם \u0003כ\u0004מו ה\u0003מתירין\u0004 עצמם, שאין עבודתם אלא ביום והם נפסלים בשקיעת החמה. ולא ניתן לקדש ידים ורגלים במים אלה למחרת לצורך עבודות המתירים, אלא אם שיקע את הכיור בבור המיועד לכך קודם שקיעת החמה, ובכך שוב אין המים מצויים בכלי שרת, ואינם נפסלים בלינה. ומצד אחר נפסלים מי הכיור לקידוש \u0003ל\u0004צורך הקטרת \u0003אברים\u0004 על המזבח \u0003כ\u0004מו ה\u0003אברים,\u0004 שהקטרתם כל הלילה, ונפסלים רק אם לא היו משוקעים בבור עם עלות השחר.","\u0003רב\u0004 \u0003חסדא אמר: אף ל\u0004צורך עבודת ה\u0003מתירין אין\u0004 מי הכיור \u0003נפסלין אלא ב\u0004עלות \u0003עמוד השחר\u0004 של היום הבא, \u0003כאברין\u0004 של הקרבנות, שרק אז הם נפסלים. \u0003ור' יוחנן אמר: כיור כיון ששקעו\u0004 בבור בגמר עבודת היום, קודם שקיעת השמש — \u0003שוב אין מעלהו.\u0004","ושואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 שאם לא היה כיור משוקע בשקיעת השמש \u0003לעבודת לילה נמי לא חזי\u0004 \u0005[גם כן אינו ראוי]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אסי אמר ר' יוחנן משמיה\u0004 \u0005[משמו]\u0006 של \u0003אילפא: כיור שלא שקעו מבערב\u0004 — \u0003מקדש ממנו לעבודת לילה\u0004 (כגון הקטרת איברים), אבל \u0003למחר\u0004 לצורך עבודות היום הבא \u0003אינו מקדש,\u0004 לפי שנפסלו המים בלינה. ואם כן אין מי הכיור נפסלים לגמרי עם השקיעה!","ומשיבים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אינו מעלהו\" נמי דקאמר\u0004 \u0005[גם כן שאמר]?\u0006 הכוונה היא שאינו מעלהו \u0003ל\u0004צורך \u0003עבודת יום\u0004 המחר, \u0003אבל לעבודת לילה חזי\u0004 \u0005[ראוי הוא]\u0006 לקדש ממנו.","ומקשים: \u0003[אי הכי\u0004 \u0005[אם כך]\u0006\u0003], היינו\u0004 \u0005[הרי זו]\u0006 בדיוק מה שאמר \u0003ר' חייא בר יוסף,\u0004 שמי הכיור נפסלים לעבודת יום בשקיעה ולעבודת לילה בעמוד השחר, ומה בא ר' יוחנן לחדש?"],["ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל לעניין \u0003גזירת שיקוע,\u0004 שלדעת ר' חייא בר יוסף המים נפסלים בלילה לעבודת היום, אבל לדעת ר' יוחנן אין המים נפסלים בכך, ומכל מקום גזרו חכמים לכתחילה לשקע את הכיור בלילה, שמא לא יחזור וישקענו קודם עלות השחר, ואז ייפסלו מימיו.","ומקשים: והאם סבור ר' יוחנן שהכיור משוקע כל הלילה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן:\u0004 מי ש\u0003קידש ידיו\u0004 בלילה \u0003לתרומת הדשן\u0004 — \u0003למחר אין צריך לקדש, שכבר קידש מתחילת עבודה!\u0004","ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004פי שיטת \u0003רבא דמוקים לההיא\u0004 \u0005[שמעמיד את\u0006 ההלכה \u0005ההיא]\u0006 שאמר ר' יוחנן \u0003כ\u0004דעת \u0003ר'\u0004 \u0003אלעזר בר' שמעון,\u0004 הסבור שאין לינה בעמוד השחר פוסלת בקידוש ידים ורגלים, ולכן למחר אין צריך לקדש, יש לומר כי \u0003הא\u0004 \u0005[\u0006הלכה \u0005זו]\u0006 לגבי גזירת שיקוע היא \u0003כרבי,\u0004 הסבור שלינה פוסלת.","\u0003אלא לאביי דמוקים לה\u0004 \u0005[שמעמיד אותה]\u0006 את ההלכה בקידוש ידים לתרומת הדשן \u0003כ\u0004שיטת \u0003רבי,\u0004 \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003רבי\u0004 על דברי \u0003רבי, מאי שנא התם דמשקע ליה\u0004 \u0005[מה שונה שם\u0006 שהזכיר ר' יוחנן \u0005ש\u0006הוא \u0005משקע אותו,\u0006 את הכיור\u0005],\u0006 \u0003ומאי שנא הכא דלא משקע ליה\u0004 \u0005[ומה שונה כאן,\u0006 בענין הקידוש לתרומת הדשן, \u0005שלא\u0006 אמר שצריך \u0005לשקע אותו]\u0006 לאחר מכן?","ומשיבים: גם שם מדובר \u0003דמסלק ליה והדר\u0004 \u0005[שמעלה אותו\u0006 לקידוש לתרומת הדשן \u0005ואחר כך]\u0006 \u0003משקע ליה\u0004 \u0005[אותו]\u0006 עד לאחר עמוד השחר.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שחוזר ומשקעו, מה שאמר ר' יוחנן \u0003\"למחר אינו מקדש\", [אמאי\u0004 \u0005[מדוע]\u0006 אינו מקדש? והרי לא נפסלו המים! ומשיבים: אין הכוונה שלא יכול לקדש, אלא ש\u0003אין\u0004 הכהן \u0003צריך\u0004 לחזור ו\u0003לקדש]\u0004 מאחר שהתחיל בעבודת היום.","ותמהים: \u0003למימרא\u0004 \u0005[\u0006מכאן יש להסיק ו\u0005לומר]\u0006 שלדעת ר' יוחנן כיור שהעלהו בלילה (ושיקעו קודם עמוד השחר) גם \u0003ל\u0004עבודת \u0003מתירין\u0004 של היום \u0003הבא\u0004 \u0003מיחזא חזי\u0004 \u0005[ראוי\u0006 הוא\u0005]\u0006 ואין המים נפסלים לעבודת היום? אם כן, \u0003היינו\u0004 \u0005[הרי זו]\u0006 בדיוק דעתו של \u0003רב חסדא!\u0004","ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 לגבי \u0003מצות שיקוע\u0004 האם יש מצוה לשקע את הכיור בלילה או לא, שלדעת ר' יוחנן מצוה לעשות זאת, ולדעת רב חסדא לא.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דעת רב חסדא ממה ששנינו במשנה: \u0003לא היו\u0004 שאר הכהנים \u0003רואין אותו\u0004 את הכהן התורם את הדשן \u0003ולא שומעין את קולו, עד ששומעים\u0004 \u0003קול של עץ שעשה בן קטין מוכני\u0004 (מכשיר) \u0003לכיור\u0004 להורידו ולהעלותו לבור, שמפעיל אותו הכהן התורם את הדשן, \u0003והן אומרים: הגיע [עת] קידוש ידים ורגלים מן הכיור. מאי לאו דמסלק ליה\u0004 \u0005[האם לא\u0006 פירוש הדבר \u0005שמעלה אותו]\u0006 במוכני? \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003משקע ליה\u0004 \u0005[אותו]\u0006 קודם לכן, ולכן צריך עכשיו להעלותו, וקושיה היא על דעת רב חסדא, שסבור שאין מצוה לשקעו בלילה!","ודוחים: \u0003לא,\u0004 הכוונה היא ש\u0003משקע ליה\u0004 \u0005[אותו]\u0006 במוכני, כדי שלא ייפסלו מימיו בעמוד השחר. ושואלים: \u0003אי דמשקע ליה מי משתמע קליה\u0004 \u0005[אם\u0006 מדובר \u0005ש\u0006הוא \u0005משקע אותו\u0006 בלבד, \u0005האם נשמע קולו]?\u0006 והרי לשם הורדתו לבור לא היה צורך במוכני, אלא רק לשלשלו בשרשרת לבור, ולא היה זה משמיע קול! ומשיבים: על כל פנים היה \u0003משקע ליה בגילגלא\u0004 \u0005[אותו\u0006 הכהן \u0005בגלגל]\u0006 ולכן היו שומעים את קולו, או ב","\u0003לישנא אחרינא\u0004 \u0005[לשון אחרת]:\u0006 \u0003דמשקע ליה בחומרתיה, כי היכי דלישתמע קליה ולשמעי וליתי\u0004 \u0005[שמשקע אותו בגלגלו, כדי שיישמע קולו וישמעו\u0006 שאר הכהנים \u0005ויבואו]\u0006 לעבודתם. ושואלים: \u0003והא הוה\u0004 \u0005[והרי היה]\u0006 \u0003גביני\u0004 ה\u0003כרוז\u0004 שהיה מכריז באותה עת שהגיע זמן העבודה! ומשיבים: \u0003בי תרי היכרי הוו עבדי\u0004 \u0005[שני\u0006 סוגים \u0005של היכר היו עושים]\u0006 לתחילת עבודה, קול הגלגל וקול הכרוז, \u0003דשמע מהאי אתי ושמע מהאי\u0004 \u0003אתי\u0004 \u0005[ששומע מזה בא ושומע מזה בא].\u0006","\u0003גופא\u0004 \u0005[\u0006ל\u0005גופה]\u0006 של הלכה שהוזכרה לעיל (זבחים יט,ב), \u0003אמר ר' יוסי בר' חנינא: כל כיור שאין\u0004 \u0003בו\u0004 כמות מים \u0003כדי לקדש ארבעה כהנים ממנו\u0004 — \u0003אין מקדשין בו, שנאמר: \"ורחצו\u0004 \u0003ממנו משה ואהרן ובניו\" וגו'\u0004 (שמות מ, לא).","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: \u0003כל הכלים מקדשין\u0004 בהם ידים ורגלים, \u0003בין שיש בהן\u0004 כדי להכיל \u0003רביעית\u0004 הלוג מים,"],["\u0003בין שאין בהן רביעית, ובלבד שיהו\u0004 כלים אלה \u0003כלי שרת,\u0004 משמע שאין צורך בשיעור גדול כל כך!","\u0003אמר רב אדא בר אחא:\u0004 כאן מדובר \u0003בקודח בתוכו\u0004 שעושה חור בדופן הכיור ומכניס בתוכו כלי קטן, ואליו מגיעים מים מן הכיור. ומכלי כזה יכול לקדש גם אם אין בו רביעית מים, כל עוד בכיור עצמו היה השיעור הראוי לארבעה כהנים.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \"ורחצו \u0003ממנו\"\u0004 (שמות מ, לא) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 ולא מכלי אחר! ומשיבים: נאמר שם שוב \u0003\"ירחצו\"\u0004 (שמות מ, לב) לומר, בכל אופן \u0003לרבות\u0004 בכל \u0003כלי שרת.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 אם יש ריבוי, ב\u0003כלי חול נמי\u0004 \u0005[גם כן]\u0006 יקדשו! \u0003אמר אביי: כלי חול לא מצית אמרת\u0004 \u0005[אינך יכול לומר],\u0006 ודבר זה נלמד \u0003מקל וחומר מכנו\u0004 בסיסו של הכיור: \u0003ומה כנו\u0004 של הכיור, אף על פי \u0003שנמשח עמו\u0004 (שמות מ, יא) ונתקדש ככלי שרת — \u0003אינו מקדש\u0004 ממנו ידים ורגלים, \u0003כלי חול שאינו נמשח עמו\u0004 — \u0003אינו דין שאינו מקדש?\u0004","ושואלים: \u0003וכנו מנלן\u0004 \u0005[מנין לנו]\u0006 שאין מקדשים ממנו? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה אומר: יכול יהא כנו\u0004 של הכיור \u0003מקדש\u0004 לרחיצת ידים ורגלים \u0003כדרך שהכיור מקדש? תלמוד לומר:\u0004 \u0003\"ועשית כיור נחשת וכנו נחשת\"\u0004 (שמות ל, יח), \u0003לומר:\u0004 \u0003לנחשת הקשתיו\u0004 שבזה הוא דומה לכיור, \u0003ולא לדבר אחר\u0004 שאינו משמש לרחיצה כמותו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב מרי לרבינא:\u0004 כיצד אפשר להוכיח מכנו של כיור? \u0003מה לכנו ש\u0004מתחילה \u0003אין עשוי ל\u0004השתמש ב\u0003תוכו,\u0004 אלא להניח עליו את הכיור, \u0003תאמר בכלי חול שעשוי לתוכו! אלא\u0004 צריך לומר כך: נאמר \u0003\"ממנו\" למעוטי\u0004 \u0005[למעט]\u0006 \u0003כלי חול.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שנאמר \"ממנו\" למעט, \u0003כלי שרת\u0004 \u0003נמי\u0004 \u0005[גם כן]\u0006 נמעט! ומשיבים: \u0003הא רבי רחמנא\u0004 \u0005[הרי ריבתה התורה]\u0006 \u0003\"ירחצו\".\u0004","ושואלים: \u0003ומה ראית\u0004 לומר למעט זה לרבות זה? ומשיבים: \u0003זה\u0004 כלי שרת \u0003טעון\u0004 \u0003משיחה כמוהו\u0004 כמו הכיור, כפי שנצטוה משה בהקמת המשכן (שמות פרק מ), \u0003וזה\u0004 כלי חול \u0003אין טעון משיחה כמוהו.\u0004","\u0003אמר ריש לקיש: כל\u0004 \u0003המשלים למי מקוה\u0004 כלומר, כל נוזל שאינו מים, שמצטרף למי המקוה להשלים את שיעור המים שבו לארבעים סאה — \u0003משלים\u0004 גם \u0003למי כיור,\u0004 לענין שיעור המים שבו, שצריך שיהא בהם כדי לקדש ידיהם ורגליהם של ארבעה כהנים. אבל \u0003ל\u0004ענין \u0003רביעית\u0004 של נטילת ידים \u0003אינו משלים.\u0004","ושואלים: \u0003למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]?\u0006 מה הוא המשלים למקוה שאינו ראוי לנטילת ידים? \u0003אילימא\u0004 \u0003למעוטי\u0004 \u0005[אם תאמר\u0006 שבא \u0005למעט]\u0006 \u0003טיט הנדוק\u0004 טיט שנעשה דליל כל כך עד שאפשר לשפוך אותו — לא ניתן להסביר כך, שכן \u0003היכי דמי\u0004 \u0005[כיצד\u0006 מדובר \u0005בדיוק]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 זה טיט ש\u0003פרה שוחה\u0004 (מתכופפת) \u0003ושותה ממנו,\u0004 הרי הוא כמים ממש, ו\u0003אפילו לרביעית נמי\u0004 \u0005[גם כן]\u0006 יוכשר! \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003אין פרה שוחה ושותה ממנו, אפילו למקוה נמי\u0004 \u0005[גם כן]\u0006 \u0003אין משלים!\u0004","\u0003אלא\u0004 תאמר שבא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003יבחושין אדומין\u0004 שנוצרים וגדלים במים — אלה \u0003אפילו בעינייהו נמי\u0004 \u0005[בעינם,\u0006 בפני עצמם, \u0005גם כן]\u0006 כשרים למקוה, ולא רק כהשלמה למים, \u0003דהא תניא\u0004 \u0005[שהרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003רבן שמעון בן גמליאל אומר: כל\u0004 דבר \u0003שתחילת ברייתו מן המים\u0004 — \u0003מטבילין בו,\u0004 שדינו כמים. \u0003ו\u0004כן \u0003אמר רב יצחק בר אבדימי: מטבילין\u0004 אפילו \u0003בעינו של דג\u0004 שנימוקה ונעשתה נוזלית, אם היא גדולה מספיק!","\u0003אמר רב פפא:\u0004 בא הדבר \u0003למעוטי\u0004 \u0005[למעט]\u0006 מקרה ש\u0003נתן\u0004 לתוך המקוה \u0003סאה\u0004 של מי פירות \u0003ונטל סאה\u0004 ממימיו. וכפי \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003מקוה שיש\u0004 \u0003בו ארבעים סאה מכוונות\u0004 (בדיוק), שהוא שיעור מקוה כשר, \u0003נתן\u0004 בתוכו \u0003סאה\u0004 של מי פירות \u0003ונטל\u0004 ממנו \u0003סאה\u0004 אחרת — \u0003הרי\u0004 \u0003זה כשר,\u0004 שאנו אומרים שמה שנכנס למקוה בטל בו, והמקוה נשאר כשר. \u0003ואמר\u0004 \u0003רב יהודה בר שילא אמר רב אסי אמר ר' יוחנן:\u0004 וכך הוא יכול לעשות \u0003עד\u0004 שמי הפירות הללו נעשים \u0003רובו\u0004 של מקוה. מה שאין כן לענין נטילת ידים, אין רביעית מים מבטלת מי פירות שנפלו לתוכה, ואם חזר ונטל מן הרביעית כשיעור מי הפירות שנפלו לתוכה — שוב אינו יכול ליטול בהם ידים.","ועוד דמיון בין מי כיור ומי מקוה, \u0003אמר רב פפא: אם קדח בו\u0004 חור בכותל מקוה, ועשה בו חלל כדי שיעור \u0003רביעית\u0004 — \u0003מטבילין בו\u0004 בחלל הזה כלים קטנים, כגון \u0003מחטין וצינוריות,\u0004 למרות שהמים עומדים שם לעצמם, \u0003הואיל ו\u0004אותה רביעית \u0003מהכשירה\u0004 של \u0003מקוה\u0004 \u0003אתיא\u0004 \u0005[באה],\u0006 וכדרך שנאמר לעיל בענין כיור.","ועוד בענין מי מקוה ומי כיור, \u0003אמר ר' ירמיה אמר ריש לקיש: מי מקוה כשירים למי כיור.\u0004","ושואלים: \u0003למימרא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 שמי הכיור \u0003לא מים חיים נינהו\u0004 \u0005[הם]?\u0006 שאין צורך למלא הכיור ממי מעין? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 נאמר לגבי עבודת הקרבן: \"וקרבו וכרעיו ירחץ במים\" (ויקרא א, ט) וכוונתו להדגיש: \u0003\"במים\"\u0004 — \u0003ולא ביין, \"במים\"\u0004 — \u0003ולא ב\u0004יין \u0003מזוג, \"במים\"\u0004 — \u0003לרבות שאר מים\u0004 שאינם מים חיים, \u0003וקל וחומר למי כיור\u0004 שהם ראויים לרחיצת קרבי הקרבן. \u0003מאי\u0004 \u0005[מהו]\u0006 ה\u0003קל וחומר למי כיור? לאו\u0004 \u0005[האם לא]\u0006 משום ש\u0003מים חיים נינהו\u0004 \u0005[הם]?\u0006","ודוחים: \u0003לא,\u0004 הקל וחומר מבוסס על כך שהם מים \u0003דקדיש\u0004 \u0005[שקדשו]\u0006 בכיור לשם עבודה. ותוהים: \u0003וקדישי מעליותא היא\u0004 \u0005[ו\u0006מה שהם \u0005קדושים,\u0006 שהמים קרויים מי כיור, \u0005עילוי הוא]\u0006 במקום שהצריכה התורה מים? \u0003והא תנא\u0004 \u0005[והרי שנה]\u0006 \u0003ר' שמואל: \"מים\"\u0004 שהוזכרו בכתוב הם מים \u0003שאין להם שם לווי,\u0004 כלומר שהם נקראים רק מים,"],["\u0003יצאו מי כיור\u0004 שאינם ראויים להשתמש בהם כמים, מפני \u0003שיש להם שם לווי! אלא לאו\u0004 \u0005[האם לא]\u0006 נלמד מכאן כי מה שלמדו קל וחומר למי כיור אינו למי כיור עצמם, אלא למים ש\u0003ראויין למי כיור, אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003מים חיים נינהו\u0004 \u0005[הם]\u0006 מי כיור!","ומשיבים: \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בענין זה, ש\u0003אומר ר' יוחנן: מי כיור\u0004 — \u0003ר' ישמעאל\u0004 \u0003אומר: מי מעין הן\u0004 כלומר, מים חיים, \u0003וחכמים אומרים: שאר מימות הן,\u0004 ולאו דווקא מי מעין.","שנינו במשנה ש\u0003ערל\u0004 פוסל את העבודה. ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שערל פסול? \u0003אמר רב חסדא: דבר זה מתורת משה רבינו לא למדנו,\u0004 שאינו מפורש בתורה, אלא \u0003מדברי\u0004 הנביא \u0003יחזקאל בן בוזי למדנו,\u0004 שנאמר: \u0003\"כל בן נכר ערל לב וערל בשר לא יבא אל מקדשי\"\u0004 (יחזקאל מד, ט).","ושואלים: \u0003ומנלן דמחלי\u0004 \u0005[ומנין לנו ש\u0006הם \u0005מחללים]\u0006 \u0003עבודה?\u0004 ומשיבים, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בהביאכם בני נכר ערלי לב וערלי בשר להיות במקדשי לחלל את ביתי\"\u0004 (יחזקאל מד, ז).","ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר שם \u0003\"בן נכר\", יכול בן נכר ממש\u0004 כלומר, גוי? \u0003תלמוד לומר: \"ערל לב\".\u0004 ואם כן, לא משום שהוא בן נכר הוא נפסל, אלא מדובר בכהן. \u0003אם כן, מה תלמוד לומר \"בן נכר\"?\u0004 כוונתו \u0003שנתנכרו מעשיו לאביו שבשמים\u0004 כלומר, משומד, שעובר עבירות באופן קבוע. \u0003ואין לי אלא ערל לב\u0004 שהוא פסול, \u0003ערל בשר\u0004 כהן שלא נימול, \u0003מנין\u0004 שהוא פוסל? \u0003תלמוד לומר: \"וערל בשר\".\u0004","ומעירים: \u0003וצריכי\u0004 \u0005[וצריך]\u0006 שייאמרו שני הדברים, \u0003דאי כתב רחמנא\u0004 \u0005[שאילו היתה כותבת התורה]\u0006 רק \u0003\"ערל בשר\"\u0004 הייתי אומר שהוא פסול \u0003משום דמאיס\u0004 \u0005[ש\u0006הוא \u0005מאוס]\u0006 משום שיש לו עורלה, \u0003אבל ערל לב דלא מאיס\u0004 \u0005[שאינו מאוס]\u0006 בגופו, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יהא פסול. \u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 רק ב\u0003ערל\u0004 \u0003לב,\u0004 הייתי אומר שהוא פסול \u0003משום\u0004 ש\u0003אין לבו לשמים, אבל ערל בשר\u0004 ש\u0003לבו\u0004 \u0003לשמים אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יהיה פסול, לכן \u0003צריכי\u0004 \u0005[צריך]\u0006 שייאמרו שניהם.","שנינו במשנה ש\u0003טמא פסול\u0004 ופוסל את העבודה. \u0003אמרו זקני דרום: לא\u0004 \u0003שנו אלא טמא שרץ\u0004 שנטמא מחמת שרץ וכיוצא בו, \u0003אבל\u0004 כהן \u0003טמא מת, מתוך\u0004 \u0003שמרצה בציבור\u0004 שאם רוב הציבור טמא מת נעשית עבודת קרבנות הציבור לכתחילה בכהן טמא — \u0003מרצה נמי\u0004 \u0005[גם כן]\u0006 \u0003ב\u0004קרבן \u0003יחיד.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003טמא שרץ נמי ליתי\u0004 \u0005[גם כן\u0006 ש\u0005יבוא\u0006 ויילמד\u0005]\u0006 שהוא מרצה בציבור לכתחילה (ומשם נלמד שהוא מרצה על היחיד בדיעבד) \u0003בקל וחומר מטמא מת:\u0004 \u0003מה טמא מת ש\u0004הוא טמא שבעת ימים, ו\u0003טעון\u0004 לטהרתו \u0003הזאה\u0004 של מי פרה אדומה ביום ה\u0003שלישי ו\u0004ביום \u0003ה\u0004\u0003שביעי\u0004 — \u0003מרצה, טמא שרץ\u0004 שטומאתו קלה, \u0003שאינו טעון הזאה שלישי ושביעי,\u0004 אלא טובל בו ביום וטהור בערב — \u0003אינו דין שמרצה?\u0004","ומשיבים: \u0003קסברי\u0004 \u0005[סבורים]\u0006 \u0003זקני דרום\u0004 כי לענין היתר עבודת קרבנות הציבור בטומאה יש ללמוד דין ה\u0003מכפרין\u0004 (הכהנים המקריבים את הקרבן) \u0003כ\u0004דין ה\u0003מתכפרין.\u0004 ולפיכך, \u0003מה מתכפרין\u0004 כלומר, הציבור, דווקא כשהוא \u0003טמא מת\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 מקריבים את קרבנו, אבל אם היה רוב הציבור \u0003טמא שרץ\u0004 — \u0003לא, אף\u0004 לגבי \u0003מכפרין\u0004 (הכהנים) הדין כן, \u0003טמא מת\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 מקריב קרבנות הציבור כשהם באים בטומאה, \u0003טמא שרץ\u0004 — \u0003לא.\u0004","בעקבות תשובה זו, המניחה שקרבן ציבור אינו קרב כשהיה הציבור טמא שרץ, שואלים: \u0003מאי קסברי\u0004 \u0005[מה הם סבורים]\u0006 זקני דרום? \u0003אי קסברי\u0004 \u0005[אם הם סבורים]:\u0006 \u0003אין שוחטין וזורקין\u0004 את דם הפסח \u0003על\u0004 יחיד שהוא \u0003טמא שרץ,\u0004 אף שלערב יהיה טהור ויוכל לאכול ממנו, \u0003אמאי\u0004 \u0003לא עבדי\u0004 \u0005[מדוע אין עושים]\u0006 \u0003ציבור בטומאה\u0004 זו? \u0003הא\u0004 \u0005[הרי]\u0006 כלל הוא, ש\u0003כל שביחיד נדחה\u0004 ועושה פסח שני, \u0003ציבור עבדי\u0004 \u0005[עושים\u0006 אותו\u0005]\u0006 \u0003בטומאה!\u0004","\u0003אלא\u0004 מכאן ש\u0003קסברי\u0004 \u0005[סבורים הם]\u0006 שאכן \u0003שוחטין וזורקין על\u0004 יחיד שהוא \u0003טמא שרץ,\u0004 ואינו נדחה לפסח שני. וממילא גם ציבור אינו עושה אותו בטומאה.","\u0003אמר\u0004 \u0003עולא,\u0004 על כך \u0003תקע להו\u0004 \u0005[צעק להם]\u0006 \u0003ריש לקיש לדרומאי\u0004 \u0005[לדרומיים]:\u0006 לפי שיטתכם, \u0003וכי איזה כח מרובה\u0004 לדחות את הטומאה, \u0003כח מכפרין או כח מתכפרין? הוי אומר: כח מתכפרין,\u0004 שהרי שוחטים את הפסח על יחיד טמא שרץ, ומצד שני כהן טמא שרץ אינו מרצה.","אבל לפי הנחה זו יש לדחות את עיקר דבריכם בדרך קל וחומר: \u0003ומה במקום שנטמאו בעלים\u0004 עצמם \u0003בשרץ משלחין\u0004 הם את \u0003קרבנותיהן\u0004 — \u0003כהן שנטמא בשרץ אינו מרצה,\u0004 \u0003מקום שנטמאו בעלים במת, שאין\u0004 הם \u0003משלחין קרבנותיהן, כהן שנטמא במת אינו דין שאינו מרצה?\u0004 והרי זה סותר את דבריהם בפירוש המשנה, שכהן טמא מת מרצה!","ומשיבים: \u0003קסברי\u0004 \u0005[סבורים]\u0006 \u0003זקני דרום\u0004 כי \u0003טמא מת [נמי\u0004 \u0005[גם כן]\u0006\u0003] משלח קרבנותיו,\u0004 אף שאינו יכול לאכול מקרבן הפסח.","ומקשים: \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"איש איש כי יהיה טמא... ועשה פסח... בחדש\u0004 \u0003השני\" וגו'\u0004 (במדבר ט, י— יא), משמע שהטמא אינו יכול לעשותו בראשון כלל! ומשיבים: דבר זה נאמר \u0003למצוה\u0004 שלכתחילה צריך להמתין עד לפסח שני, אבל בדיעבד אם שלח הטמא את קרבנו — הרי הוא מרצה, ואינו חייב להביא פסח שני.","ומקשים: \u0003והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"איש\u0004"],["\u0003לפי אכלו\u0004 תכוסו על השה\" (שמות יב, ד) שניתן לשחוט רק על מי שראוי לאכול את הפסח (\"לפי אוכלו\")! ומשיבים: לדעתם דבר זה הוא \u0003למצוה,\u0004 אבל לא בדיעבד.","ושואלים: \u0003ולעכובי\u0004 \u0005[ולעכב]\u0006 בדיעבד \u0003לא? והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"במכסת נפשות\"\u0004 (שמות יב, ד) \u0003מלמד שאין הפסח נשחט אלא\u0004 \u0003למנוייו,\u0004 לאלה שנימנו עליו מראש. \u0003שחטו שלא למנוייו יכול יהא\u0004 רק \u0003כעובר\u0004 \u0003על המצוה,\u0004 אבל בכל זאת יהא הקרבן כשר? \u0003תלמוד לומר: \"תכסו\"\u0004 (שמות יב, ד) \u0003הכתוב שנה עליו\u0004 חזר על אותה מלה (\"במכסת... תכוסו\") \u0003לעכב,\u0004 שאם נשחט שלא למנויים \u0003—\u0004 פסול. \u0003ואיתקש\u0004 \u0005[ו\u0006הרי בפסוק זה \u0005הוקשו]\u0006 \u0003אוכלין\u0004 (\"לפי אוכלו\") \u0003למנויין\u0004 (\"במכסת נפשות\"), נמצא שאם שחטו עבור מי שאינו יכול לאוכלו — לא עלה לו!","ומשיבים: \u0003זקני דרום לא מקשי\u0004 \u0005[אינם מקישים\u0006 היקש זה\u0005].\u0006 ושואלים: \u0003וכי לא מקשי נמי\u0004 \u0005[וכאשר אינם מקישים גם כן],\u0006 והם סבורים שרק לכתחילה אין שוחטים על טמא מת, \u0003מהא נמי אית להו פירכא\u0004 \u0005[מזו גם כן יש להם פירכה],\u0006 שיש לטעון: \u0003ומה במקום שנטמאו בעלים בשרץ שמשלחין קרבנותיהם לכתחילה\u0004 — \u0003כהן שנטמא בשרץ אינו מרצה, מקום שנטמאו בעלים במת, שאין משלחין קרבנותיהן לכתחילה, כהן שנטמא במת אינו דין שאינו מרצה?\u0004","ועוד, \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על זקני דרום מן המשנה בפסחים: \u0003מפני שאמרו נזיר ועושה פסח\u0004 — \u0003הציץ\u0004 של כהן גדול \u0003מרצה על טומאת דם\u0004 הקרבן \u0003ואין הציץ מרצה על טומאת הגוף\u0004 של האדם.","ונברר: \u0003במאי\u0004 \u0005[במה]\u0006 מדובר? \u0003אילימא\u0004 \u0005[אם\u0006 \u0003תאמר]\u0004 שנטמאו הבעלים \u0003בטומאת שרץ\u0004 — \u0003האמרת\u0004 \u0005[הרי אמרת]\u0006 שלשיטת זקני דרום \u0003שוחטין וזורקין על\u0004 מי שנטמא ב\u0003טומאת שרץ! אלא\u0004 הכוונה היא שנטמאו הבעלים \u0003טומאת מת,\u0004 \u0003וקתני\u0004 \u0005[ושנה]:\u0006 \u0003אין הציץ מרצה. אלמא\u0004 \u0005[מכאן]\u0006 שאם \u0003נטמאו בעלים במת\u0004 — \u0003אין משלחין קרבנותיהם!\u0004","ודוחים: \u0003לא, אי דאיטמו\u0004 \u0005[אם שנטמאו]\u0006 \u0003בעלים במת\u0004 — \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 יהא הציץ מרצה, אבל \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003כגון שנטמא\u0004 ה\u0003כהן\u0004 המקריב \u0003בשרץ.\u0004","ומקשים: \u0003אי הכי, אימא סיפא\u0004 \u0005[אם כך\u0006 אתה מפרש את המשנה, \u0005אמור\u0006 את \u0005סופה]\u0006: \u0003ניטמא טומאת התהום\u0004 (טומאה שלא היתה ידועה כלל בשעה שנטמא בה, כגון שהיתה מוסתרת מן העין) — \u0003הציץ מרצה,\u0004 וכי יכול אתה לפרש כך? \u0003הא\u0004 \u0003תני\u0004 \u0005[הרי שנה]\u0006 \u0003ר' חייא: לא אמרו\u0004 דין \u0003טומאת התהום\u0004 שהציץ מרצה עליה \u0003אלא ל\u0004ענין טומאת \u0003מת בלבד,\u0004 ונדייק: \u0003למת למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]?\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 בא הדבר \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003טומאת התהום\u0004 של \u0003שרץ\u0004 שאין הציץ מרצה עליה?","ודוחים: \u0003לא, למעוטי\u0004 \u0005[למעט]\u0006 \u0003טומאת התהום\u0004 של \u0003זיבה,\u0004 שבטומאה זו אין ריצוי ציץ. אבל על טומאת התהום של שרץ — מרצה.","ושואלים: \u0003ואלא הא דבעי\u0004 \u0005[\u0006שאלה \u0005זו ששאל]\u0006 \u0003רמי בר חמא: כהן המרצה\u0004 המקריב \u0003בקרבנותיהם\u0004 של נזיר או עושה הפסח, האם \u0003הותרה לו טומאת התהום\u0004 אם נטמא בה \u0003או לא הותרה לו טומאת התהום? תפשוט\u0004 \u0005[תפתור]\u0006 מכאן ש\u0003טומאת התהום הותרה לו, דהא הכא\u0004 \u0005[שהרי כאן],\u0006 לפי מה שפירשנו לדעת זקני דרום, \u0003בכהן קיימינא\u0004 \u0005[עומדים\u0006 עוסקים \u0005אנו]!\u0006","ומשיבים: דבריו של \u0003רמי בר חמא ודאי פליגי\u0004 \u0005[חלוקים],\u0006 שהוא אינו הולך בשיטתם בפירוש משנה זו.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ראיה לענין זה. נאמר בציץ של כהן גדול: \u0003\"ונשא אהרן את עון הקדשים\"\u0004 (שמות כח, לח). ומבררים בברייתא: \u0003וכי איזהו עון נושא\u0004 הכהן?"],["\u0003אם עון פיגול\u0004 — \u0003הרי כבר נאמר: \"לא יחשב\"\u0004 (ויקרא ז, יח), משמע שאין לו תקנה! \u0003אם עון נותר\u0004 — \u0003הרי כבר נאמר: \"לא ירצה\"\u0004 (ויקרא ז, יח)!","\u0003הא אינו נושא\u0004 הציץ \u0003אלא עון טומאה,\u0004 ומסתבר כי על עוון זה מכפר הציץ על היחיד, \u0003ש\u0004כבר \u0003הותרה\u0004 טומאה \u0003מכללה בצבור.\u0004","ונברר: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003טומאה?\u0004 באיזו טומאה מדובר שהציץ מרצה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003מטומאת שרץ, היכא אישתרי\u0004 \u0005[היכן הותרה]\u0006 בציבור? \u0003אלא\u0004 ודאי מדובר ב\u0003טומאת מת, ולאו\u0004 \u0005[והאם לא]\u0006 \u0003כגון שנטמאו בעלים במת? אלמא\u0004 \u0005[מכאן]\u0006 שאם \u0003נטמאו בעלים במת\u0004 — \u0003משלחין קרבנותיהן\u0004 שהרי הציץ מרצה עליהם.","ונברר: \u0003ובמאי\u0004 \u0005[ובמה]\u0006 באיזה קרבן מדובר? \u0003אי\u0004 \u0005[אם]\u0006 \u0003בנזיר,\u0004 הלוא \u0003\"וכי ימות מת עליו\u0004 בפתע פתאום וטמא ראש נזרו\" (במדבר ו, ח) \u0003אמר\u0004 \u0003רחמנא\u0004 \u0005[אמרה התורה],\u0006 שבכל מקרה שהוא טמא, גם באונס, אינו יכול להביא קרבן נזירות עד שיטהר מטומאתו! \u0003אלא\u0004 בהכרח הכוונה היא \u0003לעושה פסח,\u0004 ומכאן שטמא מת יכול לשלח את קרבן הפסח שלו, וכדברי זקני דרום, ושלא כדברי רמי בר חמא! \u0003(ולאו כגון שנטמאו בעלים במת).\u0004","ודוחים: \u0003לעולם\u0004 אפשר לפרש שהציץ מרצה במקרה שנטמאו הבעלים \u0003בשרץ\u0004 ולא במת. \u0003ו\u0004אין לסתור זאת ממה שנאמר בתור ראיה לכך, שטומאה הותרה בציבור, והרי דין זה אינו אלא בטומאת מת, משום שאין הכוונה אלא ל\u0003שם טומאה בעולם\u0004 ענין טומאה בכללו, שמצאנו שהותר בציבור.","\u0003ואיכא דדייק ומייתי\u0004 \u0003הכי\u0004 \u0005[ויש שמדייק\u0006 מלשון הכתוב בענין ציץ \u0005ומביא כך]\u0006 ראיה לצד ההפוך: \"ונשא אהרן את עוון הקדשים\" (שמות כח, לח), \u0003עון הקדשים\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 מכפר, \u0003עון מקדישין\u0004 (כלומר, טומאתם של המקריבים) — \u0003לא,\u0004 ונברר \u0003מאי\u0004 \u0005[באיזו]\u0006 \u0003טומאה\u0004 מדובר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003טומאת שרץ, מי\u0004 \u0003אישתריא\u0004 \u0005[האם הותרה]\u0006 \u0003בציבור? אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר ב\u0003טומאת מת,\u0004 \u0003ועון קדשים אין\u0004 \u0005[כן]\u0006 מרצה הציץ, \u0003עון מקדישים לא,\u0004 ושלא כדברי זקני דרום, הסבורים שטמא מת משלח קרבנותיו!","ומשיבים: \u0003לעולם\u0004 יכול אחד לפרש שטומאה שהציץ מרצה עליה (ולא על המקריב) היא \u0003טומאת שרץ, ו\u0004אולם אין זה משום שהיא עצמה הותרה בציבור, אלא משום שמצאנו שהותר \u0003שם טומאה בעולם\u0004 בטמא מת.","שנינו במשנה כי העובד \u0003יושב\u0004 פוסל את העבודה. ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003אמר רבא אמר רב נחמן,\u0004 משום ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 לגבי הכהנים: \"כי בו בחר ה' אלקיך מכל שבטיך \u0003לעמד לשרת\u0004 בשם ה'\" (דברים יח, ה), \u0003לעמידה בחרתיו ולא\u0004 \u0003לישיבה,\u0004 שרק בדרך זו נבחר הכהן לשרת.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר \u0003\"לעמד לשרת\"\u0004 הרי זו \u0003מצוה\u0004 לעשות את עבודת הקודש בעמידה, \u0003כשהוא אומר:\u0004 \"ככל אחיו הלויים \u0003העמדים\u0004 שם לפני ה'\" (דברים יח, ז) — \u0003שנה עליו הכתוב\u0004 במצות העבודה, כדי לומר שהוא \u0003לעכב,\u0004 שאם לא עמד הרי הוא פוסל.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב\u0004 \u0003נחמן: מכדי\u0004 \u0005[הרי]\u0006 \u0003יושב כזר דמי\u0004 \u0005[נחשב]\u0006 \u0003ומחיל\u0004 \u0005[ומחלל]\u0006 את ה\u0003עבודה, אימא\u0004 \u0005[אמור]:\u0006 \u0003מה זר\u0004 שעבד — עונשו \u0003במיתה\u0004 בידי שמים, \u0003אף יושב\u0004 יהיה עונשו \u0003במיתה, אלמה\u0004 \u0003תניא\u0004 \u0005[מדוע שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אבל ערל, אונן, יושב\u0004 שעבדו במקדש \u0003—\u0004 \u0003אינן במיתה אלא\u0004 \u0003באזהרה\u0004 (באיסור לא תעשה)?","ומשיבים: \u0003משום דהוי\u0004 \u0005[שהיו]\u0006 גם כהן \u0003מחוסר בגדים ו\u0004גם כהן \u0003שלא רחוץ\u0004 \u0003ידים ורגלים שני כתובין הבאין כאחד,\u0004 שבשניהם נאמר שהכהן שעשה זאת — חייב מיתה,"],["\u0003וכל שני כתובים הבאין כאחד\u0004 שנאמר בשניהם פרט היכול להילמד מאחד מהם על \u0003האחר —\u0004 \u0003אין מלמדין\u0004 על אחרים דין זה בבנין אב, ולכן אין למדים מכאן ששאר הדברים המחללים עבודה חייב עליהם מיתה.","\u0003ולמאן דאמר\u0004 \u0005[ו\u0006גם \u0005ל\u0006דעת \u0005מי שאומר]\u0006 ששני כתובים הבאים כאחד \u0003מלמדין,\u0004 מכל מקום \u0003שתויי יין\u0004 שגם בהם נאמר שהם חייבים מיתה, \u0003הוה ליה\u0004 \u0005[הריהו]\u0006 כתוב \u0003שלישי,\u0004 \u0003ושלשה\u0004 כתובים הבאים כאחד \u0003לדברי הכל אין מלמדין.\u0004","שנינו במשנה, שלא יושב בלבד פסול בעבודה, אלא גם \u0003עומד על גבי כלים, על גבי בהמה, על גבי רגלי חבירו\u0004 — \u0003פסול.\u0004 ומבררים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 דבר זה? \u0003דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005בבית\u0006 מדרשו\u0003]\u0004 של \u0003ר' ישמעאל: הואיל ורצפה\u0004 של העזרה \u0003מקדשת\u0004 את הכהן לעבוד עליה, \u0003וכלי שרת\u0004 (בגדי כהונה) גם הם \u0003מקדשים,\u0004 יש ללמוד מזה על זה: \u0003מה כלי\u0004 \u0003שרת\u0004 הלכה היא ש\u0003לא יהא דבר חוצץ בינו\u0004 בין הכהן \u0003לבין כלי שרת, אף רצפה\u0004 — \u0003לא יהא דבר\u0004 \u0003חוצץ בינו לבין הרצפה.\u0004","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 שייאמרו כל הפרטים הללו במשנה, שהם חוצצים, שאי אפשר ללמוד זה מזה, \u0003דאי אשמעינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 רק \u0003כלי,\u0004 היינו אומרים שהוא חוצץ \u0003משום דלאו מינא\u0004 \u0005[ש\u0006כלים \u0005לא ממין]\u0006 של \u0003בשר נינהו\u0004 \u0005[הם],\u0006 \u0003אבל בהמה דמינא\u0004 \u0005[שמין]\u0006 של \u0003בשר\u0004 הכהן \u0003הוא, אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 תיחשב חציצה. \u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 רק ב\u0003בהמה,\u0004 היינו אומרים כי היא חוצצת משום \u0003דלא מינא\u0004 \u0005[שלא ממין]\u0006 של \u0003אדם הוא, אבל חבירו\u0004 ש\u0003אדם הוא, אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 תהא חציצה, לכן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו כולם. ומעתה דנים בפרטי הלכה זו.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר\u0004 \u0003אומר: רגלו אחת\u0004 של הכהן \u0003על הכלי ורגלו אחת על הרצפה,\u0004 וכן \u0003רגלו אחת על האבן\u0004 (שאינה מאבני הרצפה) \u0003ורגלו אחת על הרצפה\u0004 — \u0003רואין, כל שאילו ינטל הכלי\u0004 או \u0003תנטל האבן יכול\u0004 הכהן עדיין \u0003לעמוד על רגלו אחת ויעבוד\u0004 — הרי \u0003עבודתו כשירה, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003עבודתו פסולה.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' אמי:\u0004 אם \u0003נדלדלה האבן\u0004 של הרצפה, שאינה מחוברת היטב ומתנדנדת, \u0003ועמד\u0004 \u0003עליה, מהו\u0004 הדין? ומסבירים: \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003אין דעתו\u0004 לשוב ו\u0003לחברה\u0004 את האבן הזו לרצפה — \u0003לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך,\u0004 ש\u0003ודאי חייצא\u0004 \u0005[חוצצת]\u0006 שהרי היא כחפץ זר, \u0003כי תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 זה באבן ש\u0003דעתו לחברה, מאי\u0004 \u0005[מה]\u0006 הדין? האם \u0003כיון\u0004 ש\u0003דעתו לחברה כמה דמחברא דמיא\u0004 \u0005[כמו שמחוברת\u0006 היא \u0005נחשבת],\u0006 \u0003או\u0004 \u0003דילמא השתא מיהא הא תלישא\u0004 \u0005[שמא עכשיו על כל פנים הרי\u0006 היא \u0005תלושה]?\u0006","\u0003רבה זוטי בעי לה הכי\u0004 \u0005[היה שואל את השאלה הזו כך],\u0006 בנוסח הבא: \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' אמי:\u0004 \u0003נעקרה האבן\u0004 ממקומה \u0003ועמד במקומה\u0004 של האבן, בגומה שנוצרה ברצפה, \u0003מהו?\u0004","ותמהים על הצגה זו של השאלה: \u0003מאי קא מיבעיא\u0004 \u0003ליה\u0004 \u0005[מה\u0006 שאלה \u0005נשאלה לו]?\u0006 האם \u0003כי קדיש\u0004 \u0005[כאשר קידש]\u0006 \u0003דוד\u0004 המלך את מקום המקדש \u0003רצפה עליונה קדיש\u0004 \u0005[קידש],\u0006 ומה שמתחת לזה אינו מקודש, \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003עד לארעית דתהומא קדיש\u0004 \u0005[לתחתית התהום קידש]?\u0006 אם כן הוא — \u0003ותיבעי\u0004 \u0003ליה\u0004 \u0005[ותישאל לו]\u0006 שאלה זו לגבי \u0003כל העזרה כולה,\u0004 מה יהא דינה אם ניטלה כל הרצפה!","ומשיבים: \u0003לעולם פשיטא\u0004 \u0003ליה דעד ארעית דתהומא קדיש\u0004 \u0005[פשוט לו שעד לתחתית התהום קידש],\u0006 והקדושה אמנם קיימת גם מתחת לרצפה. \u0003ו\u0004אולם \u0003הכי קמיבעיא ליה\u0004 \u0005[כך נשאלה לו]:\u0006 האם כאשר עומד הכהן בגומה שברצפה \u0003דרך שירות בכך, או אין דרך שירות בכך?\u0004 שאלה זו לא נפתרה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","שנינו במשנה \u0003קיבל בשמאל\u0004 — \u0003פסול, ור' שמעון מכשיר. תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 נאמר: \"ולקח הכהן מדם החטאת באצבעו ונתן על קרנות מזבח העולה\" (ויקרא ד, כה), והואיל ואנו למדים מגזירה שווה כי כל מקום שנאמר אצבע הכוונה לימין (כמבואר להלן) הרי מה שנאמר: \u0003\"באצבעו ולקח\"\u0004 (כלומר, \"ולקח... באצבעו\"), ולקיחה זו קבלת הדם בכלי היא — \u0003מלמד שלא תהא קבלה\u0004 של הדם \u0003אלא\u0004 ביד \u0003ימין,\u0004 ומה שנאמר \u0003\"באצבעו ונתן\" מלמד שלא תהא נתינה אלא בימין.\u0004","\u0003אמר ר' שמעון: וכי\u0004 \u0003נאמרה יד בקבלה? אלא\u0004 נאמר רק \u0003\"באצבעו ונתן\"\u0004 — \u0003שלא תהא נתינה אלא בימין, הואיל ולא נאמרה\u0004 במפורש \u0003יד בקבלה,\u0004 אם \u0003קיבל בשמאל\u0004 — \u0003כשר.\u0004","ושואלים: \u0003ור' שמעון ממה נפשך\u0004 \u0005[מה רצונך]?\u0006 כיצד הוא תופס את הדברים? \u0003אי אית ליה\u0004 \u0005[אם יש לו]\u0006 הוא מקבל אותה \u0003גזירה שוה\u0004 מפרשת מצורע (ויקרא יד), לכל מקום שנאמר אצבע או יד, שאינה אלא ימין, \u0003כי\u0004 \u0005[גם אם]\u0006 \u0003לא נאמרה יד בקבלה מאי הוי\u0004 \u0005[מה בכך]?\u0006 הרי הוזכרה אצבע! \u0003ואי לית ליה\u0004 \u0005[ואם אין לו]\u0006 \u0003גזירה שוה\u0004 זו, \u0003כי\u0004 \u0005[גם אם]\u0006 \u0003נאמרה יד בקבלה מאי הוי\u0004 \u0005[מה בכך]?\u0006 הרי רק ממה שנזכרה יד אינו יודע באיזו יד יקבל!","\u0003אמר רב יהודה: לעולם לית ליה\u0004 \u0005[אין לו]\u0006 \u0003גזירה שוה\u0004 זו, \u0003והכי קאמר\u0004 \u0005[וכך אמר]:\u0006 \u0003וכי נאמר יד ימין בקבלה? הואיל ולא נאמר יד ימין בקבלה,\u0004 אם \u0003קבל בשמאל\u0004 — \u0003כשר.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה: אי הכי\u0004 \u0005[אם כך],\u0006 שאתה סבור שהוא מדייק ממה שלא נאמר ימין, \u0003אפילו נתינה נמי\u0004 \u0005[גם כן]\u0006 צריך היה ר' שמעון להכשיר בשמאל, שהרי גם בה לא נאמר ימין! \u0003ועוד, וכי לית\u0004 \u0003ליה\u0004 \u0005[והאם אין לו]\u0006 \u0003לר' שמעון גזירה שוה\u0004 זו? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון אומר: כל מקום שנאמר\u0004 בעבודת המקדש \u0003\"יד\"\u0004 — \u0003אינה אלא\u0004 יד \u0003ימין, \"אצבע\"\u0004 — \u0003אינה אלא\u0004 אצבע \u0003ימין!\u0004","\u0003אלא אמר רבא: לעולם אית ליה\u0004 \u0005[יש לו]\u0006 \u0003גזירה\u0004 \u0003שוה, והכי קאמר\u0004 \u0005[וכך הוא אומר]:\u0006 \u0003וכי נאמרה יד בקבלה? הואיל ולא נאמרה יד בקבלה אלא אצבע, ואי אפשר לקבלה\u0004 שתיעשה \u0003באצבע\u0004 בלבד, חייבים אנו לומר שאין \"באצבעו\" מתייחס כלל לקבלת הדם, אלא לנתינה (\"באצבעו ונתן\"), ולכן אם \u0003קיבל בשמאל\u0004 — \u0003כשר.\u0004","על הסבר זה \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב סמא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אשי לרבינא:\u0004 הרי \u0003איפשר דעביד ליה\u0004 \u0005[שיעשה לו]\u0006 \u0003אזן לשפת מזרק, ו\u0004כשהוא מחזיק את אוזן הכלי באצבעו \u0003מקבל בה\u0004 את הדם. ואם כן, אין זו טענה!","\u0003אלא\u0004 יש לומר כמו ש\u0003אמר אביי:\u0004"],["\u0003ב\u0004שאלה אם \u0003מקרא נדרש לפניו ולאחריו קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 שלדעת ר' שמעון המקרא נדרש דווקא לאחריו, ולכן הוא מפרש ש\"אצבעו\" נאמר לענין נתינה בלבד. ואילו חכמים סבורים שהמקרא נדרש גם לפניו, ולכן לא רק \"ונתן\" אלא גם \"ולקח\" (קבלת הדם) צריכים להיות בימין. ומביאים דעה נוספת בענין זה.","\u0003אמר אביי: הא\u0004 \u0005[זו]\u0006 שאמר \u0003ר' אלעזר בר' שמעון, מפקא מדאבוה ומפקא מדרבנן\u0004 \u0005[מוציאה מ\u0006דברי \u0005אביו ומוציאה מ\u0006דברי \u0005חכמים],\u0006 שהיא שיטה נוספת. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אלעזר בר' שמעון אומר: כל מקום שנאמר אצבע בקבלה\u0004 ולא בנתינה, אם \u0003שינה בקבלה\u0004 ועשאה בשמאל — \u0003פסול,\u0004 אבל אם שינה \u0003בנתינה\u0004 — \u0003כשר. וכל מקום שנאמר אצבע בנתינה,\u0004 בא ללמד שדווקא \u0003אם שינה בנתינה\u0004 בשמאל — \u0003פסול,\u0004 אבל אם שינה \u0003בקבלה\u0004 — \u0003כשר.\u0004","\u0003והיכן נאמר אצבע בנתינה? דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ולקחת מדם הפר ונתת על קרנת המזבח באצבעך\"\u0004 (שמות כט, יב). \u0003ומעירים:\u0004 \u0003וקסבר\u0004 \u0005[וסבור הוא]:\u0006 \u0003מקרא נדרש לפניו, ולא\u0004 נדרש \u0003לפני פניו\u0004 כלומר, למה שאינו כתוב ממש לפניו בסמוך לו, \u0003ו\u0004אף אינו נדרש \u0003לאחריו.\u0004","\u0003אמר רבה בר בר חנה אמר ר' יוחנן: כל מקום שנאמר אצבע וכהונה אינה אלא אצבע ימין.\u0004","ותחילה מעירים: \u0003קא סלקא דעתין תרתי בעינן\u0004 \u0005[עלה על דעתנו\u0006 שאת \u0005שניהם\u0006 יחד \u0005צריכים אנו],\u0006 \u0003כדכתיב\u0004 \u0005[כמו שנאמר]\u0006 למשל בפסוק: \u0003\"ולקח הכהן מדם החטאת באצבעו\"\u0004 (ויקרא ד, כה). \u0003ויליף\u0004 \u0005[ונלמד]\u0006 דבר זה בגזירה שווה \u0003ממצורע, דכתיב\u0004 \u0005[שנאמר]\u0006 בו הדבר במפורש: \u0003\"וטבל הכהן את אצבעו הימנית\"\u0004 (ויקרא יד, טז). ומקשים: \u0003והרי קמיצה,\u0004 ש\u0003לא כתיב\u0004 \u0005[נאמר]\u0006 \u0003בה אלא כהונה,\u0004 ולא נאמר אצבע, \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003קמץ בשמאל\u0004 — \u0003פסול!\u0004","\u0003אלא אמר רבא:\u0004 צריך להבין כי הכוונה היא לכל מקום שנאמר בו אחד הדברים, \u0003או אצבע או כהונה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: הרי הולכת אברים\u0004 של קרבן התמיד \u0003לכבש\u0004 המזבח, להניחם שם לצורך הקטרה, \u0003דכתיב בהו\u0004 \u0005[שנאמר בהם]\u0006 רק \u0003כהונה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והקריב הכהן את הכל [והקטיר] המזבחה\"\u0004 (ויקרא א, יג), \u0003ואמר מר\u0004 \u0005[החכם]:\u0006 \"והקריב\" \u0003זו הולכת אברים לכבש, ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 כיצד מוליכים את האיברים? \u0003הרגל של ימין בשמאלו ובית עורה\u0004 (הצד בו מצוי העור, ולא מקום החתך) פונה \u0003לחוץ.\u0004 הרי שלמרות שכתוב שם כהונה עושים זאת בשמאל!","ומשיבים: \u0003[כי אמרינן\u0004 \u0005[כאשר אנו אומרים]\u0006\u0003] או אצבע או כהונה\u0004 — \u0003בדבר המעכב כפרה\u0004 אנו אומרים, \u0003דומיא\u0004 \u0005[בדומה]\u0006 להזאה על ה\u0003מצורע,\u0004 והולכת אברים אינה מעכבת כפרה.","ומקשים: \u0003והרי קבלה\u0004 של הדם בכלי, \u0003דכתב בהו\u0004 \u0005[שנאמר בהם]\u0006 \u0003כהונה, ודבר המעכב בכפרה הוא, ותנן\u0004 \u0005[ושנינו\u0006 במשנתנו\u0005]:\u0006 \u0003קבל בשמאל\u0004 — \u0003פסול, ור' שמעון מכשיר.\u0004 וכיצד אתה מיישב את שיטת ר' שמעון?","ומשיבים: \u0003ר' שמעון תרתי בעי\u0004 \u0005[שתים\u0006 הוא \u0005מצריך],\u0006 גם אצבע וגם כהונה.","ושואלים: \u0003מי בעי\u0004 \u0005[האם מצריך]\u0006 \u0003ר' שמעון תרתי\u0004 \u0005[שתים]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון אומר: כל מקום שנאמר יד\u0004 — \u0003אינו אלא ימין, אצבע\u0004 — \u0003אינו אלא ימין,\u0004 ואינו מזכיר כהונה!","ומשיבים: במקום שנאמר \u0003אצבע לא בעיא\u0004 \u0005[אינו צריך]\u0006 שיהיה כתוב \u0003כהונה,\u0004 אבל אם כתוב \u0003כהונה\u0004 בלבד \u0003בעיא\u0004 \u0005[צריך]\u0006 שיהיה כתוב \u0003אצבע\u0004 כדי לומר שאינו אלא ימין.","ושואלים: \u0003ואלא\u0004 לדעת ר' שמעון, \u0003כהן\u0004 שנזכר במיוחד לענין קבלה \u0003למה לי\u0004 שייכתב? הרי לדעתו קבלה כשירה בשמאל! ומשיבים: ללמד שהכהן יהיה \u0003בכיהונן,\u0004 כשהוא לבוש בגדי כהונה (ראה לעיל זבחים יז,א).","ושואלים: \u0003והרי זריקה\u0004 ש\u0003לא כתב בהו\u0004 \u0005[נאמר בהם]\u0006 \u0003אלא כהונה\u0004 ולא אצבע, \u0003ותנן\u0004 \u0005[ושנינו]:\u0006 \u0003זרק בשמאל\u0004 — \u0003פסול, ולא פליג\u0004 \u0005[חלק]\u0006 \u0003ר' שמעון\u0004 על כך, משמע שלדעתו עצם המילה כהונה מספיקה!","\u0003אמר אביי:\u0004 אף שלא נזכרה מחלוקת במשנה \u0003פליג\u0004 \u0005[חולק\u0006 הוא\u0005]\u0006 באמת \u0003בברייתא, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003קיבל בשמאל\u0004 — \u0003פסול, ור' שמעון מכשיר. זרק בשמאל\u0004 — \u0003פסול, ור' שמעון מכשיר.\u0004","ומקשים: \u0003אלא הא\u0004 \u0005[זו]\u0006 ש\u0003אמר רבא\u0004 לענין הכתובים היתרים בפרשת המצורע: נאמר \u0003\"יד\"\u0004 לגזירה שווה, ללמד על \u0003\"יד\" לקמיצה\u0004 של המנחות שתהא נעשית ביד ימין, \u0003\"רגל\" \"רגל\" ל\u0004למד על \u0003חליצה,\u0004 שחולצת היבמה את הנעל מרגלו הימנית של היבם, \u0003\"אזן\" \"אזן\"\u0004 — \u0003ל\u0004למד על \u0003רציעה\u0004 של אוזנו של עבד עברי שאינו רוצה לצאת לחפשי, שתהא זאת אזנו הימנית. ויש לשאול: \u0003למה לי\u0004 גזירה שווה זו לענין קמיצה? הרי \u0003מ\u0004דברי \u0003רבה בר בר חנה נפקא\u0004 \u0005[יוצא\u0006 הדבר\u0005]\u0006 שהרי נאמרה שם כהונה, ולמדים מכאן שהיא ימין!","ומשיבים: \u0003חד\u0004 \u0005[\u0006פסוק \u0005אחד]\u0006 נאמר \u0003ל\u0004צורך קמיצת ה\u0003קומץ\u0004 מתוך המנחה, שתיעשה ביד ימין, \u0003וחד\u0004 \u0005[ו\u0006פסוק \u0005אחד]\u0006 \u0003לקידוש קומץ\u0004 להכנסת הקומץ לתוך כלי שרת, שגם זה צריך להיעשות בימין."],["ושואלים: \u0003ול\u0004דעת \u0003ר' שמעון\u0004 ש\u0003לא בעי\u0004 \u0005[מצריך]\u0006 \u0003קידוש קומץ\u0004 המנחה בכלי, אלא מוליכו בידו למזבח, \u0003ו\u0004כן \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי \u0003לר' שמעון נמי בעי\u0004 \u0005[גם כן צריך]\u0006 \u0003קידוש קומץ,\u0004 אבל \u0003ב\u0004יד \u0003שמאל אכשורי מכשר\u0004 \u0005[מכשיר],\u0006 אם כן, הלימוד ממצורע \u0003\"יד\" \"יד\"\u0004 של \u0003רבא למה לי?\u0004","\u0003אי\u0004 \u0005[אם]\u0006 \u0003לקמיצה עצמה\u0004 שתהיה ביד ימין — \u0003מ\u0004דברי \u0003רב יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא נפקא\u0004 \u0005[יוצא],\u0006 ש\u0003אמר רב יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' שמעון\u0004 שהכשיר הקטרת קומץ שלא בכלי שרת? \u0003[\u0004ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 לגבי מנחה\u0003]: \"קדש קדשים היא כחטאת וכאשם\"\u0004 (ויקרא ו, י), לומר כי יש לדמותה הן לחטאת והן לאשם:","אם \u0003בא לעובדה\u0004 להקטיר את קומצה \u0003ביד\u0004 — \u0003עובדה בימין כ\u0004דין הזאת דם של \u0003חטאת\u0004 שנעשית ביד ימין, ואם \u0003בא לעובדה בכלי\u0004 שמכניס את הקומץ לכלי שרת — \u0003עובדה ב\u0004יד \u0003שמאל כ\u0004דרך שעושה בזריקת דם ה\u0003אשם\u0004 שהיא בכלי. והרי קמיצה נעשית ביד, ואם כן מן ההיקש לחטאת למדנו שהיא נעשית בימין!","ומשיבים: \u0003לא נצרכא\u0004 \u0005[נצרכה]\u0006 גזירה שווה זו של רבא \u0003[אלא] לקומץ\u0004 של \u0003מנחת חוטא.\u0004 שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ואמר ר' שמעון\u0004 שאין מנחת חוטא טעונה שמן ולבונה, כמו כל מנחה, כדי \u0003שלא יהא קרבנו\u0004 של חוטא \u0003מהודר,\u0004 אם כן, \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003קמץ לה בשמאל נמי תיתכשר\u0004 \u0005[גם כן תהא כשרה],\u0006 \u0003קא\u0004 \u0003משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאינה כשירה אלא בימין.","השוחט את הזבח, וקודם שהספיק לקבלו בכלי \u0003נשפך הדם על הרצפה, ואספו\u0004 מן הרצפה לכלי — \u0003פסול.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 מה שנאמר: \u0003\"ולקח הכהן המשיח מדם הפר\"\u0004 (ויקרא ד, ה), ולא \"מדמו\", בא להדגיש: \u0003מדם הנפש\u0004 של הפר, הדם המקלח מוורידי הצוואר, בו יוצאת נפשו, \u0003ולא מדם העור, ולא מדם התמצית\u0004 הדם שמתמצה מורידי הצואר לאחר הקילוח של דם הנפש.","ומוסיפים ואומרים: ומה שנאמר: \u0003\"מדם הפר\"\u0004 — כוונתו כאילו היה כתוב: \u0003דם מהפר יקבלנו\u0004 וכדין משנתנו, שאם נשפך הדם לרצפה — שוב אינו כשר. ומסבירה הגמרא: \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לפרש \u0003\"מדם הפר\" כדכתיב\u0004 \u0005[כמו שכתוב]\u0006 לפי פשוטו: \u0003\"מדם\" ואפילו מקצת דם\u0004 — \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב:\u0004 \u0003השוחט צריך שיקבל את כל דמו של פר, שנאמר: \"ואת כל דם הפר ישפך\"\u0004 (ויקרא ד, ז)!","\u0003אלא \"מדם הפר\"\u0004 כוונתו: \u0003דם מהפר יקבלנו,\u0004 כאילו עברה האות מ' למלה \"הפר\". \u0003וקסבר\u0004 \u0005[וסבור הוא]\u0006 התנא, כי במדרש הכתובים \u0003גורעין\u0004 ממלה אחת אות \u0003ומוסיפין\u0004 אותה למלה אחרת, \u0003ודורשין\u0004 כאילו כך היה כתוב.","\u0003גופא\u0004 \u0005[לגופה]\u0006 של הלכה שהזכרנו, \u0003אמר רב יהודה אמר רב: השוחט צריך\u0004 \u0003שיקבל את כל דמו של פר, שנאמר: \"ואת כל דם הפר ישפך\"\u0004 (ויקרא ד, ז). ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003בשיריים כתיב\u0004 \u0005[נאמר]\u0006 דבר זה, במה שנותר לאחר שנזרק הדם, ולא בקבלת הדם!","ומשיבים: \u0003אם\u0004 \u0003אינו ענין לשיריים, דהא ליתיה לכוליה\u0004 \u0005[שהרי איננו לכל]\u0006 ה\u0003דם,\u0004 שכן מקצתו כבר נזרק על המזבח, \u0003תניהו ענין בקבלה.\u0004","\u0003אמר רב יהודה אמר שמואל: השוחט\u0004 את הזבח \u0003צריך שיגביה סכין\u0004 של שחיטה \u0003למעלה\u0004 לאחר השחיטה, כדי שלא יזל הדם מן הסכין אל תוך הכלי, \u0003שנאמר: \"ולקח מדם הפר\", ולא מדם הפר ודבר\u0004 \u0003אחר\u0004 (דם הסכין).","ושואלים: \u0003ודם\u0004 שעל ה\u0003סכין במאי\u0004 \u0005[במה]\u0006 הוא \u0003מקנח ליה\u0004 \u0005[אותו]?\u0006 \u0003אמר אביי:\u0004 מקנח אותו \u0003בשפת\u0004 ה\u0003מזרק, כדכתיב\u0004 \u0005[כמו שנאמר]:\u0006 \u0003\"כפורי זהב\"\u0004 (עזרא א, י) והם מזרקי הדם, ונקראו בשם זה משום שבהם מכפרים (מנגבים) את הדם.","\u0003אמר רב חסדא אמר רב\u0004 \u0003ירמיה בר אבא: השוחט צריך שיתן\u0004"],["\u0003ורידין\u0004 של הקרבן \u0003לתוך הכלי,\u0004 כדי שכל הדם ייכנס לתוכו. \u0003איתמר נמי\u0004 \u0005[נאמר גם כן],\u0006 \u0003אמר רב אסי אמר ר' יוחנן: ורידין צריך שיראו אויר כלי.\u0004","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' אסי מר' יוחנן: היה מקבל\u0004 את הדם \u0003ונפחתו\u0004 \u0003שולי\u0004 ה\u0003מזרק\u0004 כלומר, נשברה תחתיתו \u0003עד שלא הגיע דם לאויר\u0004 המזרק, \u0003מהו?\u0004 וצדדי השאלה: האם דבר הנמצא ב\u0003אויר\u0004 (של כלי) באופן \u0003שאין סופו לנוח,\u0004 כגון כאן שהדם אינו יכול לנוח בכלי, שהרי נפחתו שוליו, הריהו \u0003כמונח דמי\u0004 \u0005[נחשב],\u0006 כאילו נכנס הדם תחילה בכלי ואחר כך נשפך ממנו, והוא כשר לזריקה כשיאספהו מן הרצפה. \u0003או לא כמונח דמי\u0004 \u0005[נחשב]\u0006 והריהו כדם שנשפך מן הצואר לרצפה ופסול?","\u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003תניתוה\u0004 \u0005[\u0006כבר \u0005שניתם אותה]\u0006 בהלכה אחרת, ביחס לקידוש מי חטאת: \u0003חבית\u0004 \u0003שמונחת תחת הזינוק\u0004 צינור המקלח מים למרחוק — \u0003מים ש\u0004נכנסו \u0003בתוכה\u0004 של החבית, \u0003ושבחוצה לה\u0004 מעל פיה — \u0003פסולין\u0004 למי חטאת, משום שהם נחשבים כמונחים בחבית, ושוב אין הם עוד \"מים חיים\". אבל אם \u0003צירף\u0004 (חיבר) \u0003פיה\u0004 של החבית \u0003לזינוק\u0004 — \u0003מים שבתוכה פסולין,\u0004 \u0003ו\u0004אולם אלו \u0003שבחוצה לה\u0004 מעל פיה \u0003כשירין,\u0004 משום שהם עדיין חלק מן הקילוח, ואינם נחשבים כמצויים באויר החבית. על כל פנים, משמע מכאן שדבר המצוי באויר הכלי נחשב כמונח בכלי.","ותוהים: \u0003האי מאי\u0004 \u0005[זה מהו]?\u0006 הרי \u0003בעי מיניה\u0004 \u0005[שאל אותו]\u0006 ר' אסי שאלה ביחס ל\u0003אויר שאין סופו לנוח,\u0004 כשנפחתו שולי המזרק, \u0003וקא פשט ליה\u0004 \u0005[ופתר לו\u0006 בעיה\u0005]\u0006 ב\u0003אויר שסופו לנוח,\u0004 שהרי חבית זו שלימה היא, והמים עתידים להישאר בתוכה!","ומשיבים: \u0003תרתי קא בעי מיניה\u0004 \u0005[שתי\u0006 שאלות \u0005שאל ממנו]\u0006 ר' אסי מר' יוחנן, האחת — מה דינו של אויר שאין סופו לנוח, והשניה — גם \u0003אם תימצי\u0004 \u0005[תמצא]\u0006 \u0003לומר: אויר שאין סופו לנוח לאו\u0004 \u0005[אינו]\u0006 \u0003כמונח דמי\u0004 \u0005[נחשב],\u0006 \u0003אויר\u0004 \u0003שסופו לנוח מאי\u0004 \u0005[מה]\u0006 דינו? ופתר לו בעיה זו.","ומוסיפים: \u0003רב יוסף מתני הכי\u0004 \u0005[היה שונה כך]\u0006 את הדיון הזה, כמו שאמרנו, שאת השאלה לגבי מזרק פתר ר' יוחנן מחבית. ואילו \u0003רב כהנא מתני\u0004 \u0005[היה שונה\u0006 אחרת\u0005]:\u0006 בענין \u0003חבית\u0004 עצמה \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 ר' אסי, האם נפסלים המים באויר שחוצה לה, \u0003ופשט ליה\u0004 \u0005[ופתר לו]\u0006 ר' יוחנן מן הברייתא בענין \u0003חבית,\u0004 שר' אסי לא ידעה.","\u0003רבה מתני\u0004 \u0005[היה שונה]:\u0006 בענין \u0003חבית בעא מיניה\u0004 \u0005[שאל אותו]\u0006 ר' אסי, \u0003ופשט ליה\u0004 \u0005[ופתר לו]\u0006 ר' יוחנן מדין \u0003מזרק,\u0004 וכך פתר לו: \u0003אי\u0004 \u0005[וכי אין]\u0006 \u0003אתה מודה במזרק\u0004 שמקבל בו את דם הקרבן, \u0003שאי איפשר לו בלא זינוק?\u0004 שאי אפשר שיגיע הדם במישרין לתחתית המזרק, ובהכרח הוא מגיע תחילה לאויר שמעל המזרק ומשם נשפך לתוכו. ומכאן אתה למד שדבר המגיע לאוירו של כלי הרי הוא כמונח בתוכו. ולכן מים שזינקו מול חבית — פסולים למי חטאת.","ועוד בענין זה \u0003תנן התם\u0004 \u0005[שנינו שם]:\u0006 \u0003נתן ידו או רגלו או עלי ירקות כדי שיעברו\u0004 על ידם \u0003מים\u0004 חיים \u0003לחבית\u0004 שמקדש בה המים — הרי הם \u0003פסולין,\u0004 משום שהעבירם על ידי דבר המקבל טומאה, נתן שם \u0003עלי קנים ועלי אגוזים\u0004 שאינם מקבלים טומאה — \u0003כשירה.\u0004 \u0003זה הכלל:\u0004 אם הועברו המים על ידי \u0003דבר המקבל טומאה\u0004 — \u0003פסולין,\u0004 על ידי \u0003דבר שאינו מקבל טומאה\u0004 — \u0003כשירין.\u0004","ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 ומשיבים: ש\u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' יוסי בר אבא, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"אך מעין ובור\u0004 \u0003מקוה מים יהיה טהור\"\u0004 (ויקרא יא, לו), ש\u0003הוייתן\u0004 כלומר יצירתם של הבור והמקוה \u0003על ידי טהרה תהא,\u0004 ואם הגיעו לשם על ידי דבר שמקבל טומאה — אין זו יצירה על ידי טהרה.","\u0003אמר ר' חייא אמר ר' יוחנן: זאת אומרת\u0004 ממשנה זו יש ללמוד ש\u0003אויר\u0004 שמעל ה\u0003כלי ככלי דמי\u0004 \u0005[נחשב],\u0006 שאם לא כן מדוע נפסלו המים כשהעבירם בידו? והרי המים מגיעים תחילה לאוירה של החבית, שאינו מקבל טומאה, ורק אחר כך נכנסים בתוכה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לר' חייא בר אבא: ודילמא\u0004 \u0005[ושמא]\u0006 מדובר שם \u0003בשותת,\u0004 שהיו המים החיים שותתים מידו ישירות לתוך החבית, ולא עברו כלל באוירה! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תרדא\u0004 \u0005[שוטה],\u0006 \"נתן ידו או רגלו \u0003כדי שיעברו מים לחבית\" תנן\u0004 \u0005[שנינו],\u0006 ובאופן זה המים אינם שותתים, אלא באים בקילוח, ואם כן בוודאי עברו תחילה באוירה של החבית.","\u0003ואמר ר' חייא בר אבא אמר ר' יוחנן: מעדותו של ר' צדוק נישנית משנה זו\u0004 בחבית, \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנתנו\u0005]\u0006 במסכת עדויות: \u0003העיד ר' צדוק על הזוחלין\u0004 מים הזורמים על גבי קרקע ממקום למקום, \u0003שקילחן\u0004 שעשה בהם מעין צינור מקלח \u0003בעלי אגוזין\u0004 — \u0003שהן כשירין. זה\u0004 \u0003היה מעשה\u0004 כך נעשה \u0003ב\u0004עיר \u0003אוהלייא, ובא מעשה לפני חכמים בלשכת הגזית\u0004 שבבית המקדש \u0003והכשירו\u0004 אותו.","\u0003אמר ר' זירא אמר רבי: הצורם\u0004 (חותך מקצת) \u0003אזן הפר\u0004 לאחר שחיטה, ועשה בו מום, \u0003ואחר כך קיבל דמו\u0004 של הפר — \u0003פסול, שנאמר: \"ולקח\u0004 הכהן המשיח \u0003מדם הפר\"\u0004 (ויקרא ד, ה), לומר: \u0003פר שהיה כבר,\u0004 שלא השתנה במשך הזמן מן השחיטה ועד לקבלת הדם.","ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 הלכה זו ב\u0003קדשי קדשים,\u0004 שהרי פר זה הוא פר חטאת של כהן משיח, ב\u0003קדשים קלים\u0004 \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שכך הוא גם כן?","\u0003אמר רבא, תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 נאמר בקרבן הפסח \u0003\"שה תמים זכר בן שנה\u0004 יהיה לכם\" (שמות יב, ה), לומר: \u0003שיהא תמים ובן שנה בשעת שחיטה. ב\u0004שעת \u0003קבלה, ב\u0004שעת \u0003הולכה,\u0004 בשעת \u0003זריקה מנין\u0004 שצריך להישאר תמים? \u0003תלמוד לומר: \"יהיה\",\u0004 לומר, \u0003כל הוייותיו\u0004 שעושים בו בקודש \u0003לא יהיו אלא\u0004 כשהוא \u0003תם ובן שנה.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 לרבא ממה ששנינו בברייתא, \u0003ר' יהושע אומר: כל הזבחים שבתורה, שנשתייר\u0004 \u0003מהן כזית בשר או כזית חלב\u0004 והשאר הלך לאיבוד — \u0003זורק\u0004 עליהם \u0003את הדם.\u0004 משמע שאף כשנחסר עיקרו של הקרבן עדיין ראוי הוא לזריקה!","ומשיבים: \u0003תרגומא\u0004 \u0005[תרגם,\u0006 הסבר אותה\u0005]\u0006 שדבר זה נאמר דווקא על \u0003בן שנה\u0004 האמור שם, שהכבש צריך להישאר בן שנה עד לגמר הזריקה, אבל לא לענין \"תמים\".","ושואלים: \u0003ומי איכא מידי\u0004 \u0005[והאם יש דבר]\u0006 ש\u0003בשעת שחיטה\u0004 היה \u0003בן שנה,\u0004 ו\u0003בשעת הולכה וזריקה\u0004 הינו \u0003בן שתים?\u0004","\u0003אמר רבא: זאת אומרת\u0004 ש\u0003שעות פוסלות בקדשים,\u0004 ולכן יכול להיות שעברה שנתו בדיוק באותו זמן שבין שחיטה והולכה.","ועוד בענין זה מביאים מה ש\u0003אמר ר' אמי אמר ר' אלעזר: היא בפנים\u0004 היתה בהמת הקרבן עומדת בתוך העזרה \u0003ורגליה\u0004 נמצאות \u0003בחוץ,\u0004 אם \u0003חתך\u0004 את \u0003הרגלים\u0004 \u0003ואחר כך שחט\u0004 את הבהמה — הרי היא \u0003כשירה\u0004 כקרבן, משום שכל הדם שנכנס למזרק היה מן הדם שבתוך העזרה."]]};
